class _SafeTicker:
    """Wraps yf.Ticker to silently handle Yahoo 401 errors"""
    def __init__(self, ticker, *args, **kwargs):
        self._ticker = ticker
        self._obj = None
        try:
            self._obj = _yf_original.Ticker(ticker, *args, **kwargs)
        except:
            pass
    def history(self, *args, **kwargs):
        if not self._obj: return None
        try: return self._obj.history(*args, **kwargs)
        except Exception as e:
            if '401' in str(e) or 'Unauthorized' in str(e) or 'Crumb' in str(e): pass
            return None
    @property
    def info(self):
        if not self._obj: return {}
        try: return self._obj.info or {}
        except: return {}
    @property
    def income_stmt(self):
        if not self._obj: return None
        try: return self._obj.income_stmt
        except: return None
    @property
    def balance_sheet(self):
        if not self._obj: return None
        try: return self._obj.balance_sheet
        except: return None
    @property
    def cashflow(self):
        if not self._obj: return None
        try: return self._obj.cashflow
        except: return None
    @property
    def financials(self):
        if not self._obj: return None
        try: return self._obj.financials
        except: return None
    @property
    def options(self):
        if not self._obj: return ()
        try: return self._obj.options
        except: return ()
    def option_chain(self, *args, **kwargs):
        if not self._obj: return None
        try: return self._obj.option_chain(*args, **kwargs)
        except: return None
    def __getattr__(self, name):
        if self._obj:
            try: return getattr(self._obj, name)
            except: pass
        return None

class _SafeYF:
    """Drop-in replacement for yfinance module"""
    Ticker = _SafeTicker
    @staticmethod
    def Tickers(tickers_str, *args, **kwargs):
        try: return _yf_original.Tickers(tickers_str, *args, **kwargs)
        except: return None
    def __getattr__(self, name):
        return getattr(_yf_original, name)

