# ═══ WEBSOCKET — Live price updates to all connected clients ═══
_ws_clients = set()

@app.websocket("/ws/prices")
async def websocket_prices(websocket: WebSocket):
    """Live price feed via WebSocket — pushes updates every 30s"""
    await websocket.accept()
    _ws_clients.add(websocket)
    print(f"🔌 WebSocket client connected ({len(_ws_clients)} total)")
    try:
        while True:
            # Keep connection alive — also accept client messages
            data = await websocket.receive_text()
            # Client can send "subscribe:RELIANCE,TCS" etc
            if data.startswith("subscribe:"):
                symbols = data.replace("subscribe:", "").split(",")
                websocket._custom_subs = [s.strip().upper() for s in symbols if s.strip()]
    except WebSocketDisconnect:
        _ws_clients.discard(websocket)
        print(f"🔌 WebSocket client disconnected ({len(_ws_clients)} total)")
    except:
        _ws_clients.discard(websocket)

async def _ws_broadcast_loop():
    """Push price updates to all WebSocket clients every 30s"""
    global _ws_clients
    import json as _json
    await asyncio.sleep(10)  # Wait for initial prefetch
    while True:
        try:
            if _ws_clients:
                prices = {}
                for key, entry in _smart_cache.items():
                    if key.startswith("price:") and time.time() - entry['ts'] < entry['ttl']:
                        ticker = key.replace("price:", "")
                        prices[ticker] = entry['data']
                
                if prices:
                    payload = _json.dumps({"type": "prices", "data": prices, "ts": int(time.time())})
                    dead = set()
                    for ws in _ws_clients.copy():
                        try:
                            await ws.send_text(payload)
                        except:
                            dead.add(ws)
                    if dead:
                        _ws_clients = _ws_clients - dead
                        print(f"🔌 Cleaned {len(dead)} dead WebSocket connections")
        except Exception as e:
            print(f"⚠️ WS broadcast error: {e}")
        await asyncio.sleep(30)

