def _resolve_instrument(symbol, region="IN"):
    """Resolve a symbol to its yfinance ticker and metadata."""
    is_us = str(region).upper() == "US"
    sym = str(symbol).upper().strip()
    if is_us:
        return {"yf": sym, "symbol": sym, "region": "US"}
    if not sym.endswith(".NS") and not sym.endswith(".BO"):
        yf_sym = sym + ".NS"
    else:
        yf_sym = sym
    return {"yf": yf_sym, "symbol": sym, "region": "IN"}


