_premium_sessions = {}  # {email: {ts, verified}}

@app.post("/api/auth/verify")
async def verify_premium(request: Request):
    """Server-side premium email verification — prevents client-side bypass"""
    try:
        data = await request.json()
        email = (data.get("email", "")).strip().lower()
        if not email or "@" not in email:
            return {"success": False, "premium": False, "error": "Invalid email"}
        
        is_premium = email in [e.lower() for e in TRADES_ALLOWED_EMAILS]
        is_dream = email in [e.lower() for e in DREAM_ALLOWED_EMAILS]
        is_trading_only = email in [e.lower() for e in TRADING_ONLY_EMAILS]
        
        # Cache session for 24 hours
        _premium_sessions[email] = {"ts": time.time(), "verified": is_premium or is_dream or is_trading_only, "dream": is_dream, "trading_only": is_trading_only}
        
        # Cleanup old sessions
        if len(_premium_sessions) > 1000:
            cutoff = time.time() - 86400
            expired = [k for k, v in _premium_sessions.items() if v["ts"] < cutoff]
            for k in expired: del _premium_sessions[k]
        
        return {
            "success": True, "premium": is_premium or is_dream or is_trading_only, "email": email,
            "dreamAccess": is_dream,
            "tradingOnly": is_trading_only,
            "features": {
                "trading": is_premium or is_dream,
                "smartTrades": is_premium or is_dream,
                "journal": is_premium or is_dream,
                "aiAssist": is_premium or is_dream,
                "stockIntel": is_premium or is_dream,
                "valuation": is_premium or is_dream,
                "backtest": is_premium or is_dream,
                "dreamPortfolio": is_dream,
                "multibaggerHunter": is_dream,
            }
        }
    except Exception as e:
        return {"success": False, "premium": False, "error": str(e)}

def _is_premium_email(email: str) -> bool:
    """Check if email is premium — from session cache or direct check"""
    email = email.strip().lower()
    if email in _premium_sessions:
        session = _premium_sessions[email]
        if time.time() - session["ts"] < 86400:
            return session["verified"]
    return email in [e.lower() for e in TRADES_ALLOWED_EMAILS]
