@app.get("/api/paper-journal")
async def paper_journal(region: str = "IN", limit: int = 50):
    """Auto paper-trading journal + stats.
    
    Returns: {
      enabled: bool (is CELESYS_AUTO_PAPER=1),
      region: "IN"|"US",
      stats: {wins, losses, win_rate, by_state: {...}},
      open: [<trades>],          // currently open shadow trades
      closed: [<trades>],         // recent N closed trades (limit)
      total_in_journal: int,
    }
    """
    reg = region.upper()
    if reg not in ("IN", "US"):
        return {"success": False, "error": "region must be IN or US"}
    
    journal = _auto_paper_journal.get(reg) or []
    open_trades = [t for t in journal if t.get("status") == "OPEN"]
    closed_trades = [t for t in journal if t.get("status") != "OPEN"]
    # Sort closed by close-ts descending (most recent first)
    closed_trades = sorted(
        closed_trades,
        key=lambda t: t.get("closed_ts") or 0,
        reverse=True,
    )[:max(1, min(limit, 200))]
    
    return {
        "success": True,
        "enabled": _auto_paper_enabled(),
        "region": reg,
        "stats": _auto_paper_stats(reg),
        "open": open_trades,
        "closed": closed_trades,
        "total_in_journal": len(journal),
        "ts": time.time(),
    }


def _auto_scan_boot():
    import threading
    def _bg():
        time.sleep(15)
        print("[BOTTOM-NAV] 🚀 Boot scan starting...")
        try: diag_log("SYSTEM", "boot_scan_starting", {"delay_sec": 15})
        except Exception: pass
        _run_bottom_nav_scan("IN")
        _run_bottom_nav_scan("US")
        print("[BOTTOM-NAV] 🚀 Boot scan done")
        try: diag_log("SYSTEM", "boot_scan_done", {})
        except Exception: pass
    threading.Thread(target=_bg, daemon=True).start()
_auto_scan_boot()


@app.get("/api/participant-oi")
async def participant_oi():
    """Fetch participant-wise open interest data from NSE (Client/FII/DII/Pro)."""
    try:
        # Cache for 10 minutes
        if _participant_oi_cache["data"] and time.time() - _participant_oi_cache["time"] < 600:
            return _participant_oi_cache["data"]
        
        import requests as req
        s = req.Session()
        hdr = {"User-Agent": "Mozilla/5.0", "Accept": "application/json", "Referer": "https://www.nseindia.com/"}
        s.get("https://www.nseindia.com/", headers=hdr, timeout=6)
        
        # Participant-wise trading volumes (OI data)
        resp = s.get("https://www.nseindia.com/api/reports?archives=[%22fo%22,%22cat%22]", headers=hdr, timeout=8)
        
        result = {"success": False, "participants": {}, "summary": ""}
        
        if resp.status_code == 200:
            data = resp.json()
            participants = {}
            
            for entry in (data if isinstance(data, list) else data.get("data", [])):
                cat = entry.get("clientType", "").strip()
                if not cat:
                    continue
                
                fut_long = float(entry.get("futIdxLong", 0) or 0) + float(entry.get("futStkLong", 0) or 0)
                fut_short = float(entry.get("futIdxShort", 0) or 0) + float(entry.get("futStkShort", 0) or 0)
                opt_ce_long = float(entry.get("optIdxCallLong", 0) or 0) + float(entry.get("optStkCallLong", 0) or 0)
                opt_ce_short = float(entry.get("optIdxCallShort", 0) or 0) + float(entry.get("optStkCallShort", 0) or 0)
                opt_pe_long = float(entry.get("optIdxPutLong", 0) or 0) + float(entry.get("optStkPutLong", 0) or 0)
                opt_pe_short = float(entry.get("optIdxPutShort", 0) or 0) + float(entry.get("optStkPutShort", 0) or 0)
                
                net_fut = fut_long - fut_short
                net_opt = (opt_ce_long - opt_ce_short) + (opt_pe_long - opt_pe_short)
                
                participants[cat] = {
                    "futLong": fut_long, "futShort": fut_short, "futNet": net_fut,
                    "optCeLong": opt_ce_long, "optCeShort": opt_ce_short,
                    "optPeLong": opt_pe_long, "optPeShort": opt_pe_short,
                    "optNet": net_opt,
                    "bias": "BULLISH" if (net_fut + net_opt) > 0 else "BEARISH"
                }
            
            # Generate summary
            fii = participants.get("FII", participants.get("FPI", {}))
            client = participants.get("Client", {})
            pro = participants.get("Pro", participants.get("PROP", {}))
            
            summary_parts = []
            if fii:
                summary_parts.append(f"FII: {'Bullish' if fii.get('bias') == 'BULLISH' else 'Bearish'} (Fut net: {fii.get('futNet', 0):,.0f})")
            if client:
                summary_parts.append(f"Client: {'Bullish' if client.get('bias') == 'BULLISH' else 'Bearish'}")
            if pro:
                summary_parts.append(f"Pro: {'Bullish' if pro.get('bias') == 'BULLISH' else 'Bearish'}")
            
            result = {
                "success": True,
                "participants": participants,
                "summary": " | ".join(summary_parts),
                "fii_bias": fii.get("bias", "NEUTRAL") if fii else "NEUTRAL",
                "smart_money_signal": fii.get("bias", "NEUTRAL") if fii else "NEUTRAL",
                "timestamp": time.strftime("%H:%M IST")
            }
            
            _participant_oi_cache["data"] = result
            _participant_oi_cache["time"] = time.time()
            print(f"📊 Participant OI: {result['summary']}")
        
        return result
    except Exception as e:
        print(f"❌ Participant OI error: {e}")
        return {"success": False, "error": str(e), "participants": {}}


# Gift Nifty cache — 5 min
_gift_nifty_cache = {"data": None, "time": 0}

@app.get("/api/gift-nifty")
async def gift_nifty():
    """Pre-market indicator for India — Gift Nifty + global cues."""
    try:
        import yfinance as yf
        import time as _time
        
        # Check cache (5 min)
        if _gift_nifty_cache["data"] and (_time.time() - _gift_nifty_cache["time"]) < 300:
            cached = _gift_nifty_cache["data"].copy()
            cached["_cached"] = True
            return cached
        
        _t0 = _time.time()
        
        # Fetch multiple signals in parallel
        # Gift Nifty proxy: Nifty futures, US futures, Asia ETFs
        symbols = {
            "nifty_close": "^NSEI",       # Nifty 50 (last close)
            "nifty_fut": "NIFTY_FUT.NS",  # Nifty futures (if available)
            "sp500_fut": "ES=F",           # S&P 500 futures (24/5)
            "nasdaq_fut": "NQ=F",          # Nasdaq futures (24/5)
            "dow_fut": "YM=F",             # Dow futures
            "vix": "^VIX",                 # VIX
            "india_vix": "^INDIAVIX",      # India VIX
            "dxy": "DX-Y.NYB",            # Dollar index
            "gold": "GC=F",               # Gold futures
            "crude": "CL=F",              # Crude oil
            "asia_etf": "INDA",           # India ETF (US-listed)
        }
        
        _yahoo_rate_wait()
        
        results = {}
        for key, sym in symbols.items():
            try:
                tk = yf.Ticker(sym)
                hist = tk.history(period="2d")
                if len(hist) >= 1:
                    current = float(hist['Close'].iloc[-1])
                    prev = float(hist['Close'].iloc[-2]) if len(hist) >= 2 else current
                    change = round((current - prev) / max(prev, 1) * 100, 2)
                    results[key] = {
                        "price": round(current, 2),
                        "prev": round(prev, 2),
                        "change": change,
                        "sym": sym
                    }
            except:
                pass
        
        # Calculate expected gap
        nifty_close = results.get("nifty_close", {}).get("price", 0)
        
        # Gift Nifty estimate:
        # If we have Nifty futures, use that directly
        gift_nifty_price = 0
        gift_nifty_gap = 0
        gift_source = ""
        
        if "nifty_fut" in results and results["nifty_fut"]["price"] > 0:
            gift_nifty_price = results["nifty_fut"]["price"]
            gift_source = "NSE Futures"
        elif "asia_etf" in results and nifty_close > 0:
            # Use INDA ETF change as proxy
            inda_change = results["asia_etf"]["change"]
            gift_nifty_price = round(nifty_close * (1 + inda_change / 100), 2)
            gift_source = "INDA ETF proxy"
        
        if gift_nifty_price > 0 and nifty_close > 0:
            gift_nifty_gap = round((gift_nifty_price - nifty_close) / max(nifty_close, 1) * 100, 2)
        
        # US market impact on India (correlation ~0.6)
        sp_change = results.get("sp500_fut", {}).get("change", 0)
        nq_change = results.get("nasdaq_fut", {}).get("change", 0)
        us_impact = round((sp_change * 0.4 + nq_change * 0.6), 2)  # Nasdaq weighted more
        
        # Expected Nifty gap (weighted)
        if gift_nifty_gap != 0:
            expected_gap = gift_nifty_gap
        else:
            expected_gap = round(us_impact * 0.6, 2)  # Use US as proxy with 0.6 correlation
        
        expected_nifty_open = round(nifty_close * (1 + expected_gap / 100), 2) if nifty_close > 0 else 0
        
        # Sentiment analysis
        vix_val = results.get("vix", {}).get("price", 0)
        vix_change = results.get("vix", {}).get("change", 0)
        crude_change = results.get("crude", {}).get("change", 0)
        gold_change = results.get("gold", {}).get("change", 0)
        dxy_change = results.get("dxy", {}).get("change", 0)
        
        # Build pre-market analysis
        signals_bullish = 0
        signals_bearish = 0
        analysis_points = []
        
        if sp_change > 0.3:
            signals_bullish += 1
            analysis_points.append(f"US markets positive (+{sp_change}%) — bullish for India open")
        elif sp_change < -0.3:
            signals_bearish += 1
            analysis_points.append(f"US markets negative ({sp_change}%) — bearish for India open")
        
        if crude_change < -1:
            signals_bullish += 1
            analysis_points.append(f"Crude oil down ({crude_change}%) — positive for India (lower import cost)")
        elif crude_change > 1:
            signals_bearish += 1
            analysis_points.append(f"Crude oil up (+{crude_change}%) — negative for India (higher import cost)")
        
        if dxy_change < -0.3:
            signals_bullish += 1
            analysis_points.append(f"Dollar weakening ({dxy_change}%) — positive for emerging markets")
        elif dxy_change > 0.3:
            signals_bearish += 1
            analysis_points.append(f"Dollar strengthening (+{dxy_change}%) — negative for emerging markets")
        
        if gold_change > 0.5:
            analysis_points.append(f"Gold up (+{gold_change}%) — risk-off sentiment")
        
        if vix_change > 5:
            signals_bearish += 1
            analysis_points.append(f"VIX spiked (+{vix_change}%) — fear rising, expect volatile open")
        elif vix_change < -5:
            signals_bullish += 1
            analysis_points.append(f"VIX dropped ({vix_change}%) — calm markets, positive open likely")
        
        overall = "BULLISH" if signals_bullish > signals_bearish else "BEARISH" if signals_bearish > signals_bullish else "NEUTRAL"
        
        gap_label = "GAP UP" if expected_gap > 0.1 else "GAP DOWN" if expected_gap < -0.1 else "FLAT OPEN"
        
        _elapsed = round(_time.time() - _t0, 1)
        
        _result = {
            "success": True,
            "_cached": False,
            "nifty_close": nifty_close,
            "gift_nifty": gift_nifty_price,
            "gift_source": gift_source,
            "gift_gap_pct": gift_nifty_gap,
            "expected_gap_pct": expected_gap,
            "expected_open": expected_nifty_open,
            "gap_label": gap_label,
            "overall_sentiment": overall,
            "signals_bull": signals_bullish,
            "signals_bear": signals_bearish,
            "analysis": analysis_points,
            "global_cues": {
                "sp500": results.get("sp500_fut", {}),
                "nasdaq": results.get("nasdaq_fut", {}),
                "dow": results.get("dow_fut", {}),
                "vix": results.get("vix", {}),
                "india_vix": results.get("india_vix", {}),
                "crude": results.get("crude", {}),
                "gold": results.get("gold", {}),
                "dxy": results.get("dxy", {}),
            },
            "elapsed": _elapsed,
        }
        _gift_nifty_cache["data"] = _result
        _gift_nifty_cache["time"] = _time.time()
        return _result
        
    except Exception as e:
        print(f"❌ gift-nifty error: {e}")
        return {"success": False, "error": str(e)[:200]}




