@app.get("/api/test-price/{ticker}")
async def test_price(ticker: str):
    """Diagnostic endpoint — test if we can fetch a single ticker price."""
    import traceback
    results = {"ticker": ticker, "sources": []}
    
    # Source 1: yfinance
    try:
        t = yf.Ticker(ticker)
        info = t.info or {}
        price = info.get('currentPrice') or info.get('regularMarketPrice') or info.get('previousClose')
        results["sources"].append({
            "name": "yfinance",
            "success": bool(price and float(price) > 0),
            "price": float(price) if price else None,
            "keys": list(info.keys())[:20]
        })
    except Exception as e:
        results["sources"].append({"name": "yfinance", "success": False, "error": str(e)[:200]})
    
    # Source 2: Yahoo v8 chart
    try:
        _yahoo_rate_wait()

        r = _http_pool.get(f"https://query1.finance.yahoo.com/v8/finance/chart/{ticker}?interval=1d&range=2d", timeout=5)
        if r.status_code == 200:
            meta = r.json().get('chart', {}).get('result', [{}])[0].get('meta', {})
            price = meta.get('regularMarketPrice', 0)
            results["sources"].append({
                "name": "yahoo_v8",
                "success": bool(price and float(price) > 0),
                "price": float(price) if price else None,
                "status": r.status_code
            })
        else:
            results["sources"].append({"name": "yahoo_v8", "success": False, "status": r.status_code, "body": r.text[:200]})
    except Exception as e:
        results["sources"].append({"name": "yahoo_v8", "success": False, "error": str(e)[:200]})
    
    results["any_success"] = any(s.get("success") for s in results["sources"])
    return results

@app.post("/api/batch-prices")
async def batch_prices(request: Request):
    """Fetch live prices. Always fetches fresh — no stale cache."""
    import re as re_bp
    
    try:
        data = await request.json()
        tickers = data.get("tickers", [])
        if not tickers or not isinstance(tickers, list):
            return {"success": False, "error": "tickers array required"}
        
        tickers = [t.strip().upper() for t in tickers[:30] if t.strip()]
        if not tickers:
            return {"success": False, "error": "no valid tickers"}
        
        def _fetch_one(tk):
            """Fetch single ticker price with 2-source fallback."""
            is_indian = '.NS' in tk or '.BO' in tk
            sym = '₹' if is_indian else '$'
            
            # Source 1: yfinance
            try:
                t = yf.Ticker(tk)
                info = t.info or {}
                price = info.get('currentPrice') or info.get('regularMarketPrice') or info.get('previousClose')
                if price and float(price) > 0:
                    price = round(float(price), 2)
                    prev = float(info.get('previousClose') or info.get('regularMarketPreviousClose') or price)
                    chg = round(((price - prev) / prev) * 100, 2) if prev > 0 else 0
                    return tk, {"price": price, "change_pct": chg, "symbol": sym, "formatted": f"{sym}{price:,.2f}"}
            except Exception as e1:
                print(f"  yf fail {tk}: {e1}")
            
            # Source 2: Yahoo v8 chart API
            try:
                _yahoo_rate_wait()

                r = _http_pool.get(f"https://query1.finance.yahoo.com/v8/finance/chart/{tk}?interval=1d&range=2d", timeout=5)
                if r.status_code == 200:
                    meta = r.json().get('chart', {}).get('result', [{}])[0].get('meta', {})
                    price = meta.get('regularMarketPrice', 0)
                    prev = meta.get('chartPreviousClose', meta.get('previousClose', price))
                    if price and float(price) > 0:
                        price = round(float(price), 2)
                        prev = round(float(prev or price), 2)
                        chg = round(((price - prev) / prev) * 100, 2) if prev > 0 else 0
                        return tk, {"price": price, "change_pct": chg, "symbol": sym, "formatted": f"{sym}{price:,.2f}"}
            except Exception as e2:
                print(f"  v8 fail {tk}: {e2}")
            
            return tk, None
        
        # Fetch ALL tickers in parallel — dedicated pool so we don't block other endpoints
        results = {}
        failed = []
        with ThreadPoolExecutor(max_workers=min(len(tickers), 8)) as pool:
            futs = {pool.submit(_fetch_one, t): t for t in tickers}
            for f in as_completed(futs, timeout=15):
                try:
                    tk, price_data = f.result(timeout=8)
                    if price_data:
                        results[tk] = price_data
                    else:
                        failed.append(futs[f])
                except:
                    failed.append(futs[f])
        
        print(f"📊 batch-prices: {len(results)}/{len(tickers)} OK, {len(failed)} failed")
        return {"success": True, "prices": results, "fetched": len(results), "cached": 0, "failed": failed[:10]}
    except Exception as e:
        print(f"❌ batch-prices error: {e}")
        return {"success": False, "error": str(e)[:100]}


# Module-level cache for market-pulse
_pulse_cache = None
_pulse_cache_ts = None
_ticker_cache = None
_ticker_cache_ts = None

@app.get("/api/market-pulse")
async def market_pulse():
    """Lightweight market events — cached 5min, parallel fetches."""
    # yfinance imported globally with 401 wrapper
    from datetime import datetime, timedelta
    from concurrent.futures import ThreadPoolExecutor, as_completed
    
    # ═══ 5-MINUTE CACHE — prevents hammering yfinance/NSE on every page load ═══
    global _pulse_cache, _pulse_cache_ts
    now_ts = datetime.utcnow()
    if _pulse_cache and _pulse_cache_ts and (now_ts - _pulse_cache_ts).total_seconds() < 1800:
        return _pulse_cache
    
    IST_OFFSET = timedelta(hours=5, minutes=30)
    now = datetime.utcnow() + IST_OFFSET
    day_name = now.strftime("%A")
    weekday = now.weekday()
    date_str = now.strftime("%A, %B %d, %Y")
    
    # Expiry detection
    year, month = now.year, now.month
    import calendar
    last_day = calendar.monthrange(year, month)[1]
    last_tuesday = last_day
    while datetime(year, month, last_tuesday).weekday() != 1:
        last_tuesday -= 1
    is_last_tuesday = (now.day == last_tuesday and weekday == 1)
    last_thursday = last_day
    while datetime(year, month, last_thursday).weekday() != 3:
        last_thursday -= 1
    is_last_thursday = (now.day == last_thursday and weekday == 3)
    
    expiry_today = []
    if weekday == 1:  # Tuesday
        expiry_today.append("NIFTY 50 (weekly)")
        if is_last_tuesday:
            expiry_today.extend(["BANK NIFTY (monthly)", "FIN NIFTY (monthly)", "Stock F&O (monthly)"])
    if weekday == 3:  # Thursday
        expiry_today.append("SENSEX (weekly)")
        if is_last_thursday:
            expiry_today.append("BANKEX (monthly)")
    
    is_expiry = len(expiry_today) > 0
    
    # ═══ PARALLEL FETCH — all 6 tickers at once instead of sequential ═══
    events = []
    global_snapshot = {}
    quick_tickers = {"BZ=F": "Brent Crude", "CL=F": "WTI Crude", "GC=F": "Gold", "SI=F": "Silver", "DX-Y.NYB": "US Dollar", "^GSPC": "S&P 500", "INR=X": "USD/INR"}
    
    def fetch_ticker(ticker, name):
        # Source 1: Google Finance (NO rate limits)
        try:
            import re as _re
            _gf_map2 = {"BZ=F": "BZ%3DF:COMMODITY", "CL=F": "CL%3DF:COMMODITY", "GC=F": "GC%3DF:COMMODITY", "SI=F": "SI%3DF:COMMODITY", "DX-Y.NYB": "DX-Y.NYB:NYBOT", "^GSPC": ".INX:INDEXSP", "INR=X": "USD-INR"}
            _gf_sym2 = _gf_map2.get(ticker, "")
            if _gf_sym2:
                _gf_url2 = f"https://www.google.com/finance/quote/{_gf_sym2}"
                _h2 = {'User-Agent': f'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/{random.randint(125,135)}.0.{random.randint(1000,9999)}.{random.randint(10,99)} Safari/537.36'}
                _gr2 = _http_pool.get(_gf_url2, timeout=5, headers=_h2)
                if _gr2.status_code == 200:
                    _pm2 = _re.search(r'data-last-price="([0-9.,]+)"', _gr2.text)
                    _cm2 = _re.search(r'data-last-normal-market-change-percent="([0-9.,-]+)"', _gr2.text) or _re.search(r'data-change-percent="([0-9.,-]+)"', _gr2.text)
                    if _pm2:
                        price = round(float(_pm2.group(1).replace(',', '')), 2)
                        chg_pct = round(float(_cm2.group(1).replace(',', '')), 2) if _cm2 else 0
                        return name, {"price": price, "change_pct": chg_pct}
        except:
            pass
        # Source 2: Yahoo v8 chart API (backup)
        try:
            _h = {'User-Agent': f'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/{random.randint(125,133)}.0.{random.randint(1000,9999)}.{random.randint(10,99)} Safari/537.36', 'Accept': 'application/json'}
            _yahoo_rate_wait()
            r = _http_pool.get(f"https://query1.finance.yahoo.com/v8/finance/chart/{ticker}?interval=1d&range=2d", timeout=4)
            if r.status_code == 200:
                m = r.json().get('chart', {}).get('result', [{}])[0].get('meta', {})
                price = m.get('regularMarketPrice', 0)
                prev = m.get('chartPreviousClose', m.get('previousClose', price))
                if price and float(price) > 0:
                    price = round(float(price), 2)
                    prev = round(float(prev), 2)
                    chg_pct = round(((price - prev) / prev) * 100, 2) if prev else 0
                    return name, {"price": price, "change_pct": chg_pct}
        except:
            pass
        # Source 3: yfinance (last resort)
        try:
            _yahoo_rate_wait()
            t = yf.Ticker(ticker)
            hist = t.history(period="2d")
            if not hist.empty:
                price = round(hist.iloc[-1]['Close'], 2)
                prev = hist.iloc[-2]['Close'] if len(hist) > 1 else price
                chg_pct = round(((price - prev) / prev) * 100, 2) if prev else 0
                return name, {"price": price, "change_pct": chg_pct}
        except:
            pass
        return name, None
    
    with ThreadPoolExecutor(max_workers=6) as executor:
        futures = {executor.submit(fetch_ticker, t, n): n for t, n in quick_tickers.items()}
        for f in as_completed(futures, timeout=8):
            try:
                name, data = f.result(timeout=3)
                if data:
                    global_snapshot[name] = data
            except:
                pass
    
    # ═══ AUTO-DETECT EVENTS from parallel-fetched snapshot ═══
    # Always show key commodity/market data as context
    for name, snap in global_snapshot.items():
        price, chg_pct = snap["price"], snap["change_pct"]
        if name == "Crude Oil":
            pass  # Handled by Brent Crude and WTI Crude separately
        elif name == "Brent Crude":
            if abs(chg_pct) >= 0.8:
                direction = "spikes" if chg_pct > 0 else "drops"
                events.append({"headline": f"Brent Crude {direction} {chg_pct:+.1f}% to ${price}", "impact": "BEARISH" if chg_pct > 0 else "BULLISH", "severity": "HIGH" if abs(chg_pct) >= 2 else "MEDIUM",
                    "detail": f"Brent is the global oil benchmark (2/3 of world pricing). {'Rising Brent = higher fuel, transport, fertilizer costs globally. India imports 85% of crude — direct hit on inflation and fiscal deficit.' if chg_pct > 0 else 'Falling Brent = lower import bill for India. Positive for current account, rupee, and inflation. Airlines, paint, tire companies benefit.'}",
                    "action": f"{'Oil marketing companies (IOC, BPCL, HPCL) under pressure. ONGC/Oil India may benefit. Avoid logistics stocks.' if chg_pct > 0 else 'Buy airlines (IndiGo), paint (Asian Paints), tire (MRF) stocks. Oil marketing companies get margin relief.'}"})
            else:
                events.append({"headline": f"Brent Crude ${price} ({chg_pct:+.1f}%)", "impact": "VOLATILE", "severity": "LOW",
                    "detail": f"Brent stable at ${price}/barrel. OPEC+ production discipline keeping range. India's oil import bill ~$120B/year — every $1 change = ~$1.5B impact.",
                    "action": "No immediate action. Watch OPEC+ meetings and Middle East tensions for next move."})
        elif name == "WTI Crude":
            if abs(chg_pct) >= 0.8:
                direction = "spikes" if chg_pct > 0 else "drops"
                events.append({"headline": f"WTI Crude {direction} {chg_pct:+.1f}% to ${price}", "impact": "BEARISH" if chg_pct > 0 else "BULLISH", "severity": "HIGH" if abs(chg_pct) >= 2 else "MEDIUM",
                    "detail": f"WTI is the US oil benchmark. {'Rising oil = inflation pressure, Fed may delay rate cuts. Energy stocks rally but consumer spending weakens.' if chg_pct > 0 else 'Falling oil = lower inflation, supports Fed rate cut thesis. Consumer and transport stocks benefit.'}",
                    "action": f"{'US energy stocks (XOM, CVX) benefit. Avoid airlines, transport. Watch Fed inflation commentary.' if chg_pct > 0 else 'Airlines, trucking, consumer stocks benefit. Energy sector may pull back.'}"})
