@app.get("/api/health")
async def health_check():
    """Diagnostic: Test all data sources and report which work"""
    results = {}
    import time as _ht
    
    # Test 1: NSE allIndices
    try:
        t0 = _ht.time()
        _nse_init()
        d = _nse_get("https://www.nseindia.com/api/allIndices")
        if d and d.get("data"):
            nifty = next((x for x in d["data"] if x.get("index") == "NIFTY 50"), None)
            results["nse_allIndices"] = {"status": "OK", "nifty": nifty.get("last") if nifty else None, "ms": round((_ht.time()-t0)*1000)}
        else:
            results["nse_allIndices"] = {"status": "FAIL", "reason": "No data"}
    except Exception as e:
        results["nse_allIndices"] = {"status": "FAIL", "reason": str(e)[:150]}
    
    # Test 2: NSE Option Chain
    try:
        t0 = _ht.time()
        d = _nse_get("https://www.nseindia.com/api/option-chain-indices?symbol=NIFTY")
        if d and d.get("records"):
            results["nse_optionchain"] = {"status": "OK", "spot": d["records"].get("underlyingValue", 0), "expiries": d["records"].get("expiryDates", [])[:3], "ms": round((_ht.time()-t0)*1000)}
        else:
            results["nse_optionchain"] = {"status": "FAIL", "reason": "No records"}
    except Exception as e:
        results["nse_optionchain"] = {"status": "FAIL", "reason": str(e)[:150]}
    
    # Test 3: yfinance
    try:
        t0 = _ht.time()
        _yahoo_rate_wait()

        tk = yf.Ticker("^NSEI")
        h = tk.history(period="5d")
        if h is not None and len(h) > 0:
            results["yfinance"] = {"status": "OK", "price": round(float(h["Close"].iloc[-1]), 2), "bars": len(h), "ms": round((_ht.time()-t0)*1000)}
        else:
            results["yfinance"] = {"status": "FAIL", "reason": "Empty/None (Yahoo 401 blocked)"}
    except Exception as e:
        results["yfinance"] = {"status": "FAIL", "reason": str(e)[:150]}
    
    # Test 4: Google Finance
    try:
        t0 = _ht.time()
        import re as _hre
        r = requests.get("https://www.google.com/finance/quote/NIFTY_50:INDEXNSE", headers={"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"}, timeout=8)
        if r.status_code == 200:
            m = _hre.search(r'data-last-price="([0-9.,]+)"', r.text)
            results["google_finance"] = {"status": "OK" if m else "PARTIAL", "price": m.group(1) if m else "unparsed", "ms": round((_ht.time()-t0)*1000)}
        else:
            results["google_finance"] = {"status": "FAIL", "reason": f"HTTP {r.status_code}"}
    except Exception as e:
        results["google_finance"] = {"status": "FAIL", "reason": str(e)[:150]}
    
    working = [k for k, v in results.items() if v.get("status") == "OK"]
    fix = ""
    if len(working) == 0:
        fix = "CRITICAL: No data sources reachable. Try: pip install yfinance --upgrade --break-system-packages && restart"
    elif "yfinance" not in working and any("nse" in w for w in working):
        fix = "NSE working, Yahoo blocked. System OK — using NSE as primary."
    elif "yfinance" in working:
        fix = "yfinance working. All good!"
    else:
        fix = "Partial sources available."
    return {"sources": results, "working": working, "count": len(working), "fix": fix}


@app.get("/api/algo-signal")
async def algo_signal_safe(symbol: str = "NIFTY", region: str = ""):
    """Wrapper that guarantees JSON response even on crash. 3-min cache."""
    from datetime import datetime, timedelta
    symbol = symbol.upper().strip().replace(".NS","").replace(".BO","").replace("^NSEI","NIFTY").replace("^NSEBANK","BANKNIFTY").replace("^BSESN","SENSEX")
    now = datetime.utcnow()
    cache_key = f"{symbol}_{region}"
    if cache_key in _algo_cache and cache_key in _algo_cache_ts:
        if (now - _algo_cache_ts[cache_key]).total_seconds() < 600:
            return _algo_cache[cache_key]
    try:
        result = await asyncio.wait_for(_algo_signal_impl(symbol, region), timeout=25)
        _algo_cache[cache_key] = result
        _algo_cache_ts[cache_key] = now
        return result
    except asyncio.TimeoutError:
        print(f"  ⏰ algo_signal {symbol} timed out at 12s")
        return {"success": False, "error": f"Analysis timed out for {symbol} — try again", "symbol": symbol}
    except Exception as e:
        import traceback
        traceback.print_exc()
        return {"success": False, "error": f"Algo error: {str(e)}", "symbol": symbol}

@app.get("/api/algo-batch")
async def algo_batch(region: str = "IN"):
    """Batch: 3 top instruments by region. Uses cache."""
    from datetime import datetime, timedelta
    IST = datetime.utcnow() + timedelta(hours=5, minutes=30)
    day_name = IST.strftime("%A")
    
    region = region.upper()
    if region == "US":
        symbols = ["SPY", "QQQ", "IWM"]
        expiry_index = ""  # SPY/QQQ have Mon/Wed/Fri expiry
        if day_name in ["Monday", "Wednesday", "Friday"]:
            expiry_index = "SPY"  # SPY 0DTE
    else:
        symbols = ["NIFTY", "BANKNIFTY", "SENSEX"]
        EXPIRY_MAP = {"Tuesday": "NIFTY", "Thursday": "SENSEX"}
        expiry_index = EXPIRY_MAP.get(day_name, "")
    
    # Priority: expiry index first
    if expiry_index in symbols:
        symbols.remove(expiry_index)
        symbols = [expiry_index] + symbols
    
    out = []
    for s in symbols:
        try:
            r = await algo_signal_safe(s, region)
            out.append(r)
        except Exception as e:
            out.append({"success": False, "symbol": s, "error": str(e)})
    
    return {
        "success": True, "signals": out, "count": len(out),
        "expiryToday": expiry_index, "dayName": day_name, "region": region,
    }

