            # 15min EMA 9 & 21
            ema9_15m = float(pd.Series(c15).ewm(span=9).mean().iloc[-1])
            ema21_15m = float(pd.Series(c15).ewm(span=21).mean().iloc[-1])
            
            # VWAP (from 5m data)
