        # Small Cap + Niche
        "AFFLE","ROUTE","HAPPSTMNDS","ZENSAR","MASTEK","TANLA","RATEGAIN","ZAGGLE","IDEAFORGE","SOLARINDS",
        "GRINDWELL","FINEORG","CLEAN","IONEXCHANG","ASTRAZEN","CHAMBLFERT","ATUL","BALAJI AMINES","NAVINFLUOR","SRF",
        "CELLO","KAYNES","LATENTVIEW","DATAPATTER","NETWEB","SASKEN","NUCLEUS","INTELLECT","NEWGEN","RAMCOCEM",
        "JKCEMENT","DALMIACEMNT","STARCEMENT","HEIDELBERG","NUVAMA","ANGELONE","MOTILALOFS","IIFL","JIOFIN","BSE",
        "CDSL","MCX","CAMS","KFINTECH","UTIAMC","APLAPOLLO","RATNAMANI","GRAPHITE","HEG","GMDCLTD",
        "COCHINSHIP","MAZAGON","GRSE","BDL","PARAS","SYNGENE","KANSAINER","TTKPRESTIG","CROMPTON","HAVELLS",
