@app.get("/api/early-momentum-radar")
async def early_momentum_radar(email: str = "", region: str = "US", category: str = "all"):
    """Detect stocks in early stages of parabolic moves.
    
    r40: BATCHED yfinance fetch. Prior implementation (r39) made 80 individual
    history() + info() calls = 240+ HTTP requests to Yahoo, which tripped rate
    limits. Now uses yf.download([tickers], period='1y') — ONE HTTP request
    for all 80 tickers' price history. Individual .info calls remain serial
    (no bulk API exists), but we fetch them in a bounded worker pool with
    retry. Total Yahoo load cut by ~70%.
    
    r46: Category-based scanning. `category` param picks a narrower universe.
    "all" scans the full _momentum_universe_us/in (backward compat).
    Each category has its own 30-min cache. See _momentum_categories_us/in.
    """
    email = email.strip().lower()
    # r63.5: replaced 9-line duplicated gate boilerplate
    _mr_ok, email = check_premium_gate(email, "dream")
    if not _mr_ok:
        return {"success": False, "error": "This feature is exclusive. Contact support for access."}
    
    region = region.upper()
    if region not in ("US", "IN"):
        return {"success": False, "error": "region must be US or IN"}
    
    # r46: Category selection. "all" preserves backward compat.
    category = (category or "all").strip().lower()
    cat_map = _momentum_categories_us if region == "US" else _momentum_categories_in
    if category != "all" and category not in cat_map:
        return {
            "success": False,
            "error": f"Unknown category '{category}'. Valid: all, " + ", ".join(cat_map.keys()),
            "available_categories": list(cat_map.keys()),
        }
    
    # Cache key: region + category. Each combination cached independently.
    cache_key = f"{region}_{category}"
    if not isinstance(_momentum_radar_cache.get(region), dict) or "ts" in _momentum_radar_cache.get(region, {}):
        # Migrate old flat cache shape {US: {ts, data}} → {US: {category: {ts, data}}}
        _momentum_radar_cache[region] = {}
    
    cat_cache = _momentum_radar_cache[region].get(category, {})
    if cat_cache.get("data") and time.time() - cat_cache.get("ts", 0) < 1800:
        return cat_cache["data"]
    
    # Select universe based on category
    if category == "all":
        universe = _momentum_universe_us if region == "US" else _momentum_universe_in
        cat_label = "All Tickers"
        cat_desc = "Comprehensive sweep"
    else:
        cat_info = cat_map[category]
        universe = cat_info["tickers"]
        cat_label = cat_info["label"]
        cat_desc = cat_info["desc"]
    
    print(f"\n🔥 Early Momentum Radar starting ({region} / {category}) [BATCHED]...")
    t0 = time.time()
    
    universe = list(dict.fromkeys(universe))  # dedup
    yf_symbols = [s if region == "US" else s + ".NS" for s in universe]
    print(f"  📊 Scanning {len(universe)} tickers (batched, category={category})...")
    
    # ═══════════════════════════════════════════════════════════════════
    # STEP 1: BATCH PRICE HISTORY — single yf.download() call
    # ═══════════════════════════════════════════════════════════════════
    # yf.download returns a DataFrame with MultiIndex columns:
    #   level 0 = ['Open', 'High', 'Low', 'Close', 'Adj Close', 'Volume']
    #   level 1 = ticker symbols
    # Example: hist_all['Close']['AAPL'] gets AAPL close prices.
    # This is ONE HTTP request — replaces 80 individual tk.history() calls.
    import yfinance as yf
    try:
        _yahoo_rate_wait()
        # Run batch download in threadpool (yf.download is sync)
        hist_all = await asyncio.get_event_loop().run_in_executor(
            None,
            lambda: yf.download(
                tickers=" ".join(yf_symbols),
                period="1y",
                interval="1d",
                group_by="ticker",
                progress=False,
                threads=True,
                auto_adjust=False,
            )
        )
        print(f"  ✓ Batch history fetched: {len(yf_symbols)} tickers in one request")
        try: diag_log("SCAN", "momentum_batch_download_ok", {
            "region": region, "tickers": len(yf_symbols),
            "elapsed_sec": round(time.time() - t0, 1),
        })
        except Exception: pass
    except Exception as _de:
        print(f"  ❌ Batch download failed: {type(_de).__name__}: {_de}")
        try: diag_log("SCAN", "momentum_batch_download_failed", {
            "region": region, "err": f"{type(_de).__name__}: {str(_de)[:120]}",
        })
        except Exception: pass
        hist_all = None
    
    # ═══════════════════════════════════════════════════════════════════
    # STEP 2: Extract per-ticker history from batch result
    # ═══════════════════════════════════════════════════════════════════
    def _get_hist(yf_sym):
        """Extract single-ticker history from batch DataFrame."""
        if hist_all is None or len(hist_all) == 0: return None
        try:
            # Batch with group_by='ticker' creates MultiIndex: hist_all[ticker] gives subframe
            if len(yf_symbols) == 1:
                # Single-ticker edge case: no MultiIndex, just regular frame
                return hist_all if len(hist_all) >= 30 else None
            if yf_sym not in hist_all.columns.get_level_values(0):
                return None
            sub = hist_all[yf_sym].dropna()
            return sub if len(sub) >= 30 else None
        except Exception:
            return None
    
    # ═══════════════════════════════════════════════════════════════════
    # STEP 3: Fetch .info + options per-ticker in bounded concurrent pool
    # (These can't be batched — no Yahoo bulk API for info/options.)
    # ═══════════════════════════════════════════════════════════════════
    _sem = asyncio.Semaphore(6 if region == "US" else 8)
    _task_timeout = 25  # shorter now — history already fetched in batch
    
    async def _scan_one(sym):
        async with _sem:
            try:
                yf_sym = sym if region == "US" else sym + ".NS"
                hist = _get_hist(yf_sym)
                return await asyncio.wait_for(
                    _momentum_scan_single_with_hist(sym, region, hist),
                    timeout=_task_timeout
                )
            except asyncio.TimeoutError:
                print(f"  ⏱ {sym}: timeout after {_task_timeout}s")
                try: diag_log("SCAN", "momentum_radar_timeout", {"sym": sym, "region": region})
                except Exception: pass
                return None
            except Exception as _e:
                print(f"  ❌ {sym}: {type(_e).__name__}: {_e}")
                return None
    
    tasks = [_scan_one(s) for s in universe]
    raw = await asyncio.gather(*tasks)
    results = [r for r in raw if r and r.get("score", 0) > 0]
    
    # Sort by score, bucket by tier
    results.sort(key=lambda x: x["score"], reverse=True)
    red_alert = [r for r in results if r["score"] >= 80]
    watching = [r for r in results if 60 <= r["score"] < 80]
    early = [r for r in results if 40 <= r["score"] < 60]
    # r44: Dedicated ACCELERATING bucket — any score tier where acceleration is strong.
    # These may overlap with red_alert/watching/early but are surfaced separately
    # because they're the EARLIEST catchable setups (before absolute score crosses
    # high thresholds). Sort by acceleration score itself, not total score.
    accelerating = sorted(
        [r for r in results if r.get("accelerating")],
        key=lambda x: x.get("details", {}).get("signal_6_acceleration", 0),
        reverse=True
    )
    
    # Count how many tickers actually had a 14-day baseline available
    # (honest reporting: on fresh install, this starts at 0 and grows over 2 weeks)
    with_baseline = sum(1 for r in results
                        if r.get("details", {}).get("acceleration_baseline", "").startswith("baseline_"))
    
    elapsed = round(time.time() - t0, 1)
    coverage = {
        "scanned": len(universe),
        "completed": len(results),
        "failed": len(universe) - len(results),
        "coverage_pct": round((len(results) / max(1, len(universe))) * 100, 1),
        "scan_time_sec": elapsed,
        "region": region,
        "batch_mode": "yf.download",
        "acceleration_baselines_available": with_baseline,
        "acceleration_coverage_pct": round((with_baseline / max(1, len(results))) * 100, 1),
    }
    print(f"  ✅ Momentum Radar: {len(red_alert)} RED + {len(watching)} WATCH + {len(early)} EARLY + {len(accelerating)} ACCELERATING in {elapsed}s")
    print(f"  📊 Coverage: {coverage['completed']}/{coverage['scanned']} ({coverage['coverage_pct']}%)")
    print(f"  📊 Acceleration baselines: {with_baseline}/{len(results)} ({coverage['acceleration_coverage_pct']}%)")
    try:
        diag_log("SCAN", "momentum_radar_completed", {
            **coverage,
            "red_alert": len(red_alert),
            "watching": len(watching),
            "early": len(early),
            "accelerating": len(accelerating),
        })
    except Exception: pass
    
    # r44: build a status message about acceleration system state
    if with_baseline == 0:
        accel_status = "Acceleration detection warming up — no 14-day baselines yet. Signal 6 will activate after ~2 weeks of scan history. Until then, scores use the 80-point base."
    elif coverage["acceleration_coverage_pct"] < 30:
        accel_status = f"Acceleration detection partial — {with_baseline}/{len(results)} tickers have 14-day baselines. Coverage grows daily."
    else:
        accel_status = f"Acceleration detection active — {with_baseline}/{len(results)} tickers have 14-day baselines."
    
    result = {
        "success": True,
        "region": region,
        "category": category,          # r46
        "categoryLabel": cat_label,    # r46
        "categoryDesc": cat_desc,      # r46
        "elapsed": elapsed,
        "coverage": coverage,
        "redAlert": red_alert,
        "watching": watching,
        "early": early,
        "accelerating": accelerating,
        "accelerationStatus": accel_status,
        "totalScored": len(results),
        "disclaimer": (
            "SIGNAL DETECTOR, NOT A TRADE RECOMMENDER. "
            "Even the best momentum radars have 40-60% false positive rates. "
            "These signals identify SETUPS that historically precede parabolic moves "
            "(CAR, SNDK, GME patterns) — but many setups never trigger. "
            "Use as one input in your decision process, not as a buy signal."
        ),
    }
    # r46: keyed cache per region+category
    if not isinstance(_momentum_radar_cache.get(region), dict) or "ts" in _momentum_radar_cache.get(region, {}):
        _momentum_radar_cache[region] = {}
    _momentum_radar_cache[region][category] = {"ts": time.time(), "data": result}
    return result


@app.get("/api/early-momentum-radar/categories")
async def momentum_radar_categories(region: str = "US"):
    """List available categories for the region. Used by frontend to render buttons."""
    region = region.upper()
    if region not in ("US", "IN"):
        return {"success": False, "error": "region must be US or IN"}
    cat_map = _momentum_categories_us if region == "US" else _momentum_categories_in
    # Build ordered list with "all" first
    cats = [{"id": "all", "label": "📊 All", "desc": "Comprehensive sweep", "count": len(_momentum_universe_us if region == "US" else _momentum_universe_in)}]
    for cid, info in cat_map.items():
        cats.append({"id": cid, "label": info["label"], "desc": info["desc"], "count": len(info["tickers"])})
    return {"success": True, "region": region, "categories": cats}


