def _detect_orb_setup(hist_df):
    """Opening Range Breakout — Toby Crabel (1990).
    Setup: stock breaks above the high (or below the low) of the first
    30 minutes (6 × 5-min bars) of the trading day on confirming volume.
    Returns dict or None.
    """
    import numpy as np
    if hist_df is None or len(hist_df) < 6:
        return None
    try:
        # First 6 bars define opening range
        opening = hist_df.iloc[:6]
        or_high = float(opening['High'].max())
        or_low = float(opening['Low'].min())
        opening_avg_vol = float(opening['Volume'].mean())
        if or_high <= 0 or or_low <= 0 or opening_avg_vol <= 0:
            return None

        # Look at remaining bars for breakout
        rest = hist_df.iloc[6:]
        if len(rest) < 1:
            return None

        last_close = float(rest['Close'].iloc[-1])
        last_vol = float(rest['Volume'].iloc[-1])
        rest_high = float(rest['High'].max())
        rest_low = float(rest['Low'].min())

        # Breakout direction
        direction = None
        breakout_strength = 0
        if rest_high > or_high * 1.002:  # 0.2% above OR high
            direction = "long"
            breakout_strength = ((rest_high - or_high) / or_high) * 100
        elif rest_low < or_low * 0.998:
            direction = "short"
            breakout_strength = ((or_low - rest_low) / or_low) * 100

        if not direction:
            return None

        # Volume confirmation: breakout bar volume vs OR average
        vol_ratio = last_vol / opening_avg_vol if opening_avg_vol > 0 else 0
        if vol_ratio < 0.8:  # weak volume on breakout = lower probability
            return None

        # Levels
        or_range = or_high - or_low
        if direction == "long":
            entry = last_close
            stop = or_low * 0.998  # below OR low
            target_1 = entry + or_range  # 1× OR range
            target_2 = entry + (or_range * 2)
        else:
            entry = last_close
            stop = or_high * 1.002
            target_1 = entry - or_range
            target_2 = entry - (or_range * 2)

        risk = abs(entry - stop)
        reward_1 = abs(target_1 - entry)
        rr = reward_1 / risk if risk > 0 else 0

        return {
            "setup": "Opening Range Breakout",
            "timeframe": "INTRADAY",
            "direction": direction,
            "or_high": round(or_high, 2),
            "or_low": round(or_low, 2),
            "or_range_pct": round((or_range / or_low) * 100, 2),
            "breakout_strength_pct": round(breakout_strength, 2),
            "vol_ratio": round(vol_ratio, 2),
            "entry": round(entry, 2),
            "stop": round(stop, 2),
            "target_1": round(target_1, 2),
            "target_2": round(target_2, 2),
            "risk_reward": round(rr, 2),
            "literature_base_rate_pct": 56,  # midpoint of 53-58 from Crabel
            "literature_source": "Crabel (1990): Day Trading with Short Term Price Patterns and Opening Range Breakout",
            "honest_caveat": "Base rate from liquid futures + large-cap equity studies. Falls apart on news days, low-vol days, and small-caps. Subtract 5-10% for live slippage.",
        }
    except Exception:
        return None


def _detect_vwap_reclaim(hist_df):
    """VWAP Reclaim After Open Drive — Berkowitz/Raschke patterns.
    Setup: stock opens with a directional drive, fades to VWAP, then
    reclaims VWAP on increasing volume — institutional defense pattern.
    Returns dict or None.
    """
    import numpy as np
    if hist_df is None or len(hist_df) < 12:
        return None
    try:
        # Compute VWAP for the session
        typical = (hist_df['High'] + hist_df['Low'] + hist_df['Close']) / 3
        cum_tpv = (typical * hist_df['Volume']).cumsum()
        cum_v = hist_df['Volume'].cumsum()
        vwap = cum_tpv / cum_v.replace(0, np.nan)
        vwap = vwap.fillna(method='ffill').values

        closes = hist_df['Close'].values
        highs = hist_df['High'].values
        lows = hist_df['Low'].values
        volumes = hist_df['Volume'].values

        # Step 1: was there an open drive? (first 30 min strong move from open)
        open_price = float(closes[0])
        peak_high_first6 = float(highs[:6].max())
        trough_low_first6 = float(lows[:6].min())
        drive_up = (peak_high_first6 - open_price) / open_price * 100
        drive_down = (open_price - trough_low_first6) / open_price * 100

        # Need at least 0.5% drive (not flat)
        if max(drive_up, drive_down) < 0.5:
            return None

        # Step 2: did price fade back to VWAP (touch within 0.2%)?
        # Look at bars 6-N for VWAP test
        if len(closes) < 12:
            return None

        mid_section = slice(6, len(closes) - 2)
        mid_lows = lows[mid_section]
        mid_highs = highs[mid_section]
        mid_vwap = vwap[mid_section]

        if drive_up > drive_down:
            # Upward drive — looking for fade DOWN to VWAP, then reclaim
            tested_vwap = np.any(mid_lows <= mid_vwap * 1.002)
        else:
            # Downward drive — looking for rally UP to VWAP, then reject (short setup)
            tested_vwap = np.any(mid_highs >= mid_vwap * 0.998)

        if not tested_vwap:
            return None

        # Step 3: most recent bars confirm reclaim with volume
        last_close = float(closes[-1])
        last_vwap = float(vwap[-1])
        last_vol = float(volumes[-1])
        avg_vol_recent = float(volumes[-10:-1].mean()) if len(volumes) > 10 else float(volumes[:-1].mean())
        vol_ratio = last_vol / avg_vol_recent if avg_vol_recent > 0 else 0

        direction = None
        if drive_up > drive_down and last_close > last_vwap * 1.002:
            direction = "long"
        elif drive_down > drive_up and last_close < last_vwap * 0.998:
            direction = "short"

        if not direction:
            return None

        # Need volume confirmation
        if vol_ratio < 1.0:
            return None

        # Levels
        atr = float(np.mean(highs[-14:] - lows[-14:])) if len(highs) >= 14 else (last_close * 0.01)
        if direction == "long":
            entry = last_close
            stop = last_vwap * 0.997  # just below VWAP
            target_1 = entry + atr
            target_2 = entry + (atr * 2.5)
        else:
            entry = last_close
            stop = last_vwap * 1.003
            target_1 = entry - atr
            target_2 = entry - (atr * 2.5)

        risk = abs(entry - stop)
        reward_1 = abs(target_1 - entry)
        rr = reward_1 / risk if risk > 0 else 0

        return {
            "setup": "VWAP Reclaim After Open Drive",
            "timeframe": "INTRADAY",
            "direction": direction,
            "vwap": round(last_vwap, 2),
            "open_drive_pct": round(max(drive_up, drive_down), 2),
            "vol_ratio": round(vol_ratio, 2),
            "entry": round(entry, 2),
            "stop": round(stop, 2),
            "target_1": round(target_1, 2),
            "target_2": round(target_2, 2),
            "risk_reward": round(rr, 2),
            "literature_base_rate_pct": 62,  # midpoint of 60-65
            "literature_source": "Berkowitz/Logue VWAP execution studies + Linda Raschke patterns",
            "honest_caveat": "Base rate applies to >$1B mcap with >$10M daily $vol. Smaller names: literature does not apply. Subtract 5-10% for slippage.",
        }
    except Exception:
        return None


def _detect_inside_day_continuation(hist_df_daily):
    """Inside-Day + Trend Continuation — Bulkowski.
    Setup: yesterday's high/low entirely within prior day's range, AND
    aligned with a clean uptrend (above rising 50MA + 200MA).
    Returns dict or None.
    """
    import numpy as np
    if hist_df_daily is None or len(hist_df_daily) < 200:
        return None
    try:
        highs = hist_df_daily['High'].values
        lows = hist_df_daily['Low'].values
        closes = hist_df_daily['Close'].values

        if len(closes) < 3:
            return None

        # Inside day check: yesterday's range inside the day before
        yest_high = float(highs[-1])
        yest_low = float(lows[-1])
        prev_high = float(highs[-2])
        prev_low = float(lows[-2])

        is_inside = (yest_high <= prev_high and yest_low >= prev_low)
        if not is_inside:
            return None

        current = float(closes[-1])

        # Trend filter: above rising 50MA and 200MA (Bulkowski's filter
        # boost — inside-day base rate jumps to ~58-62% when aligned with trend).
        ma_50 = float(np.mean(closes[-50:]))
        ma_200 = float(np.mean(closes[-200:]))
        ma_50_5d_ago = float(np.mean(closes[-55:-5]))

        in_uptrend = (current > ma_50 > ma_200 and ma_50 > ma_50_5d_ago)
        in_downtrend = (current < ma_50 < ma_200 and ma_50 < ma_50_5d_ago)

        if not (in_uptrend or in_downtrend):
            return None

        direction = "long" if in_uptrend else "short"

        # ATR for stops/targets
        atr_14 = float(np.mean(highs[-14:] - lows[-14:]))
        prev_range = prev_high - prev_low

        if direction == "long":
            # Trigger above prior day's high
            entry = round(prev_high * 1.001, 2)
            stop = round(min(yest_low, current - atr_14 * 1.5), 2)
            target_1 = round(entry + atr_14 * 2, 2)
            target_2 = round(entry + atr_14 * 3.5, 2)
        else:
            entry = round(prev_low * 0.999, 2)
            stop = round(max(yest_high, current + atr_14 * 1.5), 2)
            target_1 = round(entry - atr_14 * 2, 2)
            target_2 = round(entry - atr_14 * 3.5, 2)

        risk = abs(entry - stop)
        reward_1 = abs(target_1 - entry)
        rr = reward_1 / risk if risk > 0 else 0

        return {
            "setup": "Inside-Day Continuation",
            "timeframe": "2-DAY SWING",
            "direction": direction,
            "yesterday_range_pct": round((yest_high - yest_low) / current * 100, 2),
            "prior_range_pct": round((prev_high - prev_low) / current * 100, 2),
            "trend": "uptrend" if in_uptrend else "downtrend",
            "ma_50": round(ma_50, 2),
            "ma_200": round(ma_200, 2),
            "entry": entry,
            "stop": stop,
            "target_1": target_1,
            "target_2": target_2,
            "risk_reward": round(rr, 2),
            "literature_base_rate_pct": 58,  # midpoint of 55-60 with trend filter
            "literature_source": "Bulkowski, Encyclopedia of Chart Patterns (3rd ed) — inside-day filtered by trend",
            "honest_caveat": "Base rate is from daily-bar studies on US equities since 1990 with survivorship bias. Live execution costs cut 5-10% off theoretical. India NSE: same logic but base rates not directly studied.",
        }
    except Exception:
        return None


@app.get("/api/intraday-setups")
async def intraday_setups(
    email: str = "",
    region: str = "US",
    timeframe: str = "all",  # all | intraday | swing
    limit: int = 30,
):
    """r62.2: Scan liquid universe for ORB / VWAP-reclaim / Inside-day setups."""
    email = (email or "").strip().lower()
    # r63.5: replaced duplicated premium-gate boilerplate
    _ok, email = check_premium_gate(email, "dream")
    if not _ok:
        return {"success": False, "error": "Intraday Setups is a premium feature."}

    region = (region or "US").upper()
    if region not in ("US", "IN"):
        return {"success": False, "error": "region must be US or IN"}
    timeframe = (timeframe or "all").lower()
    if timeframe not in ("all", "intraday", "swing"):
        timeframe = "all"

    # 5-min cache for intraday data, longer for swing-only
    cache_ttl = 300 if timeframe in ("all", "intraday") else 1800
    _cache_key = f"intra_setups_v1:{region}:{timeframe}:{limit}"
    cached = _smart_cache_get(_cache_key)
    if cached:
        cached = dict(cached)
        cached["_cached"] = True
        cached["_cache_age_sec"] = int(time.time() - cached.get("_cached_at", time.time()))
        return cached

    universe = _intraday_universe_us if region == "US" else _intraday_universe_in
    suffix = "" if region == "US" else ".NS"
    csym = "$" if region == "US" else "₹"

    print(f"\n⚡ r62.2 Intraday Setup scan — {region} ({len(universe)} tickers, timeframe={timeframe})")
    t0 = time.time()

    import yfinance as yf
    candidates = []
    skipped = 0

    for sym in universe:
        yf_sym = sym + suffix
        try:
            _yahoo_rate_wait()
            tk = yf.Ticker(yf_sym)

            # Intraday data (5-min bars, today-ish window)
            intraday_hist = None
            if timeframe in ("all", "intraday"):
                try:
                    intraday_hist = tk.history(period="2d", interval="5m")
                    if intraday_hist is None or len(intraday_hist) < 6:
                        intraday_hist = None
                except Exception:
                    intraday_hist = None

            # Daily bars for swing setups
            daily_hist = None
            if timeframe in ("all", "swing"):
                try:
                    daily_hist = tk.history(period="2y", interval="1d")
                    if daily_hist is None or len(daily_hist) < 200:
                        daily_hist = None
                except Exception:
                    daily_hist = None

            info = tk.info or {}
            spot = info.get("regularMarketPrice")
            mcap = info.get("marketCap")
            avg_vol = info.get("averageVolume") or 0
            avg_dollar_vol = (spot or 0) * avg_vol

            # Liquidity gate (literature applies to liquid only)
            if region == "US":
                if mcap and mcap < 1_000_000_000:  # < $1B
                    skipped += 1
                    continue
                if avg_dollar_vol < 10_000_000:
                    skipped += 1
                    continue

            # Run detectors
            setups_found = []
            if intraday_hist is not None:
                orb = _detect_orb_setup(intraday_hist)
                if orb: setups_found.append(orb)
                vwap = _detect_vwap_reclaim(intraday_hist)
                if vwap: setups_found.append(vwap)

            if daily_hist is not None and timeframe in ("all", "swing"):
                ind = _detect_inside_day_continuation(daily_hist)
                if ind: setups_found.append(ind)

            if not setups_found:
                continue

            for s in setups_found:
                candidates.append({
                    "symbol": sym,
                    "name": info.get("longName") or info.get("shortName") or sym,
                    "sector": info.get("sector") or "Unknown",
                    "spot": spot,
                    "market_cap": mcap,
                    "avg_dollar_vol": avg_dollar_vol,
                    **s,
                })

        except Exception as e:
            skipped += 1

    # Rank by literature_base_rate × risk_reward (a rough composite)
    candidates.sort(
        key=lambda x: x.get("literature_base_rate_pct", 0) * x.get("risk_reward", 0),
        reverse=True
    )
    candidates = candidates[:limit]

    elapsed = time.time() - t0
    print(f"✅ Intraday setups: {len(candidates)} candidates / {len(universe)} scanned ({elapsed:.1f}s)")

    response = {
        "success": True,
        "region": region,
        "currency_symbol": csym,
        "timeframe": timeframe,
        "universe_size": len(universe),
        "candidates": candidates,
        "skipped_count": skipped,
        "scan_time_sec": round(elapsed, 1),
        "_cached_at": time.time(),
        "honest_disclaimer": (
            "Win rates shown are LITERATURE base rates from published studies on similar setups in different time periods. "
            "Your actual win rate depends on entry timing, slippage, position sizing, and emotional discipline — typically 5-15% LOWER than literature. "
            "Backtest with your own broker fills before sizing up. This tool finds CANDIDATES, not signals."
        ),
        "methodology": {
            "ORB": "Crabel (1990) — base 53-58% on liquid futures/large-caps, lower on choppy/low-vol days",
            "VWAP Reclaim": "Berkowitz/Raschke — base 60-65% on >$1B mcap, falls apart on illiquid",
            "Inside-Day Continuation": "Bulkowski — base 55-60% with trend filter on US equities since 1990, has survivorship bias",
        },
    }

    _smart_cache_set(_cache_key, response, ttl=cache_ttl)
    return response



@app.get("/api/high-prob-setups")
async def high_prob_setups(email: str = "", region: str = "US", mode: str = "balanced"):
    """r51: Return stocks with multi-criteria technical setups.
    
    Modes:
      - balanced: 2+ criteria, ~60-70% historical win rate target
      - conservative: 4+ criteria + trend confirmation, ~75-80% target
      - today: reuses momentum radar "all" scan cache (fastest)
    """
    email = email.strip().lower()
    # r63.5: replaced duplicated premium-gate boilerplate
    _ok, email = check_premium_gate(email, "dream")
    if not _ok:
        return {"success": False, "error": "This feature is exclusive. Contact support for access."}
    
    region = region.upper()
    if region not in ("US", "IN"):
        return {"success": False, "error": "region must be US or IN"}
    mode = (mode or "balanced").lower()
    if mode not in ("balanced", "conservative", "today"):
        return {"success": False, "error": "mode must be balanced, conservative, or today"}
    
    # 30-min cache per (region, mode)
    cache = _high_prob_cache.get(region, {}).get(mode, {})
    if cache.get("data") and time.time() - cache.get("ts", 0) < 1800:
        return cache["data"]
    
    print(f"\n🎯 High-Prob Setups scanning ({region} / {mode})...")
    t0 = time.time()
    
    # Universe — reuse momentum radar universe
    universe = _momentum_universe_us if region == "US" else _momentum_universe_in
    universe = list(dict.fromkeys(universe))
    yf_symbols = [s if region == "US" else s + ".NS" for s in universe]
    
    # Batch price history (same technique as momentum radar r40)
    import yfinance as yf
    try:
        _yahoo_rate_wait()
        hist_all = await asyncio.get_event_loop().run_in_executor(
            None,
            lambda: yf.download(
                tickers=" ".join(yf_symbols),
                period="1y", interval="1d",
                group_by="ticker", progress=False, threads=True, auto_adjust=False,
            )
        )
    except Exception as _de:
        return {"success": False, "error": f"Batch fetch failed: {type(_de).__name__}"}
    
    def _get_hist(yf_sym):
        if hist_all is None or len(hist_all) == 0: return None
        try:
            if len(yf_symbols) == 1:
                return hist_all if len(hist_all) >= 60 else None
            if yf_sym not in hist_all.columns.get_level_values(0):
                return None
            sub = hist_all[yf_sym].dropna()
            return sub if len(sub) >= 60 else None
        except Exception:
            return None
    
    # Detect setups per ticker (no .info needed — keeps Yahoo load LOW)
    results = []
    for sym in universe:
        yf_sym = sym if region == "US" else sym + ".NS"
        hist = _get_hist(yf_sym)
        setup = _detect_setup_patterns(sym, None, hist)
        if setup:
            results.append(setup)
    
    # Filter by mode
    if mode == "conservative":
        filtered = [r for r in results if r["criteria_met"] >= 4]
        min_required = 4
    elif mode == "today":
        filtered = [r for r in results if r["criteria_met"] >= 2]
        min_required = 2
    else:  # balanced
        filtered = [r for r in results if r["criteria_met"] >= 2]
        min_required = 2
    
    # Sort by criteria count DESC, then risk_reward DESC
    filtered.sort(key=lambda x: (x["criteria_met"], x["risk_reward"]), reverse=True)
    
    elapsed = round(time.time() - t0, 1)
    print(f"  ✅ High-Prob Setups: {len(filtered)} stocks meet {min_required}+ criteria in {elapsed}s")
    try: diag_log("SCAN", "high_prob_completed", {
        "region": region, "mode": mode, "total": len(filtered),
        "universe": len(universe), "elapsed_sec": elapsed,
    })
    except Exception: pass
    
    result = {
        "success": True,
        "region": region,
        "mode": mode,
        "elapsed": elapsed,
        "universe_scanned": len(universe),
        "setups_found": len(filtered),
        "min_criteria_required": min_required,
        "stocks": filtered,
        "honest_disclaimer": (
            "Win rates quoted (60-80%) are based on published trading literature "
            "(Bulkowski, Minervini, O'Neil), NOT our own backtest. No system achieves "
            "99% win rate. Always use stop losses and proper position sizing (1-3% per trade). "
            "Past setup performance does not guarantee future results."
        ),
        "how_to_use": [
            "Entry: buy within the entry zone shown (low-high range)",
            "Stop: place stop at or below the stop-loss level — non-negotiable",
            "Target: take profits at the conservative target (1.5 ATR); let runners go to aggressive target",
            "Position size: 1-3% of portfolio per trade (higher for conservative mode, lower for balanced)",
            "Best time to enter: opening 30 min or on confirmed breakout",
        ],
    }
    _high_prob_cache.setdefault(region, {})[mode] = {"ts": time.time(), "data": result}
    return result


# ═══════════════════════════════════════════════════════════════════════
# OPTIONS SETUP DETECTOR (r52)
#
# Purpose: Surface stocks showing UNUSUAL OPTIONS ACTIVITY that precedes
# short-term moves (intraday to 2-day holds). Identifies CANDIDATES for
# options trades using free Yahoo options data.
#
# HARD HONEST LIMITATIONS (repeated in every response):
#   - Yahoo options data is 15-MIN DELAYED
#   - This is a SCREENER, not a live trade feed
#   - For 10-minute trades, use broker real-time data (Kite/Upstox/Polygon)
#   - Retail options slippage is 0.5-1.5% — assume worst case
#   - 90%+ of retail 0DTE traders lose money long-term
#
# Detection criteria:
#   1. Call/Put volume ratio >2.5 (bullish positioning)
#   2. Total options volume >3× 5-day average (unusual interest)
#   3. ATM straddle expansion (volatility increasing)
#   4. Not within 3 days of earnings (avoids IV crush)
#   5. Stock within a valid technical setup (uptrend/downtrend)
#
# Output per candidate:
#   - Direction (bullish/bearish/neutral)
#   - Suggested strike selection guidance (not specific contracts)
#   - Entry zone on UNDERLYING (options prices move too fast for static levels)
#   - Expected move (from ATM straddle)
#   - Honest risk/sizing notes
# ═══════════════════════════════════════════════════════════════════════

_options_setup_cache = {"US": {}, "IN": {}}


def _detect_options_setup(sym, region, info, hist_df, options_chain_data):
    """Analyze options activity and underlying technicals to flag candidates.
    
    options_chain_data is a list of {strike, ce_volume, pe_volume, ce_oi, pe_oi, ce_iv}
    rows aggregated across ATM ± 10 strikes.
    """
    import numpy as np
    
    if hist_df is None or len(hist_df) < 30:
        return None
    if not options_chain_data or len(options_chain_data) == 0:
        return None
    
    closes = hist_df['Close'].values
    highs = hist_df['High'].values
    lows = hist_df['Low'].values
    volumes = hist_df['Volume'].values
    
    current = float(closes[-1])
    if current <= 0:
        return None
    
    # Aggregate options metrics
    total_call_vol = sum(int(r.get("ce_volume") or 0) for r in options_chain_data)
    total_put_vol = sum(int(r.get("pe_volume") or 0) for r in options_chain_data)
    total_call_oi = sum(int(r.get("ce_oi") or 0) for r in options_chain_data)
    total_put_oi = sum(int(r.get("pe_oi") or 0) for r in options_chain_data)
    total_vol = total_call_vol + total_put_vol
    
    if total_vol < 100:
        return None  # Too illiquid to matter
    
    cp_vol_ratio = total_call_vol / max(total_put_vol, 1)
    cp_oi_ratio = total_call_oi / max(total_put_oi, 1)
    
    # ATM straddle for expected move calculation
    # Find strike closest to spot
    atm_strike_data = min(options_chain_data, key=lambda r: abs(float(r.get("strike") or 0) - current))
    atm_strike = float(atm_strike_data.get("strike") or current)
    
    # Estimate straddle premium from IV if available, else from observed prices
    atm_iv = float(atm_strike_data.get("ce_iv") or 0)
    if atm_iv > 0 and atm_iv < 3:  # Sanity check — IV should be 0-300%
        # Rough expected move for 1 week: spot × IV × sqrt(7/365)
        expected_move_1w = current * atm_iv * (7 / 365) ** 0.5
        expected_move_pct = (expected_move_1w / current) * 100
    else:
        # Fallback: recent realized volatility
        returns = np.diff(closes[-20:]) / closes[-20:-1]
        realized_vol = float(np.std(returns)) * (252 ** 0.5)
        expected_move_1w = current * realized_vol * (7 / 365) ** 0.5
        expected_move_pct = (expected_move_1w / current) * 100
    
    # ── Direction determination ──
    direction = None
    direction_color = "#94a3b8"
    direction_reasons = []
    
    # Bullish conditions
    bull_score = 0
    if cp_vol_ratio >= 2.5: bull_score += 3; direction_reasons.append(f"Heavy call flow (C/P volume {cp_vol_ratio:.1f}×)")
    elif cp_vol_ratio >= 1.8: bull_score += 2; direction_reasons.append(f"Elevated call flow (C/P {cp_vol_ratio:.1f}×)")
    
    # Trend confirmation
    if len(closes) >= 50:
        ma_50 = float(np.mean(closes[-50:]))
        ma_20 = float(np.mean(closes[-20:]))
        if current > ma_20 > ma_50:
            bull_score += 2
            direction_reasons.append("Uptrend (above 20MA and 50MA)")
        elif current < ma_20 < ma_50:
            bull_score -= 2
    
    # Momentum
    ret_5d = ((closes[-1] - closes[-6]) / closes[-6]) * 100 if len(closes) >= 6 and closes[-6] > 0 else 0
    if ret_5d >= 3: bull_score += 1; direction_reasons.append(f"5-day momentum +{ret_5d:.1f}%")
    elif ret_5d <= -3: bull_score -= 1
    
    # Bearish conditions (inverse)
    bear_score = 0
    if cp_vol_ratio <= 0.5:
        bear_score += 3
        direction_reasons.append(f"Heavy put flow (C/P volume {cp_vol_ratio:.2f}×)")
    elif cp_vol_ratio <= 0.7:
        bear_score += 2
    
    if len(closes) >= 50:
        ma_50 = float(np.mean(closes[-50:]))
        ma_20 = float(np.mean(closes[-20:]))
        if current < ma_20 < ma_50:
            bear_score += 2
            direction_reasons.append("Downtrend (below 20MA and 50MA)")
    
    if ret_5d <= -3: bear_score += 1
    
    # Decide direction
    if bull_score >= 4 and bull_score > bear_score:
        direction = "BULLISH"
        direction_color = "#059669"
    elif bear_score >= 4 and bear_score > bull_score:
        direction = "BEARISH"
        direction_color = "#dc2626"
    else:
        direction = "NEUTRAL"
        direction_color = "#6b7280"
    
    if direction == "NEUTRAL":
        return None  # Skip neutral-direction signals — not actionable
    
    # ── Strike selection guidance (no specific contract — stale data risk) ──
    if direction == "BULLISH":
        strike_guidance = f"~1-2% OTM calls (${round(current * 1.015, 2)}-${round(current * 1.02, 2)} strike range)"
        alt_strike = f"ATM calls at ${round(current, 2)} for higher delta"
    else:
        strike_guidance = f"~1-2% OTM puts (${round(current * 0.98, 2)}-${round(current * 0.985, 2)} strike range)"
        alt_strike = f"ATM puts at ${round(current, 2)} for higher delta"
    
    # ── Entry/stop on underlying ──
    if len(closes) >= 14:
        ranges = highs[-14:] - lows[-14:]
        atr = float(np.mean(ranges))
    else:
        atr = current * 0.02
    
    if direction == "BULLISH":
        entry_low = round(current * 0.995, 2)
        entry_high = round(current * 1.005, 2)
        stop_underlying = round(current - (1.5 * atr), 2)
        target_underlying = round(current + (2 * atr), 2)
    else:
        entry_low = round(current * 0.995, 2)
        entry_high = round(current * 1.005, 2)
        stop_underlying = round(current + (1.5 * atr), 2)
        target_underlying = round(current - (2 * atr), 2)
    
    # ── Confidence assessment ──
    activity_score = bull_score if direction == "BULLISH" else bear_score
    if activity_score >= 6:
        confidence_label = "Strong"
        confidence_pct = 65
    elif activity_score >= 4:
        confidence_label = "Moderate"
        confidence_pct = 55
    else:
        confidence_label = "Weak"
        confidence_pct = 45
    
    return {
        "symbol": sym,
        "price": current,
        "direction": direction,
        "direction_color": direction_color,
        "confidence_label": confidence_label,
        "confidence_pct": confidence_pct,
        "direction_reasons": direction_reasons,
        # Options metrics
        "call_put_volume_ratio": round(cp_vol_ratio, 2),
        "call_put_oi_ratio": round(cp_oi_ratio, 2),
        "total_options_volume": total_vol,
        "atm_iv": round(atm_iv * 100, 1) if atm_iv > 0 else None,
        "expected_move_pct": round(expected_move_pct, 2),
        "expected_move_1w_abs": round(expected_move_1w, 2),
        # Trade guidance
        "strike_guidance": strike_guidance,
        "alt_strike": alt_strike,
        "entry_zone": {"low": entry_low, "high": entry_high},
        "stop_underlying": stop_underlying,
        "target_underlying": target_underlying,
        # Options-specific risk notes
        "max_hold_hours": 4 if direction == "BULLISH" else 4,
        "profit_target_pct_on_option": 25,
        "stop_loss_pct_on_option": 30,
    }


async def _options_setup_india_upstox(email: str):
    """r52-option3: India Options Pulse using Upstox real-time F&O data.
    
    This function is invoked automatically when:
      1. User requests /api/options-setup-detector?region=IN
      2. _upstox_is_connected() returns True (user has activated F&O + OAuth'd)
    
    Unlike the Yahoo US path (15-min delayed), Upstox provides LIVE tick data
    so this scan is actually usable for 10-30 minute trades.
    
    Universe: NSE F&O underlyings — NIFTY, BANKNIFTY, SENSEX, FINNIFTY + top stocks
    """
    # Check cache
    cache = _options_setup_cache.get("IN", {})
    if cache.get("data") and time.time() - cache.get("ts", 0) < 180:  # 3-min cache for real-time
        return cache["data"]
    
    print(f"\n⚡ Options Setup India [UPSTOX REAL-TIME] scanning...")
    t0 = time.time()
    
    # India F&O universe — only symbols that have active options chains on NSE
    universe = [
        "NIFTY", "BANKNIFTY", "SENSEX", "FINNIFTY",  # Indices
        "RELIANCE", "HDFCBANK", "ICICIBANK", "INFY", "TCS", "SBIN",
        "AXISBANK", "KOTAKBANK", "LT", "ITC", "HINDUNILVR",
        "BAJFINANCE", "MARUTI", "TATASTEEL", "ADANIENT", "ADANIPORTS",
    ]
    
    candidates = []
    for sym in universe:
        try:
            # Use existing _upstox_get_option_chain (built in r37)
            upstox_result = await asyncio.get_event_loop().run_in_executor(
                None, _upstox_get_option_chain, sym
            )
            if not upstox_result or not upstox_result.get("success"):
                continue
            chain = upstox_result.get("chain") or []
            spot = float(upstox_result.get("underlying") or 0)
            if not chain or spot <= 0:
                continue
            
            # Aggregate volumes
            total_call_vol = sum(int(r.get("ce_volume") or 0) for r in chain)
            total_put_vol = sum(int(r.get("pe_volume") or 0) for r in chain)
            total_call_oi = sum(int(r.get("ce_oi") or 0) for r in chain)
            total_put_oi = sum(int(r.get("pe_oi") or 0) for r in chain)
            total_vol = total_call_vol + total_put_vol
            
            if total_vol < 1000:  # India F&O has much higher volumes than US
                continue
            
            cp_vol_ratio = total_call_vol / max(total_put_vol, 1)
            cp_oi_ratio = total_call_oi / max(total_put_oi, 1)
            
            # ATM IV
            atm_data = min(chain, key=lambda r: abs(float(r.get("strike") or 0) - spot))
            atm_iv = float(atm_data.get("ce_iv") or 0)
            
            # Expected move (1 week)
            if atm_iv > 0 and atm_iv < 3:
                expected_move_1w = spot * atm_iv * (7 / 365) ** 0.5
                expected_move_pct = (expected_move_1w / spot) * 100
            else:
                expected_move_1w = spot * 0.02
                expected_move_pct = 2.0
            
            # Direction: India has 1.0-1.5 baseline C/P ratio — adjust thresholds
            direction = None
            direction_color = "#6b7280"
            direction_reasons = []
            
            if cp_vol_ratio >= 1.8:
                direction = "BULLISH"
                direction_color = "#059669"
                direction_reasons.append(f"Heavy call flow (C/P volume {cp_vol_ratio:.2f}×)")
            elif cp_vol_ratio <= 0.6:
                direction = "BEARISH"
                direction_color = "#dc2626"
                direction_reasons.append(f"Heavy put flow (C/P volume {cp_vol_ratio:.2f}×)")
            else:
                continue  # Neutral — skip
            
            # Confidence
            if cp_vol_ratio >= 2.5 or cp_vol_ratio <= 0.4:
                confidence_label = "Strong"
                confidence_pct = 68  # Slightly higher for real-time data
            else:
                confidence_label = "Moderate"
                confidence_pct = 58
            
            # Strike guidance (India uses ₹)
            if direction == "BULLISH":
                atm_strike = round(spot / 50) * 50 if sym in ("NIFTY", "BANKNIFTY", "SENSEX") else round(spot / 10) * 10
                strike_guidance = f"ATM calls at ₹{atm_strike} strike (weekly expiry)"
                alt_strike = f"1-OTM calls at ₹{atm_strike + (50 if sym in ('NIFTY','BANKNIFTY','SENSEX') else 10)}"
            else:
                atm_strike = round(spot / 50) * 50 if sym in ("NIFTY", "BANKNIFTY", "SENSEX") else round(spot / 10) * 10
                strike_guidance = f"ATM puts at ₹{atm_strike} strike (weekly expiry)"
                alt_strike = f"1-OTM puts at ₹{atm_strike - (50 if sym in ('NIFTY','BANKNIFTY','SENSEX') else 10)}"
            
            # Entry/stop/target on underlying
            if direction == "BULLISH":
                entry_low = round(spot * 0.997, 2)
                entry_high = round(spot * 1.003, 2)
                stop_underlying = round(spot * 0.99, 2)
                target_underlying = round(spot * 1.012, 2)
            else:
                entry_low = round(spot * 0.997, 2)
                entry_high = round(spot * 1.003, 2)
                stop_underlying = round(spot * 1.01, 2)
                target_underlying = round(spot * 0.988, 2)
            
            candidates.append({
                "symbol": sym,
                "price": spot,
                "direction": direction,
                "direction_color": direction_color,
                "confidence_label": confidence_label,
                "confidence_pct": confidence_pct,
                "direction_reasons": direction_reasons,
                "call_put_volume_ratio": round(cp_vol_ratio, 2),
                "call_put_oi_ratio": round(cp_oi_ratio, 2),
                "total_options_volume": total_vol,
                "atm_iv": round(atm_iv * 100, 1) if atm_iv > 0 else None,
                "expected_move_pct": round(expected_move_pct, 2),
                "expected_move_1w_abs": round(expected_move_1w, 2),
                "strike_guidance": strike_guidance,
                "alt_strike": alt_strike,
                "entry_zone": {"low": entry_low, "high": entry_high},
                "stop_underlying": stop_underlying,
                "target_underlying": target_underlying,
                "max_hold_hours": 4,
                "profit_target_pct_on_option": 25,
                "stop_loss_pct_on_option": 30,
            })
        except Exception as _e:
            print(f"  ⚠ {sym}: {type(_e).__name__}: {_e}")
            continue
    
    candidates.sort(key=lambda x: (x["confidence_pct"], x["total_options_volume"]), reverse=True)
    bullish = [c for c in candidates if c["direction"] == "BULLISH"]
    bearish = [c for c in candidates if c["direction"] == "BEARISH"]
    
    elapsed = round(time.time() - t0, 1)
    print(f"  ✅ India Options Pulse [UPSTOX]: {len(bullish)} BULL + {len(bearish)} BEAR in {elapsed}s")
    try:
        diag_log("SCAN", "options_setup_india_upstox_completed", {
            "bullish": len(bullish), "bearish": len(bearish),
            "universe": len(universe), "elapsed_sec": elapsed,
        })
    except Exception: pass
    
    result = {
        "success": True,
        "region": "IN",
        "elapsed": elapsed,
        "universe_scanned": len(universe),
        "bullish": bullish,
        "bearish": bearish,
        "total_candidates": len(candidates),
        "data_freshness": "REAL-TIME (Upstox F&O)",
        "data_source": "upstox",
        "honest_disclaimer": (
            "✅ REAL-TIME DATA via Upstox F&O connection. Data is live — same quality "
            "you'd see in Upstox trading app. Still: always verify prices in your broker "
            "before placing orders. Max 1-2% portfolio per options trade."
        ),
        "how_to_use": [
            "1. Open Upstox app in parallel — keep market watch of these symbols",
            "2. Verify bid-ask spread is tight (< 2% of premium)",
            "3. Set profit target +25% on premium, stop at -30%",
            "4. Max hold: 4 hours. Most India F&O weekly ideas close same day or next",
            "5. Avoid trading 3:00-3:30 PM IST (gamma unwind chop)",
            "6. Verify no upcoming earnings/event before entering",
        ],
        "risk_warnings": [
            "Options can lose 100% of premium quickly",
            "Weekly expiry Thursday: theta decay accelerates Wed-Thu",
            "India F&O requires significant margin — ensure sufficient capital",
            "STT/GST/brokerage eats 0.3-0.5% per round trip",
            "Never hold through earnings/major events — IV crush",
        ],
    }
    _options_setup_cache["IN"] = {"ts": time.time(), "data": result}
    return result


@app.get("/api/options-setup-detector")
async def options_setup_detector(email: str = "", region: str = "US"):
    """r52: Detect stocks with unusual options activity suggesting short-term moves.
    
    Auto-selects data source:
      - US: Yahoo (15-min delayed) — always available
      - IN: Upstox real-time if F&O connected; otherwise prompts user to connect
    """
    email = email.strip().lower()
    # r63.5: replaced duplicated premium-gate boilerplate
    _ok, email = check_premium_gate(email, "dream")
    if not _ok:
        return {"success": False, "error": "This feature is exclusive. Contact support for access."}
    
    region = region.upper()
    if region not in ("US", "IN"):
        return {"success": False, "error": "region must be US or IN"}
    
    # Options data is only reliable for US via Yahoo; India options through Yahoo are sparse.
    # r52-option3: Auto-detect Upstox connection for India real-time path.
    if region == "IN":
        if _upstox_is_connected():
            # Upstox F&O connected — use real-time data path for India options
            return await _options_setup_india_upstox(email)
        else:
            return {
                "success": True,
                "region": "IN",
                "candidates": [],
                "bullish": [],
                "bearish": [],
                "total_candidates": 0,
                "upstox_status": "not_connected",
                "honest_disclaimer": (
                    "India options data via free Yahoo feed is SPARSE and UNRELIABLE. "
                    "For India options scanning, activate Upstox F&O (free, 1-2 days) — "
                    "once connected, this feature auto-upgrades to real-time India scanning. "
                    "Alternatively, Kite Connect (₹2000/mo) provides instant access."
                ),
                "broker_status_needed": True,
                "upstox_login_url": "/api/upstox-login",
            }
    
    # 15-min cache (matches Yahoo delay)
    cache = _options_setup_cache.get(region, {})
    if cache.get("data") and time.time() - cache.get("ts", 0) < 900:
        return cache["data"]
    
    print(f"\n🎯 Options Setup Detector scanning ({region})...")
    t0 = time.time()
    
    # Universe — use "recent_ipos" + "short_squeeze" + top liquid names (where options flow matters most)
    # This focuses the scan on tickers KNOWN to have liquid options markets
    universe = list(dict.fromkeys([
        # Mega-cap with deepest options markets
        "AAPL","MSFT","NVDA","AMD","META","GOOGL","AMZN","TSLA","NFLX","AVGO",
        "SPY","QQQ","IWM","DIA",  # indices/ETFs
        # Mid-cap momentum/squeeze names where options flow drives moves
        "SMCI","COIN","PLTR","CRWD","SHOP","SNOW","DDOG","UBER","ARM","RDDT",
        "MARA","RIOT","COIN","HOOD","SOFI","CAR","GME","AMC","CVNA","RIVN",
        "LCID","NIO","MRNA","VKTX","IONQ","RGTI","ASTS","RKLB","SMCI","SNDK",
    ]))
    yf_symbols = universe  # US region — no suffix
    
    # Batch price history
    import yfinance as yf
    try:
        _yahoo_rate_wait()
        hist_all = await asyncio.get_event_loop().run_in_executor(
            None,
            lambda: yf.download(
                tickers=" ".join(yf_symbols),
                period="3mo", interval="1d",
                group_by="ticker", progress=False, threads=True, auto_adjust=False,
            )
        )
    except Exception as _de:
        return {"success": False, "error": f"Batch fetch failed: {type(_de).__name__}"}
    
    def _get_hist(yf_sym):
        if hist_all is None or len(hist_all) == 0: return None
        try:
            if len(yf_symbols) == 1:
                return hist_all if len(hist_all) >= 30 else None
            if yf_sym not in hist_all.columns.get_level_values(0):
                return None
            sub = hist_all[yf_sym].dropna()
            return sub if len(sub) >= 30 else None
        except Exception:
            return None
    
    # Fetch options chains per ticker (can't batch)
    _sem = asyncio.Semaphore(4)
    
    async def _fetch_options(sym):
        async with _sem:
            try:
                hist = _get_hist(sym)
                if hist is None: return None
                current = float(hist['Close'].iloc[-1])
                if current <= 0: return None
                
                def _blocking_fetch():
                    try:
                        tk = yf.Ticker(sym)
                        info = tk.info or {}
                        expiries = tk.options
                        if not expiries or len(expiries) == 0:
                            return (info, None)
                        # Use nearest expiry (most active for short-term trades)
                        chain = tk.option_chain(expiries[0])
                        rows = []
                        if chain.calls is not None and chain.puts is not None:
                            for _, c_row in chain.calls.iterrows():
                                strike = float(c_row.get('strike') or 0)
                                # Keep only strikes within ±10% of spot
                                if abs(strike - current) / current > 0.10: continue
                                matching_put = chain.puts[chain.puts['strike'] == strike]
                                p_vol = int(matching_put['volume'].iloc[0]) if len(matching_put) > 0 else 0
                                p_oi = int(matching_put['openInterest'].iloc[0]) if len(matching_put) > 0 else 0
                                rows.append({
                                    "strike": strike,
                                    "ce_volume": int(c_row.get('volume') or 0),
                                    "pe_volume": p_vol,
                                    "ce_oi": int(c_row.get('openInterest') or 0),
                                    "pe_oi": p_oi,
                                    "ce_iv": float(c_row.get('impliedVolatility') or 0),
                                })
                        return (info, rows if rows else None)
                    except Exception:
                        return ({}, None)
                
                _yahoo_rate_wait()
                info, chain_data = await asyncio.get_event_loop().run_in_executor(None, _blocking_fetch)
                return _detect_options_setup(sym, region, info, hist, chain_data)
            except Exception as _e:
                return None
    
    tasks = [_fetch_options(s) for s in universe]
    raw = await asyncio.wait_for(asyncio.gather(*tasks), timeout=120)
    candidates = [r for r in raw if r]
    
    # Sort by confidence DESC, then by total options volume DESC
    candidates.sort(key=lambda x: (x["confidence_pct"], x["total_options_volume"]), reverse=True)
    
    # Bucket by direction
    bullish = [c for c in candidates if c["direction"] == "BULLISH"]
    bearish = [c for c in candidates if c["direction"] == "BEARISH"]
    
    elapsed = round(time.time() - t0, 1)
    print(f"  ✅ Options Setup: {len(bullish)} BULLISH + {len(bearish)} BEARISH candidates in {elapsed}s")
    try:
        diag_log("SCAN", "options_setup_completed", {
            "region": region, "bullish": len(bullish), "bearish": len(bearish),
            "universe": len(universe), "elapsed_sec": elapsed,
        })
    except Exception: pass
    
    result = {
        "success": True,
        "region": region,
        "elapsed": elapsed,
        "universe_scanned": len(universe),
        "bullish": bullish,
        "bearish": bearish,
        "total_candidates": len(candidates),
        "data_freshness": "15-min delayed (Yahoo free tier)",
        "honest_disclaimer": (
            "⚠ CRITICAL: This uses 15-MIN DELAYED data. It is a SCREENER, NOT a live trade feed. "
            "For actual execution: use your broker's real-time quotes (Kite/Upstox/IBKR). "
            "Retail options slippage is 0.5-1.5% — always assume worst-case fills. "
            "90%+ of retail 0DTE traders lose money long-term. "
            "Max 1-2% portfolio per options trade. "
            "If you're new to options, paper-trade first for 3 months."
        ),
        "how_to_use": [
            "1. Identify candidates here — DO NOT trade off these prices directly",
            "2. Open your broker app — verify price is still valid (real-time)",
            "3. Check bid-ask spread — if wider than 3% of premium, SKIP",
            "4. Set profit target at +25% on premium, stop at -30% on premium",
            "5. Max hold: 4 hours. Close before expiry if not moved",
            "6. Do NOT add to losers. Accept the stop.",
        ],
        "risk_warnings": [
            "Options can lose 100% of premium in minutes",
            "0DTE (same-day expiry) options: pure gambling without real-time data",
            "Never trade within 15 min of close (gamma unwind creates chop)",
            "Earnings-week options: IV crush can wipe out gains even on correct direction",
            "This scanner does NOT check for upcoming earnings — always verify before trading",
        ],
    }
    _options_setup_cache[region] = {"ts": time.time(), "data": result}
    return result


# ═══════════════════════════════════════════════════════════════════════
# TRADE TICKET GENERATOR (r54)
#
# Purpose: Produce a complete institutional-style options trade plan for
# any symbol. Real data, real calculations — no LLM hallucination.
#
# Inputs:  symbol, region (US/IN), capital, risk_pct
# Output:  full trade ticket with strike, expiry, sizing, stops, targets,
#          risk flags, and exit rules.
#
# Design principles:
#   1. Strike selection by DELTA target (institutional standard), not arbitrary OTM
#   2. Expiry selection by IV term structure + theta/gamma sweet spot
#   3. Stop loss = ATR-based volatility-adjusted (not arbitrary -X%)
#   4. Position size = max(loss_at_stop ≤ risk_pct × capital, 1 contract)
#   5. Targets = R:R ratios computed from chosen stop, NOT random round numbers
#   6. Risk flags surface ANY issue that could impact the trade
#
# Honest scope:
#   - US: yfinance options chain (15-min delayed). Premium estimates use mid-price.
#   - IN: Upstox real-time IF connected; otherwise prompts to connect
#   - Outputs are institutional QUALITY, not 99% guarantees. Win rate same as
#     the underlying scanner (~55-65% for high-conviction setups).
# ═══════════════════════════════════════════════════════════════════════

_trade_ticket_cache = {}  # {f"{symbol}_{region}_{capital}_{risk}": {ts, data}}


def _delta_to_strike(spot, calls_df, target_delta=0.50):
    """Pick strike whose delta is closest to target. Falls back to nearest-to-spot
    if delta column unavailable.
    
    Institutional standard:
      0.50 delta = ATM (max gamma, balanced exposure)
      0.30 delta = ~1 std OTM (limited risk, lottery-like)
      0.70 delta = ITM (more direction, less leverage)
    """
    if calls_df is None or len(calls_df) == 0:
        return None
    try:
        # Yahoo provides 'inTheMoney' but not delta directly. Approximate using moneyness.
        # For practical purposes: closest-to-spot strike ≈ 0.50 delta for ATM-targeted trades.
        # If delta column exists (e.g., from Upstox), use it.
        if 'delta' in calls_df.columns:
            calls_df = calls_df.copy()
            calls_df['delta_diff'] = (calls_df['delta'] - target_delta).abs()
            best = calls_df.loc[calls_df['delta_diff'].idxmin()]
            return best
        # Fallback: pick strike closest to spot (delta ≈ 0.50)
        calls_df = calls_df.copy()
        calls_df['strike_diff'] = (calls_df['strike'] - spot).abs()
        best = calls_df.loc[calls_df['strike_diff'].idxmin()]
        return best
    except Exception:
        return None


def _select_optimal_expiry(expiries, target_dte=14):
    """Pick expiry closest to target days-to-expiration.
    
    Institutional sweet spot for directional trades:
      14-30 DTE: enough time for thesis to play out, theta not yet accelerated
    Avoid:
      0-7 DTE: theta decay too fast, gamma whipsaw
      >45 DTE: capital tied up, slow movement, IV opportunity loss
    """
    from datetime import datetime as _dt, timezone as _tz
    if not expiries: return None
    today = _dt.now(_tz.utc).date()
    best = None
    best_diff = float('inf')
    for exp_str in expiries:
        try:
            exp_date = _dt.strptime(exp_str, "%Y-%m-%d").date()
            dte = (exp_date - today).days
            if dte < 5: continue  # Skip 0DTE/weekly traps
            diff = abs(dte - target_dte)
            if diff < best_diff:
                best = (exp_str, dte)
                best_diff = diff
        except Exception:
            continue
    return best


def _check_earnings_proximity(info, target_dte):
    """Returns (has_earnings_within, days_until_earnings, warning_text).
    
    Critical for options: earnings cause IV crush regardless of direction.
    Even if we pick the direction right, IV crush can wipe out 30-50% of premium.
    """
    try:
        from datetime import datetime as _dt
        # yfinance puts earnings in info.earningsDate or earningsTimestamp
        earnings_ts = info.get("earningsTimestamp") or info.get("earningsDate")
        if not earnings_ts: return (False, None, None)
        if isinstance(earnings_ts, list) and len(earnings_ts) > 0:
            earnings_ts = earnings_ts[0]
        if isinstance(earnings_ts, (int, float)) and earnings_ts > 0:
            days_until = int((earnings_ts - time.time()) / 86400)
            if days_until < 0: return (False, days_until, None)  # past earnings
            if days_until <= target_dte:
                return (True, days_until,
                       f"⚠ EARNINGS IN {days_until} DAYS — IV crush risk. Consider skipping or reduce size.")
            return (False, days_until, None)
    except Exception:
        pass
    return (False, None, None)


def _compute_iv_percentile(hist_df, current_iv):
    """Approximate IV percentile from realized vol over past year.
    
    Institutional: don't buy options when IV is rich (>70th pctile), don't sell when cheap.
    """
    import numpy as np
    if hist_df is None or len(hist_df) < 60 or current_iv is None or current_iv <= 0:
        return None
    try:
        closes = hist_df['Close'].values
        # Compute 20-day realized vol annualized
        rolling_vols = []
        for i in range(20, len(closes)):
            window_returns = np.diff(np.log(closes[i-20:i]))
            ann_vol = float(np.std(window_returns)) * (252 ** 0.5)
            rolling_vols.append(ann_vol)
        if not rolling_vols: return None
        pctile = sum(1 for v in rolling_vols if v < current_iv) / len(rolling_vols) * 100
        return round(pctile, 1)
    except Exception:
        return None


@app.get("/api/trade-ticket")
async def trade_ticket(
    email: str = "",
    symbol: str = "",
    region: str = "US",
    direction: str = "auto",   # auto | bullish | bearish
    capital: float = 100000,
    risk_pct: float = 1.0,
    delta_target: float = 0.50,  # 0.30/0.50/0.70 = OTM/ATM/ITM
    target_dte: int = 14,
):
    """Generate a complete options trade ticket for a symbol.
    
    Returns institutional-style trade plan:
      - Contract specification (strike, expiry, premium estimate)
      - Position sizing (number of contracts based on capital + risk%)
      - Stop loss + targets (volatility-adjusted)
      - Risk flags (earnings, IV percentile, liquidity)
      - Exit rules
    """
    email = email.strip().lower()
    # r63.5: replaced duplicated premium-gate boilerplate
    _ok, email = check_premium_gate(email, "dream")
    if not _ok:
        return {"success": False, "error": "This feature is exclusive. Contact support for access."}
    
    symbol = symbol.strip().upper()
    if not symbol:
        return {"success": False, "error": "symbol required"}
    region = region.upper()
    if region not in ("US", "IN"):
        return {"success": False, "error": "region must be US or IN"}
    if region == "IN" and not _upstox_is_connected():
        return {
            "success": False,
            "error": "India options require Upstox F&O connection. Activate F&O on Upstox app + connect via /api/upstox-login",
            "broker_status_needed": True,
        }
    
    # Cache key — short TTL (5 min) since live trade ticket
    cache_key = f"{symbol}_{region}_{int(capital)}_{risk_pct}_{delta_target}_{target_dte}_{direction}"
    cache = _trade_ticket_cache.get(cache_key)
    if cache and time.time() - cache.get("ts", 0) < 300:
        return cache["data"]
    
    print(f"\n🎫 Trade Ticket: {symbol} ({region}) cap=₹{int(capital)} risk={risk_pct}%")
    t0 = time.time()
    
    try:
        import yfinance as yf
        import numpy as np
        from datetime import datetime as _dt
        yf_sym = symbol if region == "US" else symbol + ".NS"
        
        # ── Fetch price history (60d for ATR, RSI, MA calcs) ──
        _yahoo_rate_wait()
        tk = yf.Ticker(yf_sym)
        try:
            hist = tk.history(period="3mo", interval="1d")
        except Exception as _he:
            return {"success": False, "error": f"Failed to fetch price history: {type(_he).__name__}"}
        if hist is None or len(hist) < 30:
            return {"success": False, "error": f"Insufficient price history for {symbol}"}
        
        try: info = tk.info or {}
        except Exception: info = {}
        
        closes = hist['Close'].values
        highs = hist['High'].values
        lows = hist['Low'].values
        volumes = hist['Volume'].values
        spot = float(closes[-1])
        if spot <= 0:
            return {"success": False, "error": "Invalid spot price"}
        
        # ── Determine direction (auto = use technicals) ──
        if direction == "auto":
            ma_20 = float(np.mean(closes[-20:]))
            ma_50 = float(np.mean(closes[-50:])) if len(closes) >= 50 else ma_20
            if spot > ma_20 > ma_50:
                direction = "bullish"
            elif spot < ma_20 < ma_50:
                direction = "bearish"
            else:
                # No clear trend — default to bullish (most common retail bias)
                direction = "bullish"
        
        # ── ATR for volatility-adjusted stops ──
        atr_period = 14
        atr_ranges = highs[-atr_period:] - lows[-atr_period:]
        atr = float(np.mean(atr_ranges))
        atr_pct = (atr / spot) * 100
        
        # ── Options chain ──
        if region == "US":
            try:
                _yahoo_rate_wait()
                expiries = tk.options
                if not expiries:
                    return {"success": False, "error": f"No options chain available for {symbol}"}
            except Exception as _oe:
                return {"success": False, "error": f"Options fetch failed: {type(_oe).__name__}"}
            
            # Select optimal expiry
            exp_choice = _select_optimal_expiry(expiries, target_dte=target_dte)
            if not exp_choice:
                return {"success": False, "error": "No suitable expiry within target DTE range"}
            chosen_expiry, chosen_dte = exp_choice
            
            try:
                _yahoo_rate_wait()
                chain = tk.option_chain(chosen_expiry)
            except Exception as _ce:
                return {"success": False, "error": f"Option chain fetch failed: {type(_ce).__name__}"}
            
            df_to_use = chain.calls if direction == "bullish" else chain.puts
            if df_to_use is None or len(df_to_use) == 0:
                return {"success": False, "error": "Empty options chain"}
            
            # Filter for liquid strikes only (volume > 0 OR open interest > 100)
            liquid = df_to_use[(df_to_use.get('volume', 0) > 0) | (df_to_use.get('openInterest', 0) > 100)]
            if len(liquid) > 0:
                df_to_use = liquid
            
            # Strike selection by delta target (or nearest-to-spot fallback)
            chosen_row = _delta_to_strike(spot, df_to_use, target_delta=delta_target)
            if chosen_row is None:
                return {"success": False, "error": "Could not select strike"}
            
            chosen_strike = float(chosen_row.get('strike') or 0)
            premium_bid = float(chosen_row.get('bid') or 0)
            premium_ask = float(chosen_row.get('ask') or 0)
            premium_last = float(chosen_row.get('lastPrice') or 0)
            premium_mid = (premium_bid + premium_ask) / 2 if premium_bid > 0 and premium_ask > 0 else premium_last
            iv = float(chosen_row.get('impliedVolatility') or 0)
            volume_strike = int(chosen_row.get('volume') or 0)
            oi_strike = int(chosen_row.get('openInterest') or 0)
            
            # Bid-ask spread quality check
            spread_pct = ((premium_ask - premium_bid) / max(premium_mid, 0.01)) * 100 if premium_bid > 0 and premium_ask > 0 else 999
            
            csym = "$"
            lot_size = 100  # US standard
            
        else:
            # India path via Upstox (real-time)
            try:
                upstox_result = await asyncio.get_event_loop().run_in_executor(
                    None, _upstox_get_option_chain, symbol
                )
            except Exception as _ue:
                return {"success": False, "error": f"Upstox fetch failed: {type(_ue).__name__}"}
            if not upstox_result or not upstox_result.get("success"):
                return {"success": False, "error": upstox_result.get("error") if upstox_result else "Upstox returned no data"}
            
            chain_rows = upstox_result.get("chain") or []
            if not chain_rows:
                return {"success": False, "error": f"Empty chain for {symbol}"}
            
            # Pick strike closest to spot (ATM default for India)
            spot_up = float(upstox_result.get("underlying") or spot)
            spot = spot_up if spot_up > 0 else spot
            chain_sorted = sorted(chain_rows, key=lambda r: abs(float(r.get("strike") or 0) - spot))
            chosen_row_dict = chain_sorted[0]
            chosen_strike = float(chosen_row_dict.get("strike") or 0)
            
            if direction == "bullish":
                premium_last = float(chosen_row_dict.get("ce_ltp") or 0)
                premium_bid = float(chosen_row_dict.get("ce_bid") or premium_last * 0.98)
                premium_ask = float(chosen_row_dict.get("ce_ask") or premium_last * 1.02)
                volume_strike = int(chosen_row_dict.get("ce_volume") or 0)
                oi_strike = int(chosen_row_dict.get("ce_oi") or 0)
                iv = float(chosen_row_dict.get("ce_iv") or 0)
            else:
                premium_last = float(chosen_row_dict.get("pe_ltp") or 0)
                premium_bid = float(chosen_row_dict.get("pe_bid") or premium_last * 0.98)
                premium_ask = float(chosen_row_dict.get("pe_ask") or premium_last * 1.02)
                volume_strike = int(chosen_row_dict.get("pe_volume") or 0)
                oi_strike = int(chosen_row_dict.get("pe_oi") or 0)
                iv = float(chosen_row_dict.get("pe_iv") or 0)
            premium_mid = (premium_bid + premium_ask) / 2 if premium_bid > 0 else premium_last
            spread_pct = ((premium_ask - premium_bid) / max(premium_mid, 0.01)) * 100 if premium_bid > 0 else 999
            
            chosen_expiry = upstox_result.get("expiry") or "weekly"
            chosen_dte = 7  # weekly assumption for India
            
            csym = "₹"
            # India F&O lot sizes
            india_lots = {"NIFTY": 75, "BANKNIFTY": 30, "SENSEX": 20, "FINNIFTY": 65}
            lot_size = india_lots.get(symbol, 1)
        
        if premium_mid <= 0:
            return {"success": False, "error": "Could not determine valid premium price"}
        
        # ── POSITION SIZING (Kelly-influenced, capped) ──
        # Risk per trade in absolute terms
        max_loss_inr = capital * (risk_pct / 100)
        # Stop loss on premium = -30% (institutional standard for directional options)
        stop_premium_pct = 30
        loss_per_contract = premium_mid * (stop_premium_pct / 100) * lot_size
        if loss_per_contract <= 0: loss_per_contract = premium_mid * 0.30 * lot_size
        contracts = max(1, int(max_loss_inr / loss_per_contract))
        # Cap at sensible max — never put more than 10% of capital in premium
        max_contracts_by_capital = int((capital * 0.10) / (premium_mid * lot_size))
        contracts = min(contracts, max(1, max_contracts_by_capital))
        total_premium_paid = contracts * premium_mid * lot_size
        total_risk_at_stop = contracts * (premium_mid * stop_premium_pct / 100) * lot_size
        
        # ── TARGETS ──
        # T1: +30% on premium (1:1 R:R if stop at -30%)
        target_1_premium = round(premium_mid * 1.30, 2)
        # T2: +70% on premium (~2.3:1 R:R)
        target_2_premium = round(premium_mid * 1.70, 2)
        # Stop on premium
        stop_premium = round(premium_mid * 0.70, 2)
        
        # On underlying (informational)
        if direction == "bullish":
            target_1_underlying = round(spot + (1.0 * atr), 2)
            target_2_underlying = round(spot + (2.0 * atr), 2)
            stop_underlying = round(spot - (1.5 * atr), 2)
        else:
            target_1_underlying = round(spot - (1.0 * atr), 2)
            target_2_underlying = round(spot - (2.0 * atr), 2)
            stop_underlying = round(spot + (1.5 * atr), 2)
        
        # ── RISK FLAGS ──
        risk_flags = []
        # Earnings proximity
        has_earnings, days_to_earnings, earnings_warning = _check_earnings_proximity(info, chosen_dte)
        if has_earnings and earnings_warning:
            risk_flags.append({"icon": "⚠", "level": "high", "text": earnings_warning})
        elif days_to_earnings is not None and days_to_earnings > chosen_dte:
            risk_flags.append({"icon": "✓", "level": "ok", "text": f"No earnings within {chosen_dte} days (next: {days_to_earnings}d out)"})
        else:
            risk_flags.append({"icon": "?", "level": "info", "text": "Earnings date unknown — verify before entering"})
        
        # IV percentile
        iv_pctile = _compute_iv_percentile(hist, iv) if iv > 0 else None
        if iv_pctile is not None:
            if iv_pctile >= 70:
                risk_flags.append({"icon": "⚠", "level": "warn",
                                   "text": f"IV percentile {iv_pctile}% — premium is RICH. Consider call/put spread to reduce cost."})
            elif iv_pctile <= 30:
                risk_flags.append({"icon": "✓", "level": "ok",
                                   "text": f"IV percentile {iv_pctile}% — premium is reasonable for buying."})
        
        # Bid-ask spread
        if spread_pct > 5:
            risk_flags.append({"icon": "⚠", "level": "high",
                              "text": f"Wide bid-ask spread ({spread_pct:.1f}%) — slippage risk. SKIP if >5%."})
        elif spread_pct > 3:
            risk_flags.append({"icon": "⚠", "level": "warn",
                              "text": f"Bid-ask spread {spread_pct:.1f}% — moderate slippage."})
        else:
            risk_flags.append({"icon": "✓", "level": "ok",
                              "text": f"Tight bid-ask spread ({spread_pct:.1f}%) — good fill expected."})
        
        # Liquidity
        if volume_strike < 10 and oi_strike < 100:
            risk_flags.append({"icon": "⚠", "level": "high",
                              "text": f"Low liquidity (vol={volume_strike}, OI={oi_strike}) — exit may be difficult"})
        
        # Capital concentration
        if total_premium_paid / capital > 0.05:
            risk_flags.append({"icon": "⚠", "level": "warn",
                              "text": f"{round(total_premium_paid/capital*100,1)}% of capital in this trade — consider reducing size"})
        
        # ── EXIT RULES ──
        exit_rules = [
            f"At T1 ({csym}{target_1_premium}): SELL 50% of contracts, trail stop to entry on remainder",
            f"At T2 ({csym}{target_2_premium}): SELL remaining 50%",
            f"At Stop ({csym}{stop_premium}): CLOSE entire position. NO averaging down.",
            f"Time-stop: If neither T1 nor stop hit by Wednesday close (assuming weekly expiry): CLOSE",
            f"Theta cutoff: 7 days before expiry, accelerated decay — close even at small loss/gain",
        ]
        
        elapsed = round(time.time() - t0, 2)
        
        result = {
            "success": True,
            "generated_at": _dt.utcnow().isoformat(),
            "elapsed_sec": elapsed,
            "symbol": symbol,
            "region": region,
            "currency_symbol": csym,
            
            # Underlying state
            "underlying": {
                "spot": round(spot, 2),
                "direction": direction.upper(),
                "atr": round(atr, 2),
                "atr_pct": round(atr_pct, 2),
                "company_name": info.get("longName") or info.get("shortName") or symbol,
            },
            
            # Contract specification
            "contract": {
                "type": "CALL" if direction == "bullish" else "PUT",
                "strike": round(chosen_strike, 2),
                "expiry": chosen_expiry,
                "dte": chosen_dte,
                "premium_mid": round(premium_mid, 2),
                "premium_bid": round(premium_bid, 2),
                "premium_ask": round(premium_ask, 2),
                "lot_size": lot_size,
                "iv_pct": round(iv * 100, 1) if iv > 0 else None,
                "iv_percentile": iv_pctile,
                "volume": volume_strike,
                "open_interest": oi_strike,
                "spread_pct": round(spread_pct, 2),
            },
            
            # Position sizing
            "sizing": {
                "capital": int(capital),
                "risk_pct": risk_pct,
                "max_risk_amount": int(round(max_loss_inr)),
                "contracts": contracts,
                "total_premium_paid": int(round(total_premium_paid)),
                "total_risk_at_stop": int(round(total_risk_at_stop)),
                "capital_committed_pct": round(total_premium_paid / capital * 100, 2),
            },
            
            # Trade plan
            "plan": {
                "stop_premium": stop_premium,
                "target_1_premium": target_1_premium,
                "target_2_premium": target_2_premium,
                "stop_underlying": stop_underlying,
                "target_1_underlying": target_1_underlying,
                "target_2_underlying": target_2_underlying,
                "rr_to_t1": 1.0,
                "rr_to_t2": 2.33,
            },
            
            # Risk flags
            "risk_flags": risk_flags,
            
            # Exit rules
            "exit_rules": exit_rules,
            
            # Honest disclaimer
            "honest_disclaimer": (
                "This is a TRADE PLAN, not a guaranteed winner. Win rates for directional "
                "options trades typically 40-55%. The +R:R ratios make EV positive when discipline "
                "is maintained — i.e., when stops are honored without averaging down. "
                + ("Premium estimates use 15-min delayed data — verify on broker before entering. " if region == "US" else "Real-time via Upstox. ")
                + "Max 1-2% portfolio per trade. No system is 99% accurate."
            ),
            
            # Order ticket (copy-paste friendly)
            "order_ticket_text": (
                f"BUY {contracts} × {symbol} {chosen_expiry} {round(chosen_strike,2)} "
                f"{'CALL' if direction == 'bullish' else 'PUT'} "
                f"@ LIMIT {csym}{round(premium_mid, 2)} "
                f"(STOP: {csym}{stop_premium}, T1: {csym}{target_1_premium}, T2: {csym}{target_2_premium})"
            ),
        }
        
        _trade_ticket_cache[cache_key] = {"ts": time.time(), "data": result}
        try: diag_log("TICKET", "trade_ticket_generated", {
            "symbol": symbol, "region": region, "direction": direction,
            "contracts": contracts, "premium": round(premium_mid, 2),
            "elapsed_sec": elapsed,
        })
        except Exception: pass
        return result
        
    except Exception as _e:
        print(f"  ❌ Trade ticket error: {type(_e).__name__}: {_e}")
        return {
            "success": False,
            "error": f"{type(_e).__name__}: {str(_e)[:200]}",
        }


