def _find_similar_extract_profile(dd_response):
    """Extract the similarity-relevant fields from a DD response dict.
    Returns None if data is too sparse to compare."""
    if not dd_response or not dd_response.get("success"):
        return None
    bottom = dd_response.get("bottom_line") or {}
    finance = dd_response.get("finance") or {}
    thesis = dd_response.get("thesis") or {}
    institutional = dd_response.get("institutional") or {}
    company = dd_response.get("company") or {}

    score = _safe_float(bottom.get("score"), 0)
    if score <= 0:
        return None

    profile = {
        "verdict_score":      score,
        "verdict_label":      bottom.get("verdict", "NEUTRAL"),
        "price":              _safe_float(company.get("price"), 0),
        "currency_symbol":    dd_response.get("currency_symbol", "$"),
        "name":               company.get("name", ""),
        "sector":             company.get("sector", ""),
        # Fundamental dimensions
        "profit_margin":      _safe_float(finance.get("profit_margin"), 0),
        "operating_margin":   _safe_float(finance.get("operating_margin"), 0),
        "gross_margin":       _safe_float(finance.get("gross_margin"), 0),
        "roe":                _safe_float(finance.get("roe"), 0),
        "revenue_growth":     _safe_float(finance.get("revenue_growth"), 0),
        "earnings_growth":    _safe_float(finance.get("earnings_growth"), 0),
        # Risk/momentum dimensions
        "sharpe":             _safe_float(institutional.get("sharpe"), 0),
        "max_drawdown":       _safe_float(institutional.get("max_dd"), 0),
        "ret_1y":             _safe_float(institutional.get("ret_1y"), 0),
        "beta":               _safe_float(thesis.get("beta"), 1.0),
    }
    return profile


def _find_similar_compute_score(ref_profile, cand_profile):
    """Compute 0-100 similarity score between reference and candidate.
    Higher = more similar. Returns dict with breakdown."""
    if not ref_profile or not cand_profile:
        return None

    # 1. Verdict proximity (40% weight)
    # Closer scores = higher proximity. Max gap considered = 30 points.
    verdict_gap = abs(ref_profile["verdict_score"] - cand_profile["verdict_score"])
    verdict_proximity = max(0, 100 - (verdict_gap * 100 / 30))

    # 2. Fundamental distance (35% weight)
    # Normalized Euclidean distance across 5 fundamental dimensions
    fund_dims = [
        ("profit_margin",   100),    # max realistic spread
        ("operating_margin", 100),
        ("gross_margin",    100),
        ("roe",             50),
        ("revenue_growth",  100),
    ]
    fund_sq_sum = 0.0
    for dim, max_spread in fund_dims:
        ref_v = ref_profile.get(dim, 0)
        cand_v = cand_profile.get(dim, 0)
        # Normalize: distance as fraction of max_spread
        norm_diff = min(abs(ref_v - cand_v), max_spread) / max_spread
        fund_sq_sum += norm_diff ** 2
    # RMS distance, then convert to similarity
    fund_dist = (fund_sq_sum / len(fund_dims)) ** 0.5
    fund_proximity = max(0, 100 - fund_dist * 100)

    # 3. Risk/momentum distance (25% weight)
    risk_dims = [
        ("sharpe",       3),         # Sharpe ratio: 0-3 normal range
        ("ret_1y",       100),       # 1Y return: -100% to +100%
        ("beta",         2),         # Beta: 0-2 normal range
    ]
    risk_sq_sum = 0.0
    for dim, max_spread in risk_dims:
        ref_v = ref_profile.get(dim, 0)
        cand_v = cand_profile.get(dim, 0)
        norm_diff = min(abs(ref_v - cand_v), max_spread) / max_spread
        risk_sq_sum += norm_diff ** 2
    risk_dist = (risk_sq_sum / len(risk_dims)) ** 0.5
    risk_proximity = max(0, 100 - risk_dist * 100)

    # Weighted total
    total = (
        0.40 * verdict_proximity +
        0.35 * fund_proximity +
        0.25 * risk_proximity
    )

    # Identify top matching factors for transparency
    matches = []
    if abs(ref_profile["verdict_score"] - cand_profile["verdict_score"]) < 8:
        matches.append(f"Both score {int(cand_profile['verdict_score'])}/100 ({cand_profile['verdict_label']})")
    if abs(ref_profile.get("revenue_growth", 0) - cand_profile.get("revenue_growth", 0)) < 10:
        matches.append(f"Similar revenue growth ({cand_profile.get('revenue_growth', 0):.0f}%)")
    if abs(ref_profile.get("roe", 0) - cand_profile.get("roe", 0)) < 5:
        matches.append(f"Similar ROE ({cand_profile.get('roe', 0):.0f}%)")
    if abs(ref_profile.get("profit_margin", 0) - cand_profile.get("profit_margin", 0)) < 5:
        matches.append(f"Similar profit margin ({cand_profile.get('profit_margin', 0):.0f}%)")
    if ref_profile.get("sector") and ref_profile["sector"] == cand_profile.get("sector"):
        matches.append(f"Same sector ({cand_profile['sector']})")

    return {
        "score": round(total, 1),
        "breakdown": {
            "verdict": round(verdict_proximity, 1),
            "fundamentals": round(fund_proximity, 1),
            "risk_momentum": round(risk_proximity, 1),
        },
        "matches": matches[:3],  # top 3 matching factors
    }


@app.get("/api/find-similar-stocks")
async def find_similar_stocks(
    reference: str = "",
    region: str = "US",
    email: str = "",
    nocache: int = 0,
):
    """r63.6: Find stocks similar to a reference ticker, bucketed by price tier.
    
    Args:
        reference: Reference ticker (e.g., "MU")
        region: "US" or "IN" — determines universe + bucket currency
        email: Premium gate (Dream tier required)
        nocache: 1 to bypass cache
    
    Returns:
        {
          "success": true,
          "reference": {ticker, score, price, ...},
          "buckets": {
            "penny":  {label, range, results: [...]},
            "low":    {...},
            "mid":    {...},
            "high":   {...},
            "ultra":  {...}
          },
          "scanned": int,
          "elapsed_sec": float
        }
    """
    import time, asyncio, math
    
    email = (email or "").strip().lower()
    _ok, email = check_premium_gate(email, "dream")
    if not _ok:
        return {"success": False, "error": "Find Similar Stocks is a premium feature."}
    
    reference = (reference or "").strip().upper()
    region = (region or "US").upper()
    if not reference:
        return {"success": False, "error": "reference ticker required"}
    if region not in ("US", "IN"):
        return {"success": False, "error": "region must be US or IN"}
    
    # Cache check
    cache_key = f"find_similar_{reference}_{region}"
    if nocache != 1:
        cached = _smart_cache_get(cache_key)
        if cached:
            cached["_cached"] = True
            return cached
    
    t0 = time.time()
    print("\n" + "="*60)
    print(f"🔍 FIND SIMILAR: reference={reference} region={region}")
    print("="*60)
    
    # Step 1: Get DD profile for reference ticker
    try:
        ref_dd = await investor_due_diligence(email=email, symbol=reference, region=region)
    except Exception as e:
        return {"success": False, "error": f"Could not fetch reference DD: {str(e)[:150]}"}
    
    if not ref_dd.get("success"):
        return {"success": False, "error": f"Reference DD failed: {ref_dd.get('error', 'unknown')}"}
    
    ref_profile = _find_similar_extract_profile(ref_dd)
    if not ref_profile:
        return {"success": False, "error": f"Reference {reference} has insufficient data for comparison"}
    
    print(f"  📊 Reference profile: score={ref_profile['verdict_score']:.0f} price={ref_profile['currency_symbol']}{ref_profile['price']:.2f} sector={ref_profile['sector']}")
    
    # Step 2: Pick universe + buckets
    if region == "US":
        universe = list(dict.fromkeys(_FIND_SIMILAR_US_UNIVERSE))
        buckets = _FIND_SIMILAR_BUCKETS_US
    else:
        universe = list(dict.fromkeys(_FIND_SIMILAR_IN_UNIVERSE))
        buckets = _FIND_SIMILAR_BUCKETS_IN
    
    # Remove the reference itself from universe
    universe = [t for t in universe if t.upper() != reference.upper()]
    print(f"  🎯 Scanning {len(universe)} candidates")
    
    # Step 3: Fetch DD for each candidate (in parallel batches)
    # Note: investor_due_diligence is async + cached, so this is fast on warm cache
    # On cold cache, scan takes ~3-4 minutes for 100+ tickers due to Finnhub rate limit
    
    # r63.7: bumped from 8 → 20 per user request. Note: internal _pace()
    # in finnhub_handlers serializes by 1.2s, so effective throughput depends
    # more on rate limit than concurrency. If Finnhub starts 429ing, lower this.
    BATCH_SIZE = int(os.getenv("FIND_SIMILAR_BATCH_SIZE", "20"))
    candidates = []
    
    async def _fetch_one(ticker):
        try:
            dd = await investor_due_diligence(email=email, symbol=ticker, region=region)
            profile = _find_similar_extract_profile(dd)
            if not profile:
                return None
            sim = _find_similar_compute_score(ref_profile, profile)
            if not sim:
                return None
            return {
                "ticker": ticker,
                "name": profile["name"] or ticker,
                "price": profile["price"],
                "currency_symbol": profile["currency_symbol"],
                "verdict_score": profile["verdict_score"],
                "verdict_label": profile["verdict_label"],
                "sector": profile["sector"],
                "similarity": sim["score"],
                "breakdown": sim["breakdown"],
                "matches": sim["matches"],
            }
        except Exception as e:
            print(f"    ⚠️  {ticker} failed: {type(e).__name__}: {str(e)[:80]}")
            return None
    
    for i in range(0, len(universe), BATCH_SIZE):
        batch = universe[i:i+BATCH_SIZE]
        results = await asyncio.gather(*[_fetch_one(t) for t in batch], return_exceptions=False)
        for r in results:
            if r is not None:
                candidates.append(r)
        elapsed = time.time() - t0
        print(f"  📈 Batch {i//BATCH_SIZE + 1}/{(len(universe)+BATCH_SIZE-1)//BATCH_SIZE} done — {len(candidates)} matches so far ({elapsed:.0f}s)")
    
    print(f"  ✅ Scanned {len(universe)} → {len(candidates)} valid candidates")
    
    # Step 4: Bucket candidates by price tier
    bucket_results = {}
    for bkey, bmin, bmax, blabel in buckets:
        bucket_results[bkey] = {
            "label": blabel,
            "range_min": bmin,
            "range_max": bmax if bmax < 9e8 else None,
            "results": [],
        }
    
    for c in candidates:
        price = c["price"]
        if price <= 0:
            continue
        for bkey, bmin, bmax, _ in buckets:
            if bmin <= price < bmax:
                bucket_results[bkey]["results"].append(c)
                break
    
    # Step 5: Sort each bucket by similarity (desc), keep top 5
    for bkey in bucket_results:
        bucket_results[bkey]["results"].sort(key=lambda x: x["similarity"], reverse=True)
        bucket_results[bkey]["results"] = bucket_results[bkey]["results"][:5]
        bucket_results[bkey]["count"] = len(bucket_results[bkey]["results"])
    
    elapsed = round(time.time() - t0, 1)
    
    response = {
        "success": True,
        "reference": {
            "ticker": reference,
            "name": ref_profile["name"] or reference,
            "price": ref_profile["price"],
            "currency_symbol": ref_profile["currency_symbol"],
            "verdict_score": ref_profile["verdict_score"],
            "verdict_label": ref_profile["verdict_label"],
            "sector": ref_profile["sector"],
        },
        "region": region,
        "buckets": bucket_results,
        "scanned": len(universe),
        "valid": len(candidates),
        "elapsed_sec": elapsed,
        "_cached": False,
        "weighting": {
            "verdict_proximity": "40%",
            "fundamental_distance": "35%",
            "risk_momentum_distance": "25%",
        },
    }
    
    # Cache for 30 min
    _smart_cache_set(cache_key, response, ttl=1800)
    print(f"  💾 Cached. Total elapsed: {elapsed}s")
    
    return response



# ═══════════════════════════════════════════════════════════════════
# r63.8: Momentum Leaders + Earnings Calendar + This-Week Alerts
# ═══════════════════════════════════════════════════════════════════

# Reuses _FIND_SIMILAR_US_UNIVERSE / _IN_UNIVERSE from r63.6 — same curated set
# This avoids universe-list duplication. If we want different momentum universe
# later, we can split — for now consistency wins.

def _r638_compute_momentum_score(profile, hist_closes, benchmark_closes=None):
    """r63.10: Improved momentum scoring with real relative strength + step-fn breakout.
    
    Components:
      35% recent return blend (1m=30, 3m=40, 6m=30 weighted; sustained > spike)
      30% acceleration (3m annualized > 1y? trend strengthening?)
      25% RELATIVE STRENGTH vs benchmark (SPY/^NSEI) — was absolute proxy
      10% breakout proximity (step fn: <5% from 52w hi = 100)
    
    Returns dict with score + components + signal label, or None if data sparse.
    
    NEW IN r63.10:
      - benchmark_closes parameter for true relative strength
      - step-function breakout (catches ATH stocks like SNDK properly)
      - EARLY_EMERGING signal when 60≤score<80 + accel_ratio > 2 (catches early rippers)
    """
    if not hist_closes or len(hist_closes) < 60:
        return None
    closes = list(hist_closes)
    last = closes[-1]
    if last <= 0:
        return None
    
    def _ret_from(closes_arr, days_back):
        if len(closes_arr) <= days_back: return None
        prior = closes_arr[-(days_back + 1)]
        if prior <= 0: return None
        return (closes_arr[-1] - prior) / prior * 100
    
    ret_1m = _ret_from(closes, 21)
    ret_3m = _ret_from(closes, 63)
    ret_6m = _ret_from(closes, 126)
    ret_1y = _ret_from(closes, 252)
    
    if ret_3m is None: return None
    
    # 1. Recent return blend (35% weight when no vol; 30% when vol available)
    recent_return = 0.0; return_count = 0
    if ret_1m is not None: recent_return += 0.3 * ret_1m; return_count += 0.3
    if ret_3m is not None: recent_return += 0.4 * ret_3m; return_count += 0.4
    if ret_6m is not None: recent_return += 0.3 * ret_6m; return_count += 0.3
    if return_count < 0.4: return None
    blended_return = recent_return / return_count
    return_score = max(0.0, min(100.0, (blended_return + 30) * 100 / 130))
    
    # 2. Acceleration (30% weight)
    accel_ratio = None  # NEW: expose for EARLY_EMERGING detection
    accel_score = 50.0
    if ret_3m is not None and ret_1y is not None and ret_1y != 0:
        ann_3m = ret_3m * 4
        if ret_1y > 0:
            accel_ratio = ann_3m / ret_1y
        if ann_3m > ret_1y:
            ratio = (ann_3m - ret_1y) / max(abs(ret_1y), 10)
            accel_score = min(100, 50 + ratio * 50)
        else:
            accel_score = max(0, 50 - abs(ret_1y - ann_3m) / max(abs(ret_1y), 10) * 25)
    elif ret_3m is not None and ret_3m > 0:
        accel_score = min(100, 50 + ret_3m / 2)
    
    # 3. RELATIVE STRENGTH vs benchmark (25% weight) — r63.10 fix
    rs_score = 50.0  # neutral default if benchmark unavailable
    if benchmark_closes and len(benchmark_closes) >= 126:
        bench_6m = _ret_from(benchmark_closes, 126)
        if ret_6m is not None and bench_6m is not None and bench_6m != 0:
            # RS = stock return relative to benchmark
            # If stock +60% and SPY +20%, RS = 60/20 = 3x = strong
            # If stock +20% and SPY +20%, RS = 1x = neutral
            # Map: 0.5x=0, 1x=50, 2x=80, 3x+=100
            if bench_6m > 0:
                rs_ratio = ret_6m / bench_6m
                rs_score = max(0.0, min(100.0, 50 * rs_ratio if rs_ratio < 2 else 80 + (rs_ratio - 2) * 10))
            else:
                # Benchmark down — any positive return is strong
                rs_score = 100 if ret_6m > 0 else max(0, 50 + ret_6m / 2)
    elif ret_6m is not None:
        # Fallback: absolute proxy if no benchmark
        rs_score = max(0.0, min(100.0, (ret_6m + 20) * 2))
    
    # 4. STEP-FUNCTION breakout proximity (10% weight) — r63.10 fix
    if len(closes) >= 252: hi_52w = max(closes[-252:])
    else: hi_52w = max(closes)
    bo_score = 50.0
    if hi_52w > 0:
        distance_pct = (hi_52w - last) / hi_52w * 100
        # Step function: tighter scoring for ATH-region stocks
        if distance_pct <= 2:    bo_score = 100  # at high
        elif distance_pct <= 5:  bo_score = 90
        elif distance_pct <= 10: bo_score = 75
        elif distance_pct <= 20: bo_score = 55
        elif distance_pct <= 30: bo_score = 35
        else:                    bo_score = max(0, 35 - distance_pct + 30)
    
    # Volume placeholder
    vol_score = 50.0
    
    # Weighted total — redistribute vol when neutral (preserves r63.8 fix)
    if vol_score == 50.0:
        total = 0.35 * return_score + 0.30 * accel_score + 0.25 * rs_score + 0.10 * bo_score
    else:
        total = 0.30 * return_score + 0.25 * accel_score + 0.20 * rs_score + 0.15 * vol_score + 0.10 * bo_score
    
    # Signal — added EARLY EMERGING for catching rippers in formation
    # r63.10: also trigger EARLY EMERGING when 1Y data is missing but 3M return is exceptional
    # (catches recent IPOs/spinoffs and rippers where flat 1Y prior makes accel_ratio undefined)
    is_early_emerging = (
        (accel_ratio is not None and accel_ratio >= 2) or
        (ret_1y is None and ret_3m is not None and ret_3m >= 30) or
        (ret_1y is not None and ret_1y < 5 and ret_3m is not None and ret_3m >= 25)
    )
    
    if total >= 80:
        signal = "🔥 EXTREME"
    elif total >= 65:
        signal = "🚀 STRONG"
    elif total >= 60 and is_early_emerging:
        # EARLY EMERGING: not yet STRONG but trend strongly accelerating = early rippers
        signal = "✨ EARLY EMERGING"
    elif total >= 50:
        signal = "⚡ BUILDING"
    else:
        signal = "📉 WEAK"
    
    return {
        "score": round(total, 1),
        "signal": signal,
        "ret_1m": round(ret_1m, 1) if ret_1m is not None else None,
        "ret_3m": round(ret_3m, 1) if ret_3m is not None else None,
        "ret_6m": round(ret_6m, 1) if ret_6m is not None else None,
        "ret_1y": round(ret_1y, 1) if ret_1y is not None else None,
        "accel_ratio": round(accel_ratio, 2) if accel_ratio is not None else None,
        "components": {
            "return": round(return_score, 1),
            "acceleration": round(accel_score, 1),
            "rel_strength": round(rs_score, 1),
            "breakout": round(bo_score, 1),
        },
    }


@app.get("/api/momentum-leaders")
async def momentum_leaders(region: str = "US", email: str = "", nocache: int = 0):
    """r63.8: Find top momentum stocks (SNDK/MU-style rippers).
    
    Scans curated universe, computes 5-component momentum score per ticker,
    filters out downtrending / illiquid / penny stocks, returns top 20 + bucketed.
    
    Cache: 30 min TTL (momentum doesn't change minute-to-minute)
    """
    import time, asyncio
    
    email = (email or "").strip().lower()
    _ok, email = check_premium_gate(email, "dream")
    if not _ok:
        return {"success": False, "error": "Momentum Leaders is a premium feature."}
    
    region = (region or "US").upper()
    if region not in ("US", "IN"):
        return {"success": False, "error": "region must be US or IN"}
    
    cache_key = f"momentum_leaders_{region}"
    if nocache != 1:
        cached = _smart_cache_get(cache_key)
        if cached:
            cached["_cached"] = True
            return cached
    
    t0 = time.time()
    print("\n" + "="*60)
    print(f"🔥 MOMENTUM LEADERS scan: region={region}")
    print("="*60)
    
    # r63.10: Fetch benchmark closes once for relative strength calculation
    benchmark_closes = None
    benchmark_symbol = "SPY" if region == "US" else "^NSEI"
    try:
        if region == "US":
            bench_data = _fh.get_price_history(benchmark_symbol, region="US", period_days=365)
            if bench_data and bench_data.get("closes"):
                benchmark_closes = bench_data["closes"]
                print(f"  📊 Benchmark loaded: {benchmark_symbol} {len(benchmark_closes)} closes")
        if not benchmark_closes:
            # Fallback to yfinance
            try:
                _yahoo_rate_wait()
                btk = yf.Ticker(benchmark_symbol)
                bhist = btk.history(period="1y", interval="1d")
                if bhist is not None and not bhist.empty:
                    benchmark_closes = list(bhist["Close"].dropna())
                    print(f"  📊 Benchmark via yfinance: {benchmark_symbol} {len(benchmark_closes)} closes")
            except Exception as _be:
                print(f"  ⚠ Benchmark fetch failed: {_be} — RS will fall back to absolute proxy")
    except Exception as _be:
        print(f"  ⚠ Benchmark fetch failed: {_be}")
    
    # Use same universe as find-similar (consistency)
    if region == "US":
        universe = list(dict.fromkeys(_FIND_SIMILAR_US_UNIVERSE))
    else:
        universe = list(dict.fromkeys(_FIND_SIMILAR_IN_UNIVERSE))
    
    BATCH_SIZE = int(os.getenv("MOMENTUM_BATCH_SIZE", "20"))
    leaders = []
    
    async def _fetch_one(ticker):
        try:
            # Get DD to extract price + has the data we need
            dd = await investor_due_diligence(email=email, symbol=ticker, region=region)
            if not dd.get("success"):
                return None
            company = dd.get("company") or {}
            price = _safe_float(company.get("price"))
            if price <= 0:
                return None
            # Hard filters: penny stocks
            if region == "US" and price < 5:
                return None
            if region == "IN" and price < 50:
                return None
            
            # Get price history for momentum calc
            # Reuse Finnhub for US, NSE-via-yf for IN
            hist_closes = None
            try:
                if region == "US":
                    fh_hist = _fh.get_price_history(ticker, region="US", period_days=365)
                    if fh_hist and fh_hist.get("closes"):
                        hist_closes = fh_hist["closes"]
            except Exception:
                pass
            
            # Fallback: try yfinance if Finnhub didn't deliver
            if not hist_closes:
                try:
                    yf_sym = ticker if region == "US" else f"{ticker}.NS"
                    _yahoo_rate_wait()
                    tk = yf.Ticker(yf_sym)
                    hist_df = tk.history(period="1y", interval="1d")
                    if hist_df is not None and not hist_df.empty:
                        hist_closes = list(hist_df["Close"].dropna())
                except Exception:
                    pass
            
            if not hist_closes or len(hist_closes) < 60:
                return None
            
            mom = _r638_compute_momentum_score({"price": price}, hist_closes, benchmark_closes=benchmark_closes)
            if not mom:
                return None
            
            # Skip stocks with weak momentum (filter)
            if mom["score"] < 40:
                return None
            
            return {
                "ticker":    ticker,
                "name":      company.get("name", ticker),
                "price":     price,
                "currency_symbol": dd.get("currency_symbol", "$"),
                "sector":    company.get("sector", ""),
                "score":     mom["score"],
                "signal":    mom["signal"],
                "ret_1m":    mom["ret_1m"],
                "ret_3m":    mom["ret_3m"],
                "ret_6m":    mom["ret_6m"],
                "ret_1y":    mom["ret_1y"],
            }
        except Exception as e:
            print(f"    ⚠️  {ticker} momentum failed: {type(e).__name__}: {str(e)[:80]}")
            return None
    
    for i in range(0, len(universe), BATCH_SIZE):
        batch = universe[i:i+BATCH_SIZE]
        results = await asyncio.gather(*[_fetch_one(t) for t in batch], return_exceptions=False)
        for r in results:
            if r is not None:
                leaders.append(r)
        elapsed = time.time() - t0
        print(f"  📈 Batch {i//BATCH_SIZE + 1} done — {len(leaders)} momentum leaders so far ({elapsed:.0f}s)")
    
    # Sort by score desc, take top 20
    leaders.sort(key=lambda x: x["score"], reverse=True)
    top_leaders = leaders[:20]
    
    # Bucket by signal tier — r63.10: added EARLY EMERGING for catching early rippers
    buckets = {
        "extreme":         {"label": "🔥 EXTREME (score 80+)",                  "results": []},
        "strong":          {"label": "🚀 STRONG (65-80)",                       "results": []},
        "early_emerging":  {"label": "✨ EARLY EMERGING (60+ with 2x acceleration)", "results": []},
        "building":        {"label": "⚡ BUILDING (50-65)",                     "results": []},
    }
    for L in top_leaders:
        s = L["score"]
        if s >= 80:
            buckets["extreme"]["results"].append(L)
        elif s >= 65:
            buckets["strong"]["results"].append(L)
        elif L.get("signal") == "✨ EARLY EMERGING":
            buckets["early_emerging"]["results"].append(L)
        else:
            buckets["building"]["results"].append(L)
    
    for k in buckets:
        buckets[k]["count"] = len(buckets[k]["results"])
    
    elapsed = round(time.time() - t0, 1)
    response = {
        "success":   True,
        "region":    region,
        "buckets":   buckets,
        "all_leaders": top_leaders,
        "scanned":   len(universe),
        "qualified": len(leaders),
        "elapsed_sec": elapsed,
        "_cached":   False,
        "weighting": {
            "recent_return": "30%",
            "acceleration":  "25%",
            "relative_strength": "20%",
            "volume_surge":  "15%",
            "breakout_proximity": "10%",
        },
    }
    
    _smart_cache_set(cache_key, response, ttl=1800)
    print(f"  💾 Cached. {len(leaders)} qualified, top 20 returned. {elapsed}s")
    return response


@app.get("/api/earnings-calendar")
async def earnings_calendar(symbol: str = "", region: str = "US", email: str = "",
                             nocache: int = 0):
    """r63.8: Per-ticker quarterly earnings calendar (past + upcoming).
    
    Returns historical earnings (last 4 Q via Finnhub /stock/earnings) +
    forward earnings (next 90 days via Finnhub /calendar/earnings if available).
    
    For India: only past results from NSE-via-yfinance fallback. No forward dates.
    """
    import time
    
    email = (email or "").strip().lower()
    _ok, email = check_premium_gate(email, "dream")
    if not _ok:
        return {"success": False, "error": "Earnings Calendar is a premium feature."}
    
    symbol = (symbol or "").strip().upper()
    region = (region or "US").upper()
    if not symbol:
        return {"success": False, "error": "symbol required"}
    
    cache_key = f"earnings_cal_{symbol}_{region}"
    if nocache != 1:
        cached = _smart_cache_get(cache_key)
        if cached:
            cached["_cached"] = True
            return cached
    
    past_quarters = []
    upcoming = []
    
    # 1. Past quarters via Finnhub history adapter (already exists)
    try:
        eh = _fh.get_earnings_history(symbol, region=region) if region == "US" else None
        if eh and eh.get("data"):
            for q in eh["data"]:
                d = q.get("date")
                # Convert datetime → string for JSON
                if hasattr(d, "strftime"):
                    d = d.strftime("%Y-%m-%d")
                past_quarters.append({
                    "date": d,
                    "eps_estimate": q.get("eps_estimate"),
                    "eps_actual":   q.get("eps_actual"),
                    "surprise":     q.get("surprise"),
                    "surprise_pct": q.get("surprise_pct"),
                    "beat":         q.get("beat"),
                })
    except Exception as e:
        print(f"[earnings-cal] past quarters fetch failed for {symbol}: {e}")
    
    # 2. Upcoming via Finnhub calendar (US only on free tier)
    if region == "US":
        try:
            cal = _fh.get_earnings_calendar(symbol=symbol, region="US")
            if cal and cal.get("data"):
                for ev in cal["data"]:
                    upcoming.append({
                        "date":            ev.get("date"),
                        "eps_estimate":    ev.get("epsEstimate"),
                        "rev_estimate":    ev.get("revenueEstimate"),
                        "hour":            ev.get("hour"),  # bmo/amc/dmh
                        "quarter":         ev.get("quarter"),
                        "year":            ev.get("year"),
                    })
        except Exception as e:
            print(f"[earnings-cal] upcoming fetch failed for {symbol}: {e}")
    
    response = {
        "success":      True,
        "symbol":       symbol,
        "region":       region,
        "past_quarters": past_quarters,
        "upcoming":     upcoming,
        "data_quality": (
            "FULL" if past_quarters and upcoming else
            "PARTIAL" if past_quarters or upcoming else
            "NONE"
        ),
        "data_note":    (
            "Finnhub free tier: forward dates available for US, sparse for India. Past 4-8 quarters typically present."
            if region == "US" else
            "India free-tier coverage: past quarters via NSE/yfinance, NO forward dates. Upgrade to paid tier for full calendar."
        ),
        "_cached":      False,
    }
    
    _smart_cache_set(cache_key, response, ttl=3600)  # 1 hour cache
    return response


@app.get("/api/earnings-this-week")
async def earnings_this_week(region: str = "US", email: str = "", nocache: int = 0):
    """r63.16: Extended to 3-week window. Returns earnings split into:
      - declared: past 7 days + already reported in this week
      - this_week_upcoming: rest of this week (today through Sunday)
      - next_week_upcoming: next Monday through next Sunday
    
    Each event in declared has eps_actual + beat info. Upcoming events have estimate only.
    Cache: 6 hours.
    """
    import time
    from datetime import datetime as _dt3, timedelta as _td3
    
    email = (email or "").strip().lower()
    _ok, email = check_premium_gate(email, "dream")
    if not _ok:
        return {"success": False, "error": "Earnings calendar is a premium feature."}
    
    region = (region or "US").upper()
    cache_key = f"earnings_3wk_v17_{region}"  # r63.17: bumped to invalidate cache with old None-as-0 data  # r63.16: new cache key (different shape than v15)
    
    if nocache != 1:
        cached = _smart_cache_get(cache_key)
        if cached:
            cached["_cached"] = True
            return cached
    
    if region != "US":
        response = {
            "success": True,
            "region": region,
            "declared": [],
            "this_week_upcoming": [],
            "next_week_upcoming": [],
            "data_note": "India: Finnhub free tier doesn't provide forward earnings calendar. Upgrade to paid tier for India coverage.",
            "_cached": False,
        }
        _smart_cache_set(cache_key, response, ttl=21600)
        return response
    
    # 3-week window: T-7 through T+14
    today = _dt3.utcnow().date()
    week_start = today - _td3(days=today.weekday())  # Monday of this week
    next_week_start = week_start + _td3(days=7)
    next_week_end = next_week_start + _td3(days=6)  # Sunday of next week
    
    from_date = (today - _td3(days=7)).strftime("%Y-%m-%d")
    to_date = next_week_end.strftime("%Y-%m-%d")
    
    try:
        cal = _fh.get_earnings_calendar(from_date=from_date, to_date=to_date, region="US")
    except Exception as e:
        print(f"[earnings-3wk] calendar fetch failed: {e}")
        cal = None
    
    if not cal or not cal.get("data"):
        response = {
            "success": True,
            "region": region,
            "declared": [],
            "this_week_upcoming": [],
            "next_week_upcoming": [],
            "data_note": "No earnings data available (Finnhub returned empty).",
            "_cached": False,
        }
        _smart_cache_set(cache_key, response, ttl=21600)
        return response
    
    tracked_set = set(_FIND_SIMILAR_US_UNIVERSE) if _FIND_SIMILAR_US_UNIVERSE else set()
    
    # Bucketize all events
    declared = []
    this_week_upcoming = []
    next_week_upcoming = []
    
    for ev in cal["data"]:
        date_str = ev.get("date")
        if not date_str:
            continue
        try:
            ev_date = _dt3.strptime(date_str, "%Y-%m-%d").date()
        except Exception:
            continue
        
        sym = ev.get("symbol", "")
        in_universe = sym in tracked_set
        
        eps_actual = ev.get("epsActual")
        eps_estimate = ev.get("epsEstimate")
        
        # Outcome (for declared events) — r63.17: handle None correctly
        # eps_actual=None → "pending" (event happened but data not in feed yet)
        # eps_actual=0.0 → could be legit zero (reported zero EPS); show as "reported"
        # eps_actual>0 + eps_estimate>0 → compare for beat/miss
        outcome = None
        surprise_pct = None
        if eps_actual is not None:
            if eps_estimate is not None and eps_estimate != 0:
                surprise_pct = (eps_actual - eps_estimate) / abs(eps_estimate) * 100
                outcome = "beat" if eps_actual >= eps_estimate else "miss"
            else:
                outcome = "reported"
        
        bucket_event = {
            "symbol":         sym,
            "in_universe":    in_universe,
            "date":           date_str,
            "hour":           (ev.get("hour") or "").lower(),
            "eps_estimate":   eps_estimate,
            "eps_actual":     eps_actual,
            "rev_estimate":   ev.get("revenueEstimate"),
            "rev_actual":     ev.get("revenueActual"),
            "quarter":        ev.get("quarter"),
            "year":           ev.get("year"),
            "outcome":        outcome,           # "beat", "miss", "reported", or None
            "surprise_pct":   round(surprise_pct, 1) if surprise_pct is not None else None,
        }
        
        # Bucket assignment — r63.17: simplified, more inclusive
        # Past-or-today dates with eps_actual present → declared with full data
        # Past-or-today dates without eps_actual → declared anyway (event happened)
        # Future this-week → upcoming this week
        # Future next-week → upcoming next week
        if ev_date <= today:
            declared.append(bucket_event)
        elif ev_date <= week_start + _td3(days=6):
            # This week (Mon-Sun) — strictly future days within this week
            this_week_upcoming.append(bucket_event)
        elif ev_date <= next_week_end:
            # Next week
            next_week_upcoming.append(bucket_event)
        # else: outside our window (T+15 onwards), skip
    
    # Sort each bucket: tracked first, then by date
    def sort_key(e):
        return (not e["in_universe"], e["date"], e["symbol"])
    
    declared.sort(key=sort_key, reverse=False)
    declared.sort(key=lambda e: e["date"], reverse=True)  # most recent declared first
    this_week_upcoming.sort(key=sort_key)
    next_week_upcoming.sort(key=sort_key)
    
    # Limit to keep response sane
    declared = declared[:60]
    this_week_upcoming = this_week_upcoming[:80]
    next_week_upcoming = next_week_upcoming[:80]
    
    tracked_count_total = sum(1 for e in (declared + this_week_upcoming + next_week_upcoming) if e["in_universe"])
    
    response = {
        "success":              True,
        "region":               region,
        "declared":             declared,
        "this_week_upcoming":   this_week_upcoming,
        "next_week_upcoming":   next_week_upcoming,
        "from_date":            from_date,
        "to_date":              to_date,
        "this_week_range":      [week_start.strftime("%Y-%m-%d"),
                                 (week_start + _td3(days=6)).strftime("%Y-%m-%d")],
        "next_week_range":      [next_week_start.strftime("%Y-%m-%d"),
                                 next_week_end.strftime("%Y-%m-%d")],
        "totals": {
            "declared":          len(declared),
            "this_week_upcoming": len(this_week_upcoming),
            "next_week_upcoming": len(next_week_upcoming),
            "tracked_total":      tracked_count_total,
        },
        "data_note":            f"Window: {from_date} to {to_date}. {tracked_count_total} events from your tracked universe.",
        "_cached":              False,
    }
    
    _smart_cache_set(cache_key, response, ttl=21600)  # 6h cache
    return response
    
    # Filter to tickers in our universe (or popular ones), sort by date
    tracked_set = set(_FIND_SIMILAR_US_UNIVERSE)
    
    events = []
    for ev in cal["data"]:
        sym = ev.get("symbol", "")
        in_universe = sym in tracked_set
        events.append({
            "symbol":          sym,
            "in_universe":     in_universe,  # is this ticker in our tracked set?
            "date":            ev.get("date"),
            "hour":            ev.get("hour"),  # bmo/amc/dmh
            "eps_estimate":    ev.get("epsEstimate"),
            "rev_estimate":    ev.get("revenueEstimate"),
            "quarter":         ev.get("quarter"),
            "year":            ev.get("year"),
        })
    
    # Sort: in_universe first (alphabetical), then by date
    events.sort(key=lambda e: (not e["in_universe"], e.get("date") or "9999-99-99", e["symbol"]))
    
    # Cap to 100 to keep response size sane
    events = events[:100]
    
    in_universe_count = sum(1 for e in events if e["in_universe"])
    
    response = {
        "success":          True,
        "region":           region,
        "events":           events,
        "from_date":        today.strftime("%Y-%m-%d"),
        "to_date":          seven_out.strftime("%Y-%m-%d"),
        "total_events":     len(events),
        "in_universe_count": in_universe_count,
        "data_note":        f"Showing {len(events)} earnings events Mon {today.strftime('%b %d')} - Sun {seven_out.strftime('%b %d')}. {in_universe_count} are in your tracked universe.",
        "_cached":          False,
    }
    
    _smart_cache_set(cache_key, response, ttl=21600)  # 6h cache
    return response






# ═══════════════════════════════════════════════════════════════════
# r63.14: Diagnostic — test ALL historical price data sources from Render
# ═══════════════════════════════════════════════════════════════════
# Returns honest per-source status. No speculation. Lets us learn what
# actually works from Render's network instead of guessing.

@app.get("/api/diag-data-sources")
async def diag_data_sources(symbol: str = "MU", email: str = ""):
    """r63.14: Test multiple historical price sources, return per-source status.
    
    Tests for ticker `symbol` (default MU):
      1. Finnhub /stock/candle  — what r63.8 assumed worked (probably 403)
      2. yfinance .history()    — what we use as fallback (allegedly blocked)
      3. Yahoo chart API direct — different endpoint than yfinance lib
      4. Stooq CSV              — last-resort free source
      5. Google Finance scrape  — exists in data_sources.py
    
    Returns dict per source: {success, data_points, error, sample_close, source_url}
    """
    import time, traceback
    
    # Light auth — use any valid premium email
    email = (email or "").strip().lower()
    _ok, email = check_premium_gate(email, "dream")
    if not _ok:
        return {"success": False, "error": "Premium gate required for diagnostic."}
    
    symbol = (symbol or "MU").strip().upper()
    results = {}
    t0_total = time.time()
    
    # ─── Test 1: Finnhub /stock/candle ───────────────────────────────
    t0 = time.time()
    try:
        result = _fh.get_price_history(symbol, region="US", period_days=365)
        results["finnhub_candle"] = {
            "success": bool(result and result.get("closes")),
            "data_points": len(result.get("closes", [])) if result else 0,
            "sample_close": result["closes"][-1] if result and result.get("closes") else None,
            "elapsed_ms": int((time.time() - t0) * 1000),
            "error": None if (result and result.get("closes")) else "Returned None or empty",
        }
    except Exception as e:
        results["finnhub_candle"] = {
            "success": False, "data_points": 0, "elapsed_ms": int((time.time() - t0) * 1000),
            "error": f"{type(e).__name__}: {str(e)[:200]}",
        }
    
    # ─── Test 2: yfinance .history() ─────────────────────────────────
    t0 = time.time()
    try:
        _yahoo_rate_wait()
        tk = yf.Ticker(symbol)
        hist = tk.history(period="1y", interval="1d")
        if hist is not None and not hist.empty:
            closes = list(hist["Close"].dropna())
            results["yfinance_history"] = {
                "success": True,
                "data_points": len(closes),
                "sample_close": float(closes[-1]) if closes else None,
                "elapsed_ms": int((time.time() - t0) * 1000),
                "error": None,
            }
        else:
            results["yfinance_history"] = {
                "success": False, "data_points": 0,
                "elapsed_ms": int((time.time() - t0) * 1000),
                "error": "yfinance returned empty/None",
            }
    except Exception as e:
        results["yfinance_history"] = {
            "success": False, "data_points": 0,
            "elapsed_ms": int((time.time() - t0) * 1000),
            "error": f"{type(e).__name__}: {str(e)[:200]}",
        }
    
    # ─── Test 3: Yahoo chart API direct (different from yfinance) ────
    t0 = time.time()
    try:
        import urllib.request, json as _json
        url = f"https://query1.finance.yahoo.com/v8/finance/chart/{symbol}?interval=1d&range=1y"
        req = urllib.request.Request(url, headers={
            "User-Agent": "Mozilla/5.0 (compatible; Celesys/1.0)",
            "Accept": "application/json",
        })
        with urllib.request.urlopen(req, timeout=10) as resp:
            data = _json.loads(resp.read())
        chart = data.get("chart", {}).get("result", [{}])[0]
        closes = chart.get("indicators", {}).get("quote", [{}])[0].get("close", [])
        closes = [c for c in closes if c is not None]
        results["yahoo_chart_direct"] = {
            "success": bool(closes),
            "data_points": len(closes),
            "sample_close": closes[-1] if closes else None,
            "elapsed_ms": int((time.time() - t0) * 1000),
            "error": None if closes else "Empty closes array",
            "source_url": url,
        }
    except Exception as e:
        results["yahoo_chart_direct"] = {
            "success": False, "data_points": 0,
            "elapsed_ms": int((time.time() - t0) * 1000),
            "error": f"{type(e).__name__}: {str(e)[:200]}",
        }
    
    # ─── Test 4: Stooq CSV ───────────────────────────────────────────
    t0 = time.time()
    try:
        import urllib.request
        # Stooq needs lowercase symbol with .us suffix
        stooq_sym = symbol.lower() + ".us"
        url = f"https://stooq.com/q/d/l/?s={stooq_sym}&i=d"
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=10) as resp:
            csv = resp.read().decode("utf-8", errors="replace")
        # CSV format: Date,Open,High,Low,Close,Volume
        lines = csv.strip().split("\n")
        if len(lines) > 2 and lines[0].startswith("Date"):
            closes = []
            for ln in lines[1:]:
                parts = ln.split(",")
                if len(parts) >= 5:
                    try: closes.append(float(parts[4]))
                    except: pass
            results["stooq_csv"] = {
                "success": len(closes) > 50,
                "data_points": len(closes),
                "sample_close": closes[-1] if closes else None,
                "elapsed_ms": int((time.time() - t0) * 1000),
                "error": None if closes else "No data parsed",
                "source_url": url,
            }
        else:
            results["stooq_csv"] = {
                "success": False, "data_points": 0,
                "elapsed_ms": int((time.time() - t0) * 1000),
                "error": f"Bad CSV format. First 200 chars: {csv[:200]}",
            }
    except Exception as e:
        results["stooq_csv"] = {
            "success": False, "data_points": 0,
            "elapsed_ms": int((time.time() - t0) * 1000),
            "error": f"{type(e).__name__}: {str(e)[:200]}",
        }
    
    # ─── Test 5: Google Finance via existing scraper ─────────────────
    t0 = time.time()
    try:
        # Existing google_finance scraper in data_sources lives there
        # Just check if the function exists and returns sane data
        gf_result = None
        if hasattr(_ds, "google_finance_quote"):
            gf_result = _ds.google_finance_quote(symbol, region="US")
        elif hasattr(_ds, "_google_finance_scrape"):
            gf_result = _ds._google_finance_scrape(symbol)
        # GF only gives current price, not history — note this honestly
        results["google_finance"] = {
            "success": bool(gf_result and gf_result.get("price")),
            "data_points": 1 if (gf_result and gf_result.get("price")) else 0,
            "sample_close": gf_result.get("price") if gf_result else None,
            "elapsed_ms": int((time.time() - t0) * 1000),
            "error": None if gf_result else "GF scraper returned None",
            "note": "Google Finance only provides current price, not historical.",
        }
    except Exception as e:
        results["google_finance"] = {
            "success": False, "data_points": 0,
            "elapsed_ms": int((time.time() - t0) * 1000),
            "error": f"{type(e).__name__}: {str(e)[:200]}",
        }
    
    # ─── Summary ─────────────────────────────────────────────────────
    working = [name for name, r in results.items() if r.get("success")]
    
    return {
        "success": True,
        "symbol": symbol,
        "tested_sources": list(results.keys()),
        "working_sources": working,
        "results": results,
        "total_elapsed_sec": round(time.time() - t0_total, 1),
        "render_node_info": {
            "python_version": sys.version.split()[0],
            "yfinance_available": "yfinance" in sys.modules,
        },
        "interpretation": (
            f"{len(working)}/5 sources work. " +
            ("USE THE FIRST WORKING ONE for momentum scanner price history."
             if working else
             "ALL FIVE SOURCES BLOCKED — no historical price data is reachable from Render. "
             "Only paid Finnhub Personal or paid IEX/Polygon/etc would solve this.")
        ),
    }



@app.get("/api/diag-earnings-raw")
async def diag_earnings_raw(email: str = "", days_back: int = 7, days_forward: int = 14,
                             symbol: str = ""):
    """r63.17: Inspect what Finnhub actually returns. No filtering, no bucketing.
    
    Returns up to first 30 events from /calendar/earnings call.
    Lets us verify: does Finnhub actually return META/MSFT past dates?
    Does epsActual come through as null or 0 or actual number?
    """
    from datetime import datetime as _dt4, timedelta as _td4
    
    email = (email or "").strip().lower()
    _ok, email = check_premium_gate(email, "dream")
    if not _ok:
        return {"success": False, "error": "Premium gate required."}
    
    today = _dt4.utcnow().date()
    from_date = (today - _td4(days=days_back)).strftime("%Y-%m-%d")
    to_date = (today + _td4(days=days_forward)).strftime("%Y-%m-%d")
    
    try:
        cal = _fh.get_earnings_calendar(
            from_date=from_date, to_date=to_date, region="US",
            symbol=symbol if symbol else None
        )
    except Exception as e:
        return {"success": False, "error": str(e), "from_date": from_date, "to_date": to_date}
    
    if not cal:
        return {"success": True, "raw_response": None, "note": "Finnhub returned None",
                "from_date": from_date, "to_date": to_date}
    
    events = cal.get("data", [])
    
    # Filter to a few interesting test tickers if present
    test_tickers = {"META", "MSFT", "GOOG", "GOOGL", "AMZN", "AAPL", "NVDA", "TSLA", "AMD"}
    interesting = [e for e in events if e.get("symbol") in test_tickers]
    
    return {
        "success":         True,
        "from_date":       from_date,
        "to_date":         to_date,
        "today":           today.strftime("%Y-%m-%d"),
        "total_events":    len(events),
        "interesting":     interesting[:20],   # mega-cap names if present
        "first_30":        events[:30],         # first 30 chronologically
        "samples_with_actual":     [e for e in events if e.get("epsActual") is not None][:10],
        "samples_without_actual":  [e for e in events if e.get("epsActual") is None][:10],
        "summary": {
            "events_with_epsActual_value":     sum(1 for e in events if e.get("epsActual") is not None),
            "events_without_epsActual":        sum(1 for e in events if e.get("epsActual") is None),
            "events_dated_before_today":       sum(1 for e in events if e.get("date", "") < today.strftime("%Y-%m-%d")),
            "events_dated_today_or_after":     sum(1 for e in events if e.get("date", "") >= today.strftime("%Y-%m-%d")),
        },
    }



