# r63.18: Competitor Benchmark — sector peers side-by-side
# ═══════════════════════════════════════════════════════════════════

@app.get("/api/competitor-benchmark")
async def competitor_benchmark(symbol: str = "", region: str = "US", email: str = "",
                               max_peers: int = 5):
    """r63.18: Pull 4-5 sector peers from _momentum_universe_us, compare side-by-side.
    
    Returns table-shaped data: target ticker + peers with P/E, growth, margins, score.
    """
    import asyncio
    
    email = (email or "").strip().lower()
    _ok, email = check_premium_gate(email, "dream")
    if not _ok:
        return {"success": False, "error": "Competitor benchmark requires premium tier."}
    
    symbol = (symbol or "").strip().upper()
    if not symbol:
        return {"success": False, "error": "symbol required"}
    
    region = (region or "US").upper()
    
    try:
        target_dd = await investor_due_diligence(email=email, symbol=symbol, region=region)
    except Exception as e:
        return {"success": False, "error": f"Target DD failed: {str(e)[:200]}"}
    
    if not target_dd.get("success"):
        return {"success": False, "error": "Could not analyze target ticker."}
    
    target_company = target_dd.get("company") or {}
    target_thesis  = target_dd.get("thesis") or {}    # r63.22
    target_finance = target_dd.get("finance") or {}   # r63.22
    target_bottom  = target_dd.get("bottom_line") or {}  # r63.22
    target_sector = (target_company.get("sector") or "").strip().lower()
    
    if not target_sector:
        return {"success": False, "error": "Target ticker has no sector classification."}
    
    # Find peers in universe with same sector
    universe = _FIND_SIMILAR_US_UNIVERSE if region == "US" else (_FIND_SIMILAR_IN_UNIVERSE or [])
    if not universe:
        return {"success": False, "error": "No tracked universe available."}
    
    peer_candidates = [t for t in universe if t.upper() != symbol]
    
    # Quick fetch peers — limit concurrent
    BATCH_LIMIT = 30  # check up to 30 candidates to find sector matches
    candidates_to_check = peer_candidates[:BATCH_LIMIT]
    
    async def fetch_peer(ticker):
        try:
            peer_dd = await investor_due_diligence(email=email, symbol=ticker, region=region)
            if not peer_dd.get("success"):
                return None
            peer_co = peer_dd.get("company") or {}
            peer_sector = (peer_co.get("sector") or "").strip().lower()
            if peer_sector != target_sector:
                return None
            # r63.22: Read from correct paths in DD response
            peer_thesis  = peer_dd.get("thesis") or {}
            peer_finance = peer_dd.get("finance") or {}
            peer_bottom  = peer_dd.get("bottom_line") or {}
            return {
                "ticker":        ticker,
                "name":          peer_co.get("name", ticker),
                "price":         peer_thesis.get("spot_price"),
                "market_cap":    peer_thesis.get("market_cap"),
                "forward_pe":    peer_thesis.get("forward_pe"),
                "rev_growth":    peer_finance.get("revenue_growth_yoy_pct"),
                "op_margin":     peer_finance.get("operating_margin_pct"),
                "score":         peer_thesis.get("investability_score") or peer_bottom.get("composite_score"),
            }
        except Exception:
            return None
    
    results = await asyncio.gather(*[fetch_peer(t) for t in candidates_to_check],
                                   return_exceptions=False)
    peers = [r for r in results if r is not None][:max_peers]
    
    if not peers:
        return {
            "success": True,
            "symbol": symbol,
            "target_sector": target_company.get("sector"),
            "target": {
                "ticker":     symbol,
                "name":       target_company.get("name", symbol),
                "price":      target_company.get("price"),
                "market_cap": target_company.get("market_cap"),
                "forward_pe": target_company.get("forward_pe"),
                "rev_growth": target_company.get("revenue_growth"),
                "op_margin":  target_company.get("operating_margin"),
                "score":      target_dd.get("composite_score") or target_dd.get("institutional_score"),
            },
            "peers": [],
            "data_note": f"No sector peers found for '{target_company.get('sector')}' in tracked universe.",
        }
    
    return {
        "success": True,
        "symbol": symbol,
        "target_sector": target_company.get("sector"),
        "target": {
            "ticker":     symbol,
            "name":       target_company.get("name", symbol),
            "price":      target_thesis.get("spot_price"),
            "market_cap": target_thesis.get("market_cap"),
            "forward_pe": target_thesis.get("forward_pe"),
            "rev_growth": target_finance.get("revenue_growth_yoy_pct"),
            "op_margin":  target_finance.get("operating_margin_pct"),
            "score":      target_thesis.get("investability_score") or target_bottom.get("composite_score"),
        },
        "peers": peers,
        "peer_count": len(peers),
    }



# ═══════════════════════════════════════════════════════════════════
# r63.25: Forward Value — 5Y intrinsic value trajectory + expected return
# ═══════════════════════════════════════════════════════════════════

@app.get("/api/forward-value")
async def forward_value(symbol: str = "", region: str = "US", email: str = ""):
    """r63.25: Computes 5Y intrinsic value path, probability-weighted return,
    multiple-expansion thesis, total return decomposition."""
    email = (email or "").strip().lower()
    _ok, email = check_premium_gate(email, "dream")
    if not _ok:
        return {"success": False, "error": "Premium tier required."}
    
    symbol = (symbol or "").strip().upper()
    if not symbol:
        return {"success": False, "error": "symbol required"}
    
    try:
        dd = await investor_due_diligence(email=email, symbol=symbol, region=region)
    except Exception as e:
        return {"success": False, "error": f"DD failed: {str(e)[:200]}"}
    
    if not dd.get("success"):
        return {"success": False, "error": "DD generation failed."}
    
    # Read from confirmed canonical paths
    thesis    = dd.get("thesis") or {}
    finance   = dd.get("finance") or {}
    valuation = dd.get("valuation_detail") or {}
    company   = dd.get("company") or {}
    
    spot = _safe_float(thesis.get("spot_price"))
    if spot <= 0:
        return {"success": False, "error": "Insufficient data: no spot price."}
    
    dcf_fair = _safe_float(valuation.get("fair_value")) or _safe_float(thesis.get("dcf_fair_value"))
    if dcf_fair <= 0:
        return {"success": False, "error": "Insufficient data: DCF fair value not available."}
    
    fwd_pe = _safe_float(thesis.get("forward_pe"))
    rev_growth_pct = _safe_float(finance.get("revenue_growth_yoy_pct"))
    rev_growth = (rev_growth_pct / 100.0) if rev_growth_pct else 0.05
    rev_growth = max(-0.10, min(0.40, rev_growth))  # bound
    
    # Dividend yield from yfinance (already computed in DD if available)
    div_yield_pct = _safe_float(finance.get("dividend_yield_pct"))
    if div_yield_pct == 0:  # finance dict might not have it; check company
        # Fallback: check yfinance info — but we've already done that DD-side
        # Just default to 0 if not present
        div_yield_pct = 0
    div_yield = div_yield_pct / 100.0
    
    # ────── 5-Year Intrinsic Value Trajectory ──────
    # Bull: DCF × (1 + rev_growth × 1.5) at year 5
    # Base: DCF (current fair value)
    # Bear: DCF × 0.70 at year 5
    bull_5y = dcf_fair * (1 + rev_growth * 1.5)
    base_5y = dcf_fair
    bear_5y = dcf_fair * 0.70
    
    # Annual interpolation: spot → target via geometric
    def trajectory(target):
        if spot <= 0 or target <= 0: return [spot, spot, spot, spot, spot, spot]
        cagr = (target / spot) ** (1/5) - 1
        return [round(spot * (1 + cagr) ** y, 2) for y in range(6)]  # year 0 to 5
    
    bull_path = trajectory(bull_5y)
    base_path = trajectory(base_5y)
    bear_path = trajectory(bear_5y)
    
    # ────── Probability-weighted Expected Return ──────
    # Default weights: Bull 25%, Base 50%, Bear 25%
    p_bull, p_base, p_bear = 0.25, 0.50, 0.25
    
    def weighted_return(bull_t, base_t, bear_t):
        if spot <= 0: return None
        bull_r = (bull_t - spot) / spot
        base_r = (base_t - spot) / spot
        bear_r = (bear_t - spot) / spot
        return p_bull * bull_r + p_base * base_r + p_bear * bear_r
    
    er_1y = weighted_return(bull_path[1], base_path[1], bear_path[1])
    er_3y = weighted_return(bull_path[3], base_path[3], bear_path[3])
    er_5y = weighted_return(bull_5y, base_5y, bear_5y)
    
    cagr_3y = ((1 + er_3y) ** (1/3) - 1) if er_3y is not None else None
    cagr_5y = ((1 + er_5y) ** (1/5) - 1) if er_5y is not None else None
    
    # ────── Multiple-Expansion Thesis ──────
    # Sector median P/E — from sector_context if available, else use static estimate
    sector_data = dd.get("sector_context") or {}
    sector_pe = _safe_float(sector_data.get("sector_pe_median"))
    if sector_pe <= 0:
        # Default sector medians by broad bucket — honest fallback
        sector_name = (company.get("sector") or "").lower()
        sector_default_pe = {
            "technology": 25, "healthcare": 22, "financials": 12,
            "consumer cyclical": 18, "consumer defensive": 20,
            "energy": 12, "utilities": 18, "real estate": 22,
            "communication services": 18, "industrials": 19,
            "basic materials": 15,
        }
        for k, v in sector_default_pe.items():
            if k in sector_name:
                sector_pe = v; break
        if sector_pe <= 0: sector_pe = 18  # conservative S&P median
    
    multiple_expansion = None
    if fwd_pe > 0 and sector_pe > 0:
        # If at sector median, what does spot become?
        upside_to_sector = (sector_pe - fwd_pe) / fwd_pe * 100 if fwd_pe > 0 else 0
        multiple_expansion = {
            "current_pe": round(fwd_pe, 1),
            "sector_median_pe": round(sector_pe, 1),
            "upside_to_sector_pct": round(upside_to_sector, 1),
            "interpretation": (
                f"Trading {abs(upside_to_sector):.0f}% {'below' if upside_to_sector > 0 else 'above'} sector median P/E "
                f"({fwd_pe:.1f} vs {sector_pe:.1f}). " +
                ("Re-rating to sector median implies meaningful upside." if upside_to_sector > 10 else
                 "Compressing to sector median implies downside risk." if upside_to_sector < -10 else
                 "In line with sector — multiple-expansion thesis weak.")
            ),
        }
    
    # ────── Total Return Decomposition (5Y) ──────
    capital_appreciation_5y = (base_5y - spot) / spot if spot > 0 else 0
    dividends_5y = div_yield * 5  # simple cumulative
    # Buyback yield estimate — conservative 1% annually if profitable
    profit_margin_pct = _safe_float(finance.get("profit_margin_pct"))
    buyback_yield_5y = 0.01 * 5 if profit_margin_pct > 5 else 0
    total_5y = capital_appreciation_5y + dividends_5y + buyback_yield_5y
    
    return {
        "success":   True,
        "symbol":    symbol,
        "spot":      round(spot, 2),
        "trajectory": {
            "years":  list(range(6)),  # 0=Now, 5=Year 5
            "bull":   bull_path,
            "base":   base_path,
            "bear":   bear_path,
            "bull_target": round(bull_5y, 2),
            "base_target": round(base_5y, 2),
            "bear_target": round(bear_5y, 2),
        },
        "expected_return": {
            "p_bull":    p_bull,
            "p_base":    p_base,
            "p_bear":    p_bear,
            "1y_pct":    round(er_1y * 100, 1) if er_1y is not None else None,
            "3y_pct":    round(er_3y * 100, 1) if er_3y is not None else None,
            "5y_pct":    round(er_5y * 100, 1) if er_5y is not None else None,
            "3y_cagr":   round(cagr_3y * 100, 1) if cagr_3y is not None else None,
            "5y_cagr":   round(cagr_5y * 100, 1) if cagr_5y is not None else None,
        },
        "multiple_expansion": multiple_expansion,
        "total_return_5y": {
            "capital_pct":  round(capital_appreciation_5y * 100, 1),
            "dividends_pct": round(dividends_5y * 100, 1),
            "buybacks_pct":  round(buyback_yield_5y * 100, 1),
            "total_pct":     round(total_5y * 100, 1),
        },
    }


# ═══════════════════════════════════════════════════════════════════
# r63.25: Exit Strategy — entry/trim levels, stops, position sizing
# ═══════════════════════════════════════════════════════════════════

@app.get("/api/exit-strategy")
async def exit_strategy(symbol: str = "", region: str = "US", email: str = "",
                        entry_price: float = 0):
    """r63.25: Exit strategy with price ladder, stops, position sizing."""
    email = (email or "").strip().lower()
    _ok, email = check_premium_gate(email, "dream")
    if not _ok:
        return {"success": False, "error": "Premium tier required."}
    
    symbol = (symbol or "").strip().upper()
    if not symbol:
        return {"success": False, "error": "symbol required"}
    
    try:
        dd = await investor_due_diligence(email=email, symbol=symbol, region=region)
    except Exception as e:
        return {"success": False, "error": f"DD failed: {str(e)[:200]}"}
    
    if not dd.get("success"):
        return {"success": False, "error": "DD generation failed."}
    
    thesis    = dd.get("thesis") or {}
    finance   = dd.get("finance") or {}
    valuation = dd.get("valuation_detail") or {}
    catalysts = dd.get("catalysts") or {}
    
    spot = _safe_float(thesis.get("spot_price"))
    if spot <= 0:
        return {"success": False, "error": "Insufficient data: no spot price."}
    
    dcf_fair = _safe_float(valuation.get("fair_value")) or _safe_float(thesis.get("dcf_fair_value"))
    if dcf_fair <= 0:
        return {"success": False, "error": "Insufficient data: DCF fair value not available."}
    
    rev_growth_pct = _safe_float(finance.get("revenue_growth_yoy_pct"))
    rev_growth = (rev_growth_pct / 100.0) if rev_growth_pct else 0.05
    rev_growth = max(-0.10, min(0.40, rev_growth))
    
    # Use spot as entry if not specified
    entry = entry_price if entry_price > 0 else spot
    
    # ────── Price Ladder ──────
    bull_target = round(dcf_fair * (1 + rev_growth * 1.5), 2)
    base_target = round(dcf_fair, 2)
    
    # Entry zone: 5% below spot to spot+2% (institutional accumulation band)
    entry_low  = round(spot * 0.95, 2)
    entry_high = round(spot * 1.02, 2)
    
    # First trim: 50% of base case upside achieved
    trim_1 = round(spot + (base_target - spot) * 0.5, 2) if base_target > spot else round(base_target * 0.85, 2)
    
    # Second trim: base case (DCF reached)
    trim_2 = base_target
    
    # Final exit: bull target
    exit_full = bull_target
    
    # Stop-loss: -15% from entry (institutional default)
    stop_soft = round(entry * 0.85, 2)
    # Hard stop: thesis-broken (DCF compression to bear case)
    stop_hard = round(dcf_fair * 0.70, 2)
    
    # ────── Trailing Stop Ladder ──────
    trailing_ladder = [
        {"trigger_pct": 10, "lock_pct": 0,  "rule": "At +10% gain, ratchet stop to entry breakeven (no-loss lock)"},
        {"trigger_pct": 25, "lock_pct": 10, "rule": "At +25% gain, ratchet stop to +10% (lock first profit)"},
        {"trigger_pct": 50, "lock_pct": 25, "rule": "At +50% gain, ratchet stop to +25% (compound discipline)"},
    ]
    
    # ────── Time Stop ──────
    # Default: 6 quarters for 1Y thesis, 12Q for 3Y
    time_stop_quarters = 6  # ~18 months
    
    # ────── Catalyst Window ──────
    next_earn = (catalysts.get("next_earnings") or {}) if isinstance(catalysts.get("next_earnings"), dict) else {}
    catalyst_window = None
    if next_earn.get("date"):
        catalyst_window = {
            "next_earnings_date": next_earn.get("date"),
            "days_until":         next_earn.get("days_until"),
            "rule": (
                "Re-evaluate position after earnings. If EPS misses by >10% OR guidance reduced, "
                "exit immediately regardless of price level (thesis-broken stop)."
            ),
        }
    
    # ────── Position Sizing (Kelly-Bounded) ──────
    # Conservative: max 3% per single position
    # Initial: 2% if base case > 15% upside, else 1%
    base_upside_pct = (base_target - entry) / entry * 100 if entry > 0 else 0
    
    initial_size = 2.0 if base_upside_pct > 15 else 1.0
    add_at_entry_low = 1.0 if base_upside_pct > 25 else 0.5
    max_size = min(3.0, initial_size + add_at_entry_low + 0.5)  # cap at 3%
    
    return {
        "success": True,
        "symbol": symbol,
        "spot": round(spot, 2),
        "entry": round(entry, 2),
        "ladder": {
            "stop_hard":    {"price": stop_hard,  "pct_from_entry": round((stop_hard - entry) / entry * 100, 1), "label": "Thesis-broken (DCF compression)"},
            "stop_soft":    {"price": stop_soft,  "pct_from_entry": round((stop_soft - entry) / entry * 100, 1), "label": "Soft stop (-15%)"},
            "entry_low":    {"price": entry_low,  "pct_from_entry": round((entry_low - entry) / entry * 100, 1), "label": "Optimal accumulation low"},
            "entry":        {"price": round(entry, 2), "pct_from_entry": 0, "label": "Entry (spot)"},
            "entry_high":   {"price": entry_high, "pct_from_entry": round((entry_high - entry) / entry * 100, 1), "label": "Accumulation ceiling"},
            "trim_1":       {"price": trim_1,     "pct_from_entry": round((trim_1 - entry) / entry * 100, 1), "label": "Trim 25% (1Y target)"},
            "trim_2":       {"price": trim_2,     "pct_from_entry": round((trim_2 - entry) / entry * 100, 1), "label": "Trim 50% (DCF base)"},
            "exit_full":    {"price": exit_full,  "pct_from_entry": round((exit_full - entry) / entry * 100, 1), "label": "Sell remaining (bull case)"},
        },
        "trailing_stops": trailing_ladder,
        "time_stop": {
            "quarters": time_stop_quarters,
            "rule": f"Exit position if no progress toward base target ${base_target:.2f} within {time_stop_quarters} quarters.",
        },
        "catalyst_window": catalyst_window,
        "position_sizing": {
            "initial_pct":      initial_size,
            "add_at_entry_low": add_at_entry_low,
            "max_pct":          max_size,
            "base_upside_pct":  round(base_upside_pct, 1),
            "rationale":        f"Initial {initial_size}% based on {base_upside_pct:.0f}% base case upside. Kelly-bounded max {max_size}%.",
        },
    }


# ═══════════════════════════════════════════════════════════════════
# r63.25: Catalyst Calendar — next 4 quarters of known events
# ═══════════════════════════════════════════════════════════════════

@app.get("/api/catalyst-calendar")
async def catalyst_calendar(symbol: str = "", region: str = "US", email: str = ""):
    """r63.25: Returns next 4 quarters of catalysts (earnings + macro + sector)."""
    from datetime import datetime as _dt6, timedelta as _td6
    
    email = (email or "").strip().lower()
    _ok, email = check_premium_gate(email, "dream")
    if not _ok:
        return {"success": False, "error": "Premium tier required."}
    
    symbol = (symbol or "").strip().upper()
    if not symbol:
        return {"success": False, "error": "symbol required"}
    
    try:
        dd = await investor_due_diligence(email=email, symbol=symbol, region=region)
    except Exception as e:
        return {"success": False, "error": f"DD failed: {str(e)[:200]}"}
    
    if not dd.get("success"):
        return {"success": False, "error": "DD generation failed."}
    
    catalysts_obj = dd.get("catalysts") or {}
    earnings_history = dd.get("earnings_history") or {}
    
    today = _dt6.utcnow().date()
    events = []
    
    # ────── Next earnings (highest priority) ──────
    next_earn = catalysts_obj.get("next_earnings") if isinstance(catalysts_obj.get("next_earnings"), dict) else None
    if next_earn and next_earn.get("date"):
        try:
            ed = _dt6.strptime(next_earn["date"], "%Y-%m-%d").date()
            beat_rate = _safe_float(earnings_history.get("beat_rate_pct"))
            tag = "neutral"
            if beat_rate >= 70: tag = "bullish"
            elif beat_rate <= 40 and beat_rate > 0: tag = "bearish"
            
            events.append({
                "date":        ed.strftime("%Y-%m-%d"),
                "days_until":  (ed - today).days,
                "type":        "earnings",
                "title":       f"{symbol} Quarterly Earnings",
                "details":     f"Historical beat rate: {beat_rate:.0f}%" if beat_rate > 0 else "First earnings in window",
                "tag":         tag,
                "urgency":     next_earn.get("urgency", "MEDIUM"),
            })
        except Exception:
            pass
    
    # ────── Project next 3 quarterly earnings (~91 days apart) ──────
    if next_earn and next_earn.get("date"):
        try:
            ed = _dt6.strptime(next_earn["date"], "%Y-%m-%d").date()
            for q in range(1, 4):  # Q+1, Q+2, Q+3
                projected_date = ed + _td6(days=91 * q)
                events.append({
                    "date":       projected_date.strftime("%Y-%m-%d"),
                    "days_until": (projected_date - today).days,
                    "type":       "earnings_projected",
                    "title":      f"{symbol} Q+{q} Earnings (projected)",
                    "details":    "Projected from quarterly cadence",
                    "tag":        "neutral",
                    "urgency":    "LOW",
                })
        except Exception: pass
    
    # ────── Dividend ex-date (if available) ──────
    div = catalysts_obj.get("dividend") if isinstance(catalysts_obj.get("dividend"), dict) else None
    if div and div.get("ex_date"):
        try:
            xd = _dt6.strptime(div["ex_date"], "%Y-%m-%d").date()
            if xd >= today and (xd - today).days <= 365:
                events.append({
                    "date":       xd.strftime("%Y-%m-%d"),
                    "days_until": (xd - today).days,
                    "type":       "dividend",
                    "title":      f"{symbol} Dividend Ex-Date",
                    "details":    f"Yield: {div.get('yield_pct', 'N/A')}% · Pays: ${div.get('amount', 'N/A')}",
                    "tag":        "bullish",
                    "urgency":    "LOW",
                })
        except Exception: pass
    
    # ────── Macro (Fed FOMC dates approximate — institutional discipline) ──────
    # FOMC meets ~8 times/year. Use approximate schedule (real institutional tools subscribe).
    # Conservative: just add quarterly Fed checkpoints
    for q_offset in range(1, 4):
        approx_fomc = today + _td6(days=int(82 * q_offset))  # rough Fed cadence
        if (approx_fomc - today).days <= 365:
            events.append({
                "date":       approx_fomc.strftime("%Y-%m-%d"),
                "days_until": (approx_fomc - today).days,
                "type":       "macro",
                "title":      "FOMC Meeting (approximate)",
                "details":    "Rates decision — affects multiple expansion thesis",
                "tag":        "unknown",
                "urgency":    "LOW",
            })
    
    # Sort by date
    events.sort(key=lambda e: e["days_until"])
    
    return {
        "success": True,
        "symbol":  symbol,
        "today":   today.strftime("%Y-%m-%d"),
        "events":  events,
        "summary": {
            "total":      len(events),
            "bullish":    sum(1 for e in events if e["tag"] == "bullish"),
            "bearish":    sum(1 for e in events if e["tag"] == "bearish"),
            "earnings":   sum(1 for e in events if e["type"] in ("earnings", "earnings_projected")),
        },
    }

_portfolio_progress = {"done": 0, "total": 0, "current": "", "started": 0, "active": False}

@app.get("/api/portfolio-scan-progress")
async def portfolio_scan_progress():
    """Real-time progress for portfolio scan"""
    p = _portfolio_progress
    if not p["active"]:
        return {"active": False}
    elapsed = round(time.time() - p["started"], 1) if p["started"] else 0
    pct = round(p["done"] / max(p["total"], 1) * 100, 1)
    remaining = p["total"] - p["done"]
    # Estimate time: avg time per stock so far
    avg_per = elapsed / max(p["done"], 1)
    eta = round(avg_per * remaining, 0)
    return {
        "active": True, "done": p["done"], "total": p["total"],
        "pct": pct, "current": p["current"], "elapsed": elapsed,
        "remaining": remaining, "eta": eta,
    }

@app.post("/api/portfolio-scan")
async def portfolio_scan(request: Request):
    """Batch scan uploaded stock list through Decide Investment Engine"""
    global _portfolio_progress
    try:
        body = await request.json()
        symbols = body.get("symbols", [])
        region = body.get("region", "IN")
        
        if not symbols:
            return {"success": False, "error": "No symbols provided"}
        if len(symbols) > 50:
            symbols = symbols[:50]  # Cap at 50
        
        # Clean symbols
        clean = []
        for s in symbols:
            s = str(s).strip().upper().replace(".NS", "").replace(".BO", "").replace(" ", "")
            if s and len(s) >= 2 and len(s) <= 20 and s.isalnum():
                clean.append(s)
        
        if not clean:
            return {"success": False, "error": "No valid stock symbols found in file"}
        
        print(f"\n📋 Portfolio Scan: {len(clean)} stocks ({region})")
        t0 = time.time()
        _portfolio_progress = {"done": 0, "total": len(clean), "current": "", "started": t0, "active": True}
        
        # Run investor_decide on each stock (parallel, max 5 at a time)
        results = []
        semaphore = asyncio.Semaphore(5)
        
        async def _scan_one(sym):
            async with semaphore:
                _portfolio_progress["current"] = sym
                try:
                    r = await asyncio.wait_for(investor_decide(sym, region), timeout=25)
                    _portfolio_progress["done"] += 1
                    pct = round(_portfolio_progress["done"] / max(len(clean), 1) * 100, 0)
                    print(f"  📋 [{_portfolio_progress['done']}/{len(clean)}] {sym} → {r.get('decision','?') if r.get('success') else 'ERR'} ({pct}%)")
                    if r.get("success"):
                        return {
                            "symbol": sym,
                            "name": r.get("companyName", sym),
                            "price": r.get("price", 0),
                            "decision": r.get("decision", "HOLD / REVIEW"),
                            "decColor": r.get("decColor", "#6b7280"),
                            "fScore": r.get("business", {}).get("fScore", 0),
                            "moatScore": r.get("moat", {}).get("score", 0),
                            "moatVerdict": r.get("moat", {}).get("verdict", ""),
                            "valScore": r.get("valuation", {}).get("score", 0),
                            "upside": r.get("upside", 0),
                            "fairValue": r.get("intrinsicValue", {}).get("average", 0),
                            "pe": r.get("valuation", {}).get("pe", 0),
                            "roe": r.get("business", {}).get("roe", 0),
                            "debtEquity": r.get("business", {}).get("debtEquity", 0),
                            "divYield": r.get("business", {}).get("divYield", 0),
                            "sector": r.get("sector", ""),
                            "confidence": r.get("confidence", 0),
                            "explain": r.get("explain", ""),
                            "allocPct": r.get("allocation", {}).get("pct", ""),
                            "hi52": r.get("levels", {}).get("hi52", 0),
                            "lo52": r.get("levels", {}).get("lo52", 0),
                            "altmanZ": r.get("altmanZ", {}).get("score", 0),
                            "revCAGR": r.get("revCAGR", 0),
                            "buffettScore": r.get("buffett", {}).get("score", 0),
                            "dataConfident": r.get("dataConfident", True),
                        }
                    else:
                        return {"symbol": sym, "decision": "ERROR", "decColor": "#6b7280", "error": r.get("error", ""), "dataConfident": False}
                except Exception as e:
                    _portfolio_progress["done"] += 1
                    return {"symbol": sym, "decision": "ERROR", "decColor": "#6b7280", "error": str(e)[:80], "dataConfident": False}
        
        tasks = [_scan_one(s) for s in clean]
        raw = await asyncio.gather(*tasks)
        results = [r for r in raw if r]
        
        # ═══ PHASE 2: Scan ADD candidates through REAL Decide Engine ═══
        _portfolio_syms = set(s.upper() for s in clean)
        _add_candidates = [
            "TRENT","PERSISTENT","DIXON","POLYCAB","TATAELXSI","ZOMATO","HAL","BEL","KPITTECH",
            "IRFC","RVNL","KALYANKJIL","DEEPAKNTR","ASTRAL","DMART","BAJFINANCE","TITAN","BHARTIARTL",
            "COFORGE","LTIM","PIIND","COCHINSHIP","MAZAGON","TATAPOWER","ABB","SIEMENS","KAYNES",
            "CDSL","ANGELONE","TATATECH","SOLARINDS","LATENTVIEW","AFFLE","ROUTE","NETWEB",
        ] if region == "IN" else [
            "AAPL","MSFT","NVDA","GOOGL","AMZN","META","TSLA","AVGO","AMD","NFLX",
            "CRM","PLTR","CRWD","DDOG","NET","PANW","SNOW","COIN","SHOP","SQ",
        ]
        # Filter out stocks already in portfolio
        _add_to_scan = [s for s in _add_candidates if s not in _portfolio_syms][:12]
        
        if _add_to_scan:
            print(f"  🆕 Phase 2: Scanning {len(_add_to_scan)} ADD candidates through Decide Engine...")
            _portfolio_progress["current"] = "Scanning ADD candidates..."
            _portfolio_progress["total"] = len(clean) + len(_add_to_scan)
            
            async def _scan_add(sym):
                async with semaphore:
                    try:
                        r = await asyncio.wait_for(investor_decide(sym, region), timeout=20)
                        _portfolio_progress["done"] += 1
                        if not r.get("success"): return None
                        dec = r.get("decision", "")
                        # Only suggest if engine says INVEST NOW or START SIP
                        if dec not in ["INVEST NOW", "START SIP"]: return None
                        _f = r.get("business", {}).get("fScore", 0)
                        if _f < 5: return None  # Minimum quality
                        return {
                            "symbol": sym,
                            "name": r.get("companyName", sym),
                            "price": r.get("price", 0),
                            "decision": dec,
                            "decColor": r.get("decColor", "#10b981"),
                            "fScore": _f,
                            "moatScore": r.get("moat", {}).get("score", 0),
                            "upside": r.get("upside", 0),
                            "fairValue": r.get("intrinsicValue", {}).get("average", 0),
                            "roe": r.get("business", {}).get("roe", 0),
                            "revCAGR": r.get("revCAGR", 0),
                            "debtEquity": r.get("business", {}).get("debtEquity", 0),
                            "sector": r.get("sector", ""),
                            "confidence": r.get("confidence", 0),
                            "buffettScore": r.get("buffett", {}).get("score", 0),
                            "altmanZ": r.get("altmanZ", {}).get("score", 0),
                            "reason": f"Decide Engine: {dec} | F-Score {_f}/9 | Upside {r.get('upside',0):.0f}% | ROE {r.get('business',{}).get('roe',0):.0f}%",
                        }
                    except: 
                        _portfolio_progress["done"] += 1
                        return None
            
            add_raw = await asyncio.gather(*[_scan_add(s) for s in _add_to_scan])
            add_results = sorted([r for r in add_raw if r], key=lambda x: x.get("fScore", 0) * 10 + x.get("upside", 0), reverse=True)[:8]
            print(f"  🆕 Phase 2 done: {len(add_results)} stocks qualify as ADD suggestions")
        else:
            add_results = []
        
        _portfolio_progress["active"] = False
        
        # Categorize
        invest_now = sorted([r for r in results if r["decision"] == "INVEST NOW"], key=lambda x: x.get("upside", 0), reverse=True)
        start_sip = sorted([r for r in results if r["decision"] == "START SIP"], key=lambda x: x.get("fScore", 0) + x.get("upside", 0) * 0.1, reverse=True)
        overpriced = sorted([r for r in results if "OVERPRICED" in r["decision"]], key=lambda x: x.get("fScore", 0), reverse=True)
        avoid = [r for r in results if "AVOID" in r["decision"]]
        hold = [r for r in results if r["decision"] in ["HOLD / REVIEW"]]
        errors = [r for r in results if r["decision"] == "ERROR"]
        data_na = [r for r in results if "DATA" in r.get("decision", "") or "INSUFFICIENT" in r.get("decision", "")]
        
        # Add rank
        rank = 1
        for lst in [invest_now, start_sip, overpriced, hold, avoid]:
            for r in lst:
                r["rank"] = rank
                rank += 1
        
        elapsed = round(time.time() - t0, 1)
        print(f"  ✅ Scanned {len(results)}/{len(clean)} in {elapsed}s — Invest: {len(invest_now)}, SIP: {len(start_sip)}, Overpriced: {len(overpriced)}, Avoid: {len(avoid)}")
        
        # ═══ PHASE 3: Real Historical Risk Metrics + Monte Carlo ═══
        risk_data = {}
        try:
            import numpy as np
            _portfolio_progress["current"] = "Computing risk metrics..."
            
            # Identify retain-worthy stocks (same logic as frontend)
            _retain_syms = []
            for r in results:
                if r.get("decision") in ["INVEST NOW", "START SIP"] and r.get("fScore", 0) >= 5:
                    _retain_syms.append(r["symbol"])
            
            if len(_retain_syms) >= 3:
                is_us = region.upper() == "US"
                _bench_sym = "^GSPC" if is_us else "^NSEI"  # S&P500 or Nifty50
                _all_syms = _retain_syms[:20] + [_bench_sym]  # Cap at 20 + benchmark
                
                # Fetch 1Y daily closes for all stocks + benchmark in one batch
                def _fetch_history_batch(syms):
                    import pandas as pd
                    closes = {}
                    for sym in syms:
                        try:
                            _yf_sym = sym if sym.startswith("^") else (sym if is_us else f"{sym}.NS")
                            _yahoo_rate_wait()

                            tk = yf.Ticker(_yf_sym)
                            h = tk.history(period="1y")
                            if len(h) >= 60:  # Need at least 60 days
                                closes[sym] = h["Close"].values.astype(float)
                        except:
                            pass
                    return closes
                
                _lp3 = asyncio.get_event_loop()
                _closes = await _lp3.run_in_executor(None, lambda: _fetch_history_batch(_all_syms))
                
                if len(_closes) >= 3:
                    # Daily returns for each stock
                    _returns = {}
                    _min_len = min(len(v) for v in _closes.values())
                    for sym, prices in _closes.items():
                        p = prices[-_min_len:]  # Align lengths
                        dr = np.diff(p) / p[:-1]  # Daily returns
                        _returns[sym] = dr
                    
                    # Benchmark returns
                    _bench_ret = _returns.get(_bench_sym, np.zeros(10))
                    
                    # Portfolio returns (equal-weighted for simplicity)
                    _port_syms = [s for s in _retain_syms[:20] if s in _returns]
                    if len(_port_syms) >= 2:
                        _port_daily = np.mean([_returns[s] for s in _port_syms], axis=0)
                        
                        # === ACTUAL RISK METRICS ===
                        _ann_factor = 252
                        _port_vol = float(np.std(_port_daily) * np.sqrt(_ann_factor) * 100)
                        _port_mean = float(np.mean(_port_daily) * _ann_factor * 100)
                        _rf = 4.5 if is_us else 7.0
                        _sharpe = round((_port_mean - _rf) / max(_port_vol, 1), 2)
                        
                        # Sortino (downside deviation only)
                        _down = _port_daily[_port_daily < 0]
                        _down_vol = float(np.std(_down) * np.sqrt(_ann_factor) * 100) if len(_down) > 5 else _port_vol
                        _sortino = round((_port_mean - _rf) / max(_down_vol, 1), 2)
                        
                        # Max Drawdown from actual equity curve
                        _cum = np.cumprod(1 + _port_daily)
                        _peak = np.maximum.accumulate(_cum)
                        _dd = (_cum - _peak) / _peak
                        _max_dd = round(float(np.min(_dd)) * 100, 1)
                        
                        # Beta vs benchmark
                        if len(_bench_ret) == len(_port_daily):
                            _cov = np.cov(_port_daily, _bench_ret)
                            _beta = round(float(_cov[0, 1] / max(_cov[1, 1], 1e-10)), 2)
                        else:
                            _beta = 1.0
                        
                        # Correlation matrix (top 8 stocks)
                        _corr_syms = _port_syms[:8]
                        _corr_matrix = []
                        for i, s1 in enumerate(_corr_syms):
                            row = []
                            for j, s2 in enumerate(_corr_syms):
                                if i == j:
                                    row.append(1.0)
                                else:
                                    c = float(np.corrcoef(_returns[s1], _returns[s2])[0, 1])
                                    row.append(round(c, 2))
                            _corr_matrix.append(row)
                        _avg_corr = round(float(np.mean([_corr_matrix[i][j] for i in range(len(_corr_syms)) for j in range(i+1, len(_corr_syms))])), 2) if len(_corr_syms) > 1 else 0
                        
                        # === MONTE CARLO: 1000 portfolio simulations ===
                        _n_sims = 1000
                        _n_days = 252 * 10  # 10 years
                        _daily_mean = float(np.mean(_port_daily))
                        _daily_std = float(np.std(_port_daily))
                        
                        np.random.seed(42)
                        _mc_final = []
                        _mc_paths_sampled = []  # Save 5 sample paths for chart
                        for sim in range(_n_sims):
                            _rand = np.random.normal(_daily_mean, _daily_std, _n_days)
                            _path = np.cumprod(1 + _rand)
                            _mc_final.append(float(_path[-1]))
                            if sim < 5:
                                # Sample every 252 days (yearly) for chart
                                _yearly = [1.0] + [float(_path[min(y*252-1, _n_days-1)]) for y in range(1, 11)]
                                _mc_paths_sampled.append(_yearly)
                        
                        _mc_final.sort()
                        _mc_p10 = round(_mc_final[int(_n_sims * 0.10)], 2)
                        _mc_p25 = round(_mc_final[int(_n_sims * 0.25)], 2)
                        _mc_p50 = round(_mc_final[int(_n_sims * 0.50)], 2)
                        _mc_p75 = round(_mc_final[int(_n_sims * 0.75)], 2)
                        _mc_p90 = round(_mc_final[int(_n_sims * 0.90)], 2)
                        
                        # Recovery time estimate from max drawdown
                        if _max_dd < -30:
                            _recovery = "18-24 months"
                        elif _max_dd < -20:
                            _recovery = "12-18 months"
                        else:
                            _recovery = "6-12 months"
                        
                        risk_data = {
                            "real": True,
                            "sharpe": _sharpe, "sortino": _sortino,
                            "maxDD": _max_dd, "recovery": _recovery,
                            "beta": _beta, "vol": round(_port_vol, 1),
                            "annReturn": round(_port_mean, 1),
                            "corrMatrix": _corr_matrix, "corrSyms": _corr_syms,
                            "avgCorr": _avg_corr,
                            "mc": {"p10": _mc_p10, "p25": _mc_p25, "p50": _mc_p50, "p75": _mc_p75, "p90": _mc_p90},
                            "mcPaths": _mc_paths_sampled,
                            "stockCount": len(_port_syms),
                        }
                        print(f"  📊 Phase 3 done: Sharpe {_sharpe}, Sortino {_sortino}, MaxDD {_max_dd}%, Beta {_beta}, Vol {_port_vol:.1f}%, MC p50 {_mc_p50}x, AvgCorr {_avg_corr}")
        except Exception as _risk_err:
            print(f"  ⚠️ Phase 3 risk computation failed: {_risk_err}")
            import traceback; traceback.print_exc()
        
        # ═══════════════════════════════════════════════════════════════
        # PORTFOLIO DOCTOR — Cross-portfolio diagnosis
        # ═══════════════════════════════════════════════════════════════
        print(f"  🩺 Portfolio Doctor analysis...")
        portfolio_doctor = {}
        try:
            import numpy as _np2
            _valid = [r for r in results if r.get("decision") != "ERROR" and r.get("dataConfident", True)]
            _n_stocks = len(_valid)

            # 1. Over-diversification check
            _over_div = {}
            if _n_stocks > 25:
                _over_div = {"score": 90, "count": _n_stocks, "threshold": 25, "verdict": "SEVERELY OVER-DIVERSIFIED",
                    "color": "#ef4444", "detail": f"Portfolio has {_n_stocks} stocks. Beyond 20-25 stocks, each new addition dilutes returns. Buffett holds 5-10 concentrated bets. Trim to your 15-20 highest conviction picks."}
            elif _n_stocks > 18:
                _over_div = {"score": 60, "count": _n_stocks, "threshold": 18, "verdict": "MODERATELY DIVERSIFIED",
                    "color": "#f59e0b", "detail": f"Portfolio has {_n_stocks} stocks. Could tighten to 12-15 for better concentration. Over-diversification = guaranteed mediocrity."}
            elif _n_stocks >= 8:
                _over_div = {"score": 20, "count": _n_stocks, "threshold": 18, "verdict": "WELL SIZED",
                    "color": "#10b981", "detail": f"Portfolio has {_n_stocks} stocks — good concentration. Enough diversification to manage risk, tight enough to generate alpha."}
            else:
                _over_div = {"score": 40, "count": _n_stocks, "threshold": 8, "verdict": "CONCENTRATED",
                    "color": "#3b82f6", "detail": f"Only {_n_stocks} stocks — high conviction but high risk. One bad pick can drag CAGR significantly. Ensure each has strong fundamentals."}

            # 2. Duplicate theme / sector concentration detection
            _sectors = {}
            for r in _valid:
                sec = r.get("sector", "Unknown") or "Unknown"
                if sec not in _sectors: _sectors[sec] = []
                _sectors[sec].append(r.get("symbol", "?"))

            _dup_themes = []
            for sec, syms in _sectors.items():
                if len(syms) >= 3:
                    _dup_themes.append({
                        "theme": sec,
                        "stocks": syms,
                        "count": len(syms),
                        "risk": "HIGH" if len(syms) >= 5 else "MEDIUM",
                        "color": "#ef4444" if len(syms) >= 5 else "#f59e0b",
                        "detail": f"{len(syms)} stocks in {sec} — if this sector crashes, {len(syms)}/{_n_stocks} of your portfolio suffers simultaneously."
                    })

            _sector_pcts = {sec: round(len(syms) / max(_n_stocks, 1) * 100, 1) for sec, syms in _sectors.items()}
            _max_sector = max(_sector_pcts.values()) if _sector_pcts else 0
            _max_sector_name = max(_sector_pcts, key=_sector_pcts.get) if _sector_pcts else ""

            _sector_conc = {
                "sectors": _sector_pcts,
                "maxPct": _max_sector,
                "maxSector": _max_sector_name,
                "totalSectors": len(_sectors),
                "verdict": "CONCENTRATED RISK" if _max_sector > 40 else "MODERATE" if _max_sector > 25 else "WELL SPREAD",
                "color": "#ef4444" if _max_sector > 40 else "#f59e0b" if _max_sector > 25 else "#10b981",
            }

            # 3. CAGR Drag — weak stocks pulling down portfolio
            _cagr_drag = []
            for r in _valid:
                _drag_reasons = []
                _drag_score = 0
                if r.get("fScore", 9) <= 3:
                    _drag_reasons.append(f"F-Score {r['fScore']}/9 — fundamentally weak")
                    _drag_score += 30
                if "AVOID" in r.get("decision", ""):
                    _drag_reasons.append(f"Engine says AVOID")
                    _drag_score += 40
                if r.get("upside", 0) < -20:
                    _drag_reasons.append(f"Overvalued by {abs(r['upside']):.0f}%")
                    _drag_score += 20
                if r.get("moatScore", 100) < 25:
                    _drag_reasons.append(f"Moat score only {r['moatScore']}")
                    _drag_score += 15
                if r.get("altmanZ", 3) > 0 and r.get("altmanZ", 3) < 1.8:
                    _drag_reasons.append(f"Altman Z {r['altmanZ']:.1f} — distress zone")
                    _drag_score += 25

                if _drag_score >= 30:
                    _cagr_drag.append({
                        "symbol": r.get("symbol", "?"),
                        "name": r.get("name", ""),
                        "dragScore": min(100, _drag_score),
                        "reasons": _drag_reasons,
                        "decision": r.get("decision", ""),
                        "fScore": r.get("fScore", 0),
                        "upside": r.get("upside", 0),
                        "color": "#ef4444" if _drag_score >= 50 else "#f59e0b"
                    })

            _cagr_drag.sort(key=lambda x: x["dragScore"], reverse=True)

            # 4. Portfolio quality distribution (for DNA chart)
            _dna = {"growth": 0, "quality": 0, "value": 0, "cyclical": 0, "weak": 0}
            for r in _valid:
                _fs = r.get("fScore", 0)
                _moat = r.get("moatScore", 0)
                _upside = r.get("upside", 0)
                _dec = r.get("decision", "")

                if _dec == "INVEST NOW" and _fs >= 7 and _moat >= 60:
                    _dna["quality"] += 1
                elif _dec in ["INVEST NOW", "START SIP"] and _upside > 20:
                    _dna["growth"] += 1
                elif "OVERPRICED" in _dec and _fs >= 6:
                    _dna["value"] += 1  # Good company, just expensive
                elif _fs <= 3 or "AVOID" in _dec:
                    _dna["weak"] += 1
                else:
                    _dna["cyclical"] += 1

            _dna_pct = {k: round(v / max(_n_stocks, 1) * 100, 1) for k, v in _dna.items()}

            # 5. Overall CAGR probability assessment
            _quality_count = sum(1 for r in _valid if r.get("fScore", 0) >= 6 and r.get("upside", 0) > 0)
            _quality_pct = round(_quality_count / max(_n_stocks, 1) * 100, 0)
            _weak_count = len(_cagr_drag)
            _weak_pct = round(_weak_count / max(_n_stocks, 1) * 100, 0)

            # Portfolio score (0-100)
            _p_score = 0
            _p_score += min(30, int(_quality_pct * 0.3))  # Up to 30 pts for quality stocks
            _p_score += max(0, 20 - len(_cagr_drag) * 5)  # Up to 20 pts, lose 5 per drag
            _p_score += max(0, 15 - len(_dup_themes) * 5)  # Up to 15 pts for theme diversity
            _p_score += 15 if _n_stocks >= 8 and _n_stocks <= 20 else 5  # Sizing
            if _max_sector <= 30: _p_score += 10
            elif _max_sector <= 40: _p_score += 5
            # Sharpe bonus
            if risk_data.get("sharpe", 0) > 1.5: _p_score += 10
            elif risk_data.get("sharpe", 0) > 1.0: _p_score += 7
            elif risk_data.get("sharpe", 0) > 0.5: _p_score += 3
            _p_score = max(0, min(100, _p_score))

            _p_grade = "A+" if _p_score >= 85 else "A" if _p_score >= 75 else "B+" if _p_score >= 65 else "B" if _p_score >= 55 else "C+" if _p_score >= 45 else "C" if _p_score >= 35 else "D"

            _can_30 = _quality_pct >= 60 and _weak_pct <= 15 and _p_score >= 60
            _cagr_verdict = "ON TRACK for 30% CAGR" if _can_30 else "UNLIKELY to reach 30% CAGR" if _p_score < 40 else "NEEDS WORK to reach 30% CAGR"
            _cagr_color = "#10b981" if _can_30 else "#ef4444" if _p_score < 40 else "#f59e0b"

            # 6. Auto-generated recommendations
            _recs = []
            if len(_cagr_drag) > 0:
                _drag_syms = ", ".join([d["symbol"] for d in _cagr_drag[:3]])
                _recs.append({"action": "SELL", "detail": f"Exit weak stocks: {_drag_syms} — these are dragging your CAGR", "color": "#ef4444", "priority": "HIGH"})
            if _max_sector > 40:
                _recs.append({"action": "REBALANCE", "detail": f"Reduce {_max_sector_name} exposure from {_max_sector:.0f}% to below 30%", "color": "#f59e0b", "priority": "MEDIUM"})
            if len(_dup_themes) >= 2:
                _recs.append({"action": "DIVERSIFY", "detail": f"{len(_dup_themes)} sector themes are overloaded — spread across more sectors", "color": "#f59e0b", "priority": "MEDIUM"})
            if _n_stocks > 25:
                _recs.append({"action": "TRIM", "detail": f"Too many stocks ({_n_stocks}). Consolidate to your top 15-20 highest-conviction picks", "color": "#f59e0b", "priority": "MEDIUM"})
            if _quality_pct < 40:
                _recs.append({"action": "UPGRADE QUALITY", "detail": f"Only {_quality_pct:.0f}% of portfolio is high-quality (F-Score≥6, positive upside). Target 60%+", "color": "#ef4444", "priority": "HIGH"})
            if len(_recs) == 0:
                _recs.append({"action": "HOLD", "detail": "Portfolio looks healthy. Keep monitoring quarterly earnings and rebalance if any stock triggers exit criteria.", "color": "#10b981", "priority": "LOW"})

            # 7. Quick insight cards (auto-generated from data)
            _insights = []
            # Top contributors
            _top_f = sorted([r for r in _valid if r.get("decision") == "INVEST NOW"], key=lambda x: x.get("fScore", 0), reverse=True)
            if len(_top_f) >= 2:
                _insights.append({"icon": "🏆", "text": f"{_top_f[0]['symbol']} and {_top_f[1]['symbol']} are your strongest holdings (F-Score {_top_f[0]['fScore']}/9 and {_top_f[1]['fScore']}/9)"})
            # Valuation risk
            _overval_count = len(overpriced) + len(avoid)
            if _overval_count >= 3:
                _insights.append({"icon": "⚠️", "text": f"{_overval_count} stocks are overvalued or flagged AVOID — {round(_overval_count/_n_stocks*100)}% of portfolio at risk"})
            # Sector gap
            _missing_sectors = []
            _key_sectors = ["Technology", "Financial Services", "Healthcare", "Consumer Defensive", "Industrials"]
            for ks in _key_sectors:
                if ks not in _sectors and not any(ks.lower() in s.lower() for s in _sectors):
                    _missing_sectors.append(ks)
            if _missing_sectors:
                _insights.append({"icon": "🔍", "text": f"Missing exposure to: {', '.join(_missing_sectors[:3])}"})
            # Risk-return
            if risk_data.get("sharpe", 0) > 0:
                _insights.append({"icon": "📊", "text": f"Sharpe ratio {risk_data['sharpe']:.2f} — {'excellent' if risk_data['sharpe'] > 1.5 else 'good' if risk_data['sharpe'] > 1 else 'decent' if risk_data['sharpe'] > 0.5 else 'below average'} risk-adjusted returns"})

            portfolio_doctor = {
                "portfolioScore": _p_score,
                "portfolioGrade": _p_grade,
                "cagrVerdict": _cagr_verdict,
                "cagrColor": _cagr_color,
                "overDiversification": _over_div,
                "duplicateThemes": _dup_themes,
                "sectorConcentration": _sector_conc,
                "cagrDrag": _cagr_drag[:5],  # Top 5 worst
                "dna": _dna,
                "dnaPct": _dna_pct,
                "recommendations": _recs,
                "insights": _insights,
                "qualityPct": _quality_pct,
                "weakPct": _weak_pct,
            }
            print(f"  🩺 Portfolio Doctor done: Score={_p_score} Grade={_p_grade} | {_cagr_verdict} | Drag={len(_cagr_drag)} Theme-dup={len(_dup_themes)}")

        except Exception as _doc_err:
            print(f"  ⚠️ Portfolio Doctor failed: {_doc_err}")
            import traceback; traceback.print_exc()

        csym = "$" if region == "US" else "₹"
        return {
            "success": True, "totalScanned": len(results), "elapsed": elapsed, "csym": csym,
            "investNow": invest_now, "startSip": start_sip, "overpriced": overpriced,
            "avoid": avoid, "hold": hold, "errors": errors, "dataNA": data_na,
            "addSuggestions": add_results,
            "riskMetrics": risk_data,
            "portfolioDoctor": portfolio_doctor,
            "summary": {
                "total": len(results),
                "investNow": len(invest_now), "startSip": len(start_sip),
                "overpriced": len(overpriced), "avoid": len(avoid),
                "hold": len(hold), "errors": len(errors),
            }
        }
    except Exception as e:
        import traceback; traceback.print_exc()
        return {"success": False, "error": str(e)[:200]}


@app.get("/api/cross-market-match")
async def cross_market_match(symbol: str = "MU", region: str = "US", mode: str = "cross"):
    """Find matching stocks based on DECIDE ENGINE profile similarity.
    mode=cross -> scan other market. mode=same -> scan same market for hidden gems."""
    try:
        # yfinance imported globally with 401 wrapper, math
        t0 = time.time()
        is_us = region.upper() == "US"
        target_region = region.upper() if mode == "same" else ("IN" if is_us else "US")
        csym_target = "\u20b9" if target_region == "IN" else "$"
        
        # 1. Run SOURCE through REAL Decide Engine
        print(f"\n\U0001f310 {mode.upper()}-market: investor_decide({symbol})...")
        src_result = await investor_decide(symbol, region)
        if not src_result.get("success"):
            return {"success": False, "error": f"Decide Engine failed for {symbol}: {src_result.get('error','')}"}
        
        src_biz = src_result.get("business", {})
        src_moat = src_result.get("moat", {})
        src_val = src_result.get("valuation", {})
        src_alloc = src_result.get("allocation", {})
        src_buffett = src_result.get("buffett", {})
        src = {
            "fScore": src_biz.get("fScore", 0), "fGrade": src_biz.get("grade", ""),
            "moatScore": src_moat.get("score", 0), "moatVerdict": src_moat.get("verdict", ""),
            "valScore": src_val.get("score", 50), "pe": src_val.get("pe", 0),
            "upside": src_result.get("upside", 0), "confidence": src_result.get("confidence", 50),
            "decision": src_result.get("decision", ""),
            "kellyPct": src_alloc.get("kellyFull", 0), "allocTier": src_alloc.get("tier", ""),
            "buffettScore": src_buffett.get("score", 0),
            "sector": src_result.get("sector", ""), "price": src_result.get("price", 0),
        }
        print(f"   Source: F={src['fScore']} Moat={src['moatScore']} Val={src['valScore']} Buffett={src['buffettScore']} Conf={src['confidence']}")
        
        # 2. Batch-scan target universe
        cache_key = f"xm_{target_region}_{mode}"
        if cache_key in _cross_cache and time.time() - _cross_cache[cache_key]["ts"] < 300:
            all_stocks = _cross_cache[cache_key]["data"]
            print(f"   Cached {target_region}: {len(all_stocks)} stocks")
        else:
            if target_region == "IN":
                universe = [
                    "RELIANCE","TCS","HDFCBANK","INFY","ICICIBANK","BHARTIARTL","ITC","LT","SBIN","AXISBANK",
                    "KOTAKBANK","BAJFINANCE","MARUTI","TATAMOTORS","SUNPHARMA","HCLTECH","WIPRO","NTPC","POWERGRID","ONGC",
                    "ADANIENT","TITAN","NESTLEIND","ULTRACEMCO","JSWSTEEL","M&M","TATASTEEL","BAJAJ-AUTO","HDFCLIFE","DIVISLAB",
                    "DRREDDY","CIPLA","COALINDIA","VEDL","GAIL","TRENT","ZOMATO","POLYCAB","PERSISTENT","HAL",
                    "BEL","DLF","SIEMENS","ABB","DIXON","SUZLON","NHPC","TATAPOWER",
                    "HINDALCO","BPCL","TECHM","HINDUNILVR","ASIANPAINT","GRASIM","BAJAJFINSV","INDUSINDBK",
                    "GODREJCP","PIDILITIND","HAVELLS","COLPAL","DABUR","MARICO","TORNTPHARM",
                    "MUTHOOTFIN","NAUKRI","DMART","BANKBARODA","PNB","IRCTC",
                    "VOLTAS","CROMPTON","BATAINDIA","MPHASIS","LTIM","COFORGE",
                    "CUMMINSIND","BHARATFORG","BOSCHLTD","MOTHERSON",
                    "SAIL","NMDC","AUROPHARMA","BIOCON","APOLLOHOSP","MAXHEALTH","FORTIS",
                    "SBICARD","CHOLAFIN","ASTRAL","TATAELXSI","KPITTECH",
                    "CDSL","BSE","MCX","ANGELONE","JIOFIN",
                    "TATACONSUM","GODREJPROP","OBEROIRLTY","PRESTIGE",
                    "PIIND","DEEPAKNTR","SRF","TATACHEM","UPL",
                    "MAZAGON","COCHINSHIP","BDL","RVNL","IRCON",
                    "CGPOWER","APAR","INOXWIND","BLUESTARCO","AMBER",
                    "PFIZER","GLAND","NATCOPHARM","TORNTPOWER","JSWENERGY",
                    "HUDCO","HDFCAMC","ZYDUSLIFE","LUPIN",
                    "IEX","CAMS","BIRLASOFT","ZENSAR","INDIANHOTELS",
                    "KAYNES","ELECON","VGUARD","GRINDWELL","PRAJ",
                    "HONASA","VARUN","BIKAJI","DEVYANI","JUBLFOOD",
                ]
                suffix = ".NS"
            else:
                universe = [
                    "AAPL","MSFT","NVDA","AMZN","GOOGL","META","AVGO","LLY","JPM","V","UNH","XOM","MA","COST",
                    "HD","PG","JNJ","ABBV","MRK","WMT","BAC","CRM","ORCL","CVX","NFLX","AMD","PEP","KO",
                    "ADBE","WFC","MCD","CSCO","GE","NOW","TXN","QCOM","GS","CAT","AXP","UBER","SBUX","PFE",
                    "HON","DE","MS","BA","INTC","BLK","PLTR","PANW","CRWD","SYK",
                    "TSLA","PYPL","DIS","NKE","SQ","COIN","SOFI","TSM","ASML","ARM","SNOW","NET","DDOG","ABNB","SHOP",
                ]
                suffix = ""
            universe = [s for s in universe if s != symbol]
            loop = asyncio.get_event_loop()
            def _batch_xm(syms):
                results = []
                try:
                    yf_syms = [s + suffix for s in syms]
                    tickers = yf.Tickers(" ".join(yf_syms))
                    for sym in syms:
                        try:
                            tk = tickers.tickers.get(sym + suffix)
                            if not tk: continue
                            info = tk.info or {}
                            price = float(info.get("currentPrice", 0) or info.get("regularMarketPrice", 0) or 0)
                            if price <= 0: continue
                            _pe = float(info.get("trailingPE", 0) or 0)
                            _roe = float(info.get("returnOnEquity", 0) or 0) * 100
                            _npm = float(info.get("profitMargins", 0) or 0) * 100
                            _gm = float(info.get("grossMargins", 0) or 0) * 100
                            _rev_g = float(info.get("revenueGrowth", 0) or 0) * 100
                            _earn_g = float(info.get("earningsGrowth", 0) or 0) * 100
                            _de = float(info.get("debtToEquity", 0) or 0)
                            _eps = float(info.get("trailingEps", 0) or 0)
                            _bv = float(info.get("bookValue", 0) or 0)
                            _mcap = float(info.get("marketCap", 0) or 0)
                            _target = float(info.get("targetMeanPrice", 0) or 0)
                            _cr = float(info.get("currentRatio", 0) or 0)
                            _om = float(info.get("operatingMargins", 0) or 0) * 100
                            _div_y = float(info.get("dividendYield", 0) or 0) * 100
                            _hi52 = float(info.get("fiftyTwoWeekHigh", 0) or 0)
                            _lo52 = float(info.get("fiftyTwoWeekLow", 0) or 0)
                            _pctFromLow = round((price - _lo52) / max(_lo52, 1) * 100, 1) if _lo52 > 0 else 999
                            _pctFromHigh = round((_hi52 - price) / max(_hi52, 1) * 100, 1) if _hi52 > 0 else 0
                            # Mini-Decide: F-Score proxy (STRICT — no free points for missing data)
                            _f = 0
                            if _roe > 5: _f += 1          # ROE must be meaningfully positive
                            if _npm > 3: _f += 1          # Profit margin > 3%
                            if _earn_g > 0: _f += 1        # Earnings growing
                            if _npm > _om * 0.6 and _om > 0 and _npm > 0: _f += 1
                            if 0 < _de < 80: _f += 1      # Debt manageable (NOT zero = missing data)
                            elif _de == 0 and _eps > 0: _f += 1  # Truly debt-free (has earnings)
                            if _cr > 1.0: _f += 1          # Only if CR actually > 1 (not missing)
                            if _rev_g > 0: _f += 1
                            if _gm > 15: _f += 1           # Meaningful margin, not just > 0
                            # No free dilution point — keep F-Score conservative
                            # Mini-Decide: Moat proxy
                            _m = 0
                            if _gm > 50: _m += 20
                            elif _gm > 35: _m += 14
                            elif _gm > 20: _m += 6
                            if _roe > 30: _m += 14
                            elif _roe > 18: _m += 8
                            elif _roe > 10: _m += 3
                            if _rev_g > 12 and _earn_g > 12: _m += 16
                            elif _rev_g > 5 and _earn_g > 5: _m += 10
                            elif _rev_g > 0: _m += 5
                            if _de < 20: _m += 10
                            elif _de < 60: _m += 5
                            # Valuation proxy
                            _fv = _target if _target > 0 else (math.sqrt(22.5 * _eps * _bv) if _eps > 0 and _bv > 0 else 0)
                            _upside = round((_fv - price) / price * 100, 1) if _fv > 0 else 0
                            _vs = 50
                            if _upside > 30: _vs = 90
                            elif _upside > 15: _vs = 75
                            elif _upside > 5: _vs = 60
                            elif _upside < -10: _vs = 25
                            elif _upside < 0: _vs = 40
                            # Buffett proxy
                            _bs = 0
                            if _eps > 0: _bs += 15
                            if _f >= 7: _bs += 10
                            elif _f >= 5: _bs += 5
                            if _m >= 55: _bs += 10
                            elif _m >= 30: _bs += 5
                            if _de < 50: _bs += 10
                            if _rev_g > 5: _bs += 10
                            if _gm > 35: _bs += 10
                            if _npm > 10: _bs += 10
                            _bs = min(100, _bs)
                            _conf = round(_f / 9 * 30 + _m / 100 * 30 + _vs / 100 * 30 + (10 if _upside > 0 else 0), 0)
                            # Mini-Decision: Mirror the FULL investor_decide verdict logic
                            _overall = round(_f / 9 * 25 + _m / 100 * 25 + _vs / 100 * 25 + _bs / 100 * 15 + (_conf / 100 * 10), 0)
                            if _overall >= 72 and _upside > 8 and _f >= 6:
                                _mini_dec = "INVEST NOW"
                                _mini_color = "#10b981"
                            elif _overall >= 58 and _upside > 0:
                                _mini_dec = "START SIP"
                                _mini_color = "#3b82f6"
                            elif _f >= 6 and _upside <= 0:
                                _mini_dec = "GREAT COMPANY — OVERPRICED"
                                _mini_color = "#f59e0b"
                            elif _f <= 3:
                                _mini_dec = "AVOID — WEAK BUSINESS"
                                _mini_color = "#ef4444"
                            else:
                                _mini_dec = "HOLD / REVIEW"
                                _mini_color = "#f59e0b"
                            results.append({
                                "symbol": sym, "price": price, "name": info.get("shortName", sym),
                                "sector": info.get("sector", ""), "industry": info.get("industry", ""),
                                "pe": round(_pe, 1), "roe": round(_roe, 1), "margin": round(_npm, 1),
                                "gm": round(_gm, 1), "growth": round(_rev_g, 1), "de": round(_de, 1),
                                "mcap": _mcap, "divYield": round(_div_y, 2), "upside": round(_upside, 1),
                                "fScore": _f, "moatScore": _m, "valScore": _vs,
                                "buffettScore": _bs, "confidence": int(_conf),
                                "overall": int(_overall),
                                "miniDecision": _mini_dec, "miniColor": _mini_color,
                                "hi52": round(_hi52, 2), "lo52": round(_lo52, 2),
                                "pctFromLow": _pctFromLow, "pctFromHigh": _pctFromHigh,
                            })
                        except: pass
                except: pass
                return results
            batches = [universe[i:i+30] for i in range(0, len(universe), 30)]
            raw = await asyncio.gather(*[loop.run_in_executor(None, _batch_xm, b) for b in batches])
            all_stocks = [s for batch in raw for s in batch]
            _cross_cache[cache_key] = {"ts": time.time(), "data": all_stocks}
            print(f"   Fetched {len(all_stocks)}/{len(universe)} in {time.time()-t0:.1f}s")
        
        # 3. Score DECIDE ENGINE SIMILARITY + add explanation
        _sf = src["fScore"]; _sm = src["moatScore"]; _sv = src["valScore"]; _sb = src["buffettScore"]; _sc = src["confidence"]
        for s in all_stocks:
            sim = 0
            _parts = []
            _fd = abs(s["fScore"] - _sf)
            sim += max(0, 25 - _fd * 5)
            if _fd <= 1: _parts.append(f"F-Score {s['fScore']}/9 ≈ source")
            _md = abs(s["moatScore"] - _sm)
            sim += max(0, 20 - _md / max(_sm, 1) * 20)
            if _md <= 15: _parts.append(f"Moat {s['moatScore']} similar")
            sim += max(0, 15 - abs(s["valScore"] - _sv) / max(_sv, 1) * 15)
            sim += max(0, 15 - abs(s["buffettScore"] - _sb) / max(_sb, 1) * 15)
            sim += max(0, 15 - abs(s["confidence"] - _sc) / max(_sc, 1) * 15)
            _same_sec = src["sector"] and s["sector"] and src["sector"].lower() == s["sector"].lower()
            if _same_sec: sim += 10; _parts.append("Same sector")
            if s["gm"] > 30 and s["roe"] > 15: _parts.append(f"GM {s['gm']:.0f}% ROE {s['roe']:.0f}%")
            elif s["growth"] > 10: _parts.append(f"Growth {s['growth']:.0f}%")
            s["similarity"] = round(min(100, sim), 1)
            s["whySelected"] = " · ".join(_parts[:3]) if _parts else "Profile proximity"
            s["sameIndustry"] = bool(_same_sec)
            if target_region == "IN":
                _mc = s["mcap"] / 10000000
                s["capType"] = "Large Cap" if _mc >= 100000 else ("Mid Cap" if _mc >= 25000 else ("Small Cap" if _mc >= 5000 else "Micro Cap"))
            else:
                _mc = s["mcap"] / 1e9
                s["capType"] = "Large Cap" if _mc >= 200 else ("Mid Cap" if _mc >= 10 else ("Small Cap" if _mc >= 2 else "Micro Cap"))
        
        # QUALITY FLOOR — remove genuinely weak stocks (F<3 or no earnings)
        quality_stocks = [s for s in all_stocks if s["fScore"] >= 3 and (s["roe"] > 0 or s["margin"] > 0)]
        
        by_sim = sorted(quality_stocks, key=lambda x: x["similarity"], reverse=True)
        for i, s in enumerate(by_sim): s["rank"] = i + 1
        exact_match = by_sim[:10]
        same_ind = [s for s in by_sim if s["sameIndustry"]][:6]
        diff_ind = [s for s in by_sim if not s["sameIndustry"]][:6]
        large = sorted([s for s in quality_stocks if s["capType"]=="Large Cap"], key=lambda x: x["similarity"], reverse=True)[:3]
        mid = sorted([s for s in quality_stocks if s["capType"]=="Mid Cap"], key=lambda x: x["similarity"], reverse=True)[:3]
        small = sorted([s for s in quality_stocks if s["capType"]=="Small Cap"], key=lambda x: x["similarity"], reverse=True)[:3]
        micro = sorted([s for s in quality_stocks if s["capType"]=="Micro Cap"], key=lambda x: x["similarity"], reverse=True)[:3]
        below = sorted([s for s in quality_stocks if 0 < s["price"] < (50 if target_region=="IN" else 10)], key=lambda x: x["similarity"], reverse=True)[:3]
        niche = sorted([s for s in quality_stocks if s["capType"] in ["Small Cap","Micro Cap"] and s["growth"]>5 and s["similarity"]>30], key=lambda x: x["similarity"]+x["growth"]*0.3, reverse=True)[:3]
        
        # NEAR 52-WEEK LOW — Quality stocks beaten down (potential deep value)
        near_52low = sorted([s for s in quality_stocks if s.get("pctFromLow", 999) < 25 and s["fScore"] >= 4 and s["upside"] > 0], key=lambda x: x.get("pctFromLow", 999))[:8]
        
        # INVEST NOW — Only stocks whose Mini-Decide says INVEST NOW (consistent with full engine)
        invest_now = sorted([s for s in quality_stocks if s.get("miniDecision") == "INVEST NOW"], key=lambda x: x.get("overall", 0) + x["upside"] * 0.5, reverse=True)[:6]
        
        elapsed = round(time.time() - t0, 1)
        _top = by_sim[0] if by_sim else {}
        print(f"\U0001f310 Done: #1={_top.get('symbol','?')} (F{_top.get('fScore',0)} Moat{_top.get('moatScore',0)} {_top.get('similarity',0):.0f}%) in {elapsed}s")
        return {
            "success": True, "source": symbol, "sourceRegion": region, "targetRegion": target_region,
            "csym": csym_target, "mode": mode,
            "sourceProfile": src,
            "exactMatch": exact_match, "sameIndustry": same_ind, "diffIndustry": diff_ind,
            "largeCap": large, "midCap": mid, "smallCap": small, "microCap": micro,
            "belowThreshold": below, "thresholdLabel": "Below \u20b950" if target_region=="IN" else "Below $10",
            "niche": niche, "investNow": invest_now, "near52Low": near_52low, "totalScanned": len(all_stocks), "elapsed": elapsed,
        }
    except Exception as e:
        import traceback; traceback.print_exc()
        return {"success": False, "error": str(e)[:200]}

_decide_cache = {}  # {key: {"ts": time, "data": result}}

@app.get("/api/decide-index-trades")
async def decide_index_trades(region: str = "IN", extra: str = ""):
    """FAST index scan with per-stock timeout — never hangs"""
    try:
        is_us = region.upper() == "US"
        csym = "$" if is_us else "₹"
        indices_in = ["NIFTY", "BANKNIFTY", "SENSEX", "NIFTYIT", "FINNIFTY"]
        indices_us = ["SPY", "QQQ", "IWM", "DIA", "VTI"]
        targets = indices_us if is_us else indices_in
        # Add user's stock if provided
        if extra and extra.upper() not in targets:
            targets = [extra.upper()] + targets
            print(f"  📌 User stock added: {extra.upper()}")
        t0 = time.time()
        print(f"\n🏛️ Fast index scan: {len(targets)} indices, 15s timeout each")
        
        async def _scan_with_timeout(sym, timeout=15):
            """Run decision_engine with strict timeout — return None if too slow"""
            try:
                d = await asyncio.wait_for(decision_engine(sym, region), timeout=timeout)
                if not d.get("success"): return None
                ms = d.get("marketState", {}); tp = d.get("tradePath", {})
                vol = d.get("volatility", {}); conf = d.get("confidence", {})
                strat = d.get("strategy", {}); lt = d.get("liveTag", {})
                pos = d.get("positioning", {}); z = d.get("zones", {})
                ts = d.get("tradeSpec", {}); oic = d.get("oiChange", {})
                entry = tp.get("entry", [0, 0])
                entry_v = entry[0] if isinstance(entry, list) else entry
                elapsed = time.time() - t0
                print(f"  ✅ {sym} done in {elapsed:.1f}s — {d.get('signal','?')} conf={conf.get('score',0)}")
                return {
                    "symbol": sym, "price": d.get("price", 0),
                    "signal": d.get("signal", "HOLD"), "direction": ms.get("direction", ""),
                    "state": ms.get("state", ""), "strength": ms.get("strength", ""),
                    "adx": ms.get("adx", 0), "regimeScore": ms.get("regimeScore", 0),
                    "strategy": strat.get("name", ""), "strategyReason": strat.get("reason", ""),
                    "entry": entry_v, "sl": tp.get("sl", 0),
                    "t1": tp.get("t1", 0), "t2": tp.get("t2", 0), "rr": tp.get("rr", 0),
                    "slMethod": tp.get("slMethod", ""), "targetMethod": tp.get("targetMethod", ""),
                    "ivRank": vol.get("ivRank", 0), "iv": vol.get("iv", 0), "hv": vol.get("hv", 0),
                    "ivHvRatio": vol.get("ivHvRatio", 0), "ivPremium": vol.get("ivPremium", ""),
                    "volAction": vol.get("action", ""),
                    "confidence": conf.get("score", 0), "grade": conf.get("grade", ""),
                    "liveTag": lt.get("tag", ""), "tagColor": lt.get("color", ""),
                    "pcr": pos.get("pcr", 0), "pcrRegime": pos.get("pcrRegime", ""),
                    "maxPain": pos.get("maxPain", 0), "oiBias": pos.get("oiBias", ""),
                    "oiSupport": z.get("oiSupport", 0), "oiResistance": z.get("oiResistance", 0),
                    "expMove": z.get("expectedMove", []), "expMovePct": z.get("expMovePct", 0),
                    "compressed": z.get("compressed", False),
                    "support": z.get("support", []), "resistance": z.get("resistance", []),
                    "breakout": d.get("triggers", {}).get("breakout", 0),
                    "breakdown": d.get("triggers", {}).get("breakdown", 0),
                    "vix": d.get("vix", 0), "atr": d.get("atr", 0),
                    "tradeSpec": ts, "oiChange": oic,
                    "events": (d.get("events") or [])[:3],
                    "ivTermStructure": (d.get("ivTermStructure") or [])[:4],
                    "coaching": d.get("explanation", {}),
                }
            except asyncio.TimeoutError:
                print(f"  ⏰ {sym} TIMED OUT after {timeout}s — skipping")
                return None
            except Exception as e:
                print(f"  ❌ {sym}: {e}")
                return None
        
        # Run ALL indices concurrently with individual timeouts
        raw = await asyncio.gather(*[_scan_with_timeout(sym, timeout=15) for sym in targets])
        results = [r for r in raw if r is not None]
        results.sort(key=lambda x: x["confidence"], reverse=True)
        elapsed = time.time() - t0
        print(f"🏛️ Index scan done: {len(results)}/{len(targets)} in {elapsed:.1f}s")
        
        return {
            "success": True, "region": region, "csym": csym,
            "indices": results, "count": len(results),
            "elapsed": round(elapsed, 1),
            "timestamp": datetime.utcnow().strftime("%H:%M UTC"),
        }
    except Exception as e:
        import traceback; traceback.print_exc()
        return {"success": False, "error": str(e)[:200]}

@app.get("/api/decide-top-trades")
async def decide_top_trades(region: str = "IN", force: str = ""):
    """CONCURRENT scan — ALL stocks through REAL trader decision engine"""
    ck = f"trades_{region}"
    # Shorter cache during market hours (2 min), longer after (10 min)
    from datetime import timedelta
    _ist = datetime.utcnow() + timedelta(hours=5, minutes=30)
    _is_mkt = 9.15 <= (_ist.hour + _ist.minute/60) <= 15.5 and _ist.weekday() < 5
    _cache_ttl = 120 if _is_mkt else 600  # 2 min live, 10 min after
    if force != "1" and ck in _decide_cache and time.time() - _decide_cache[ck]["ts"] < _cache_ttl:
        _age = int(time.time() - _decide_cache[ck]["ts"])
        _data = _decide_cache[ck]["data"]
        _data["fromCache"] = True
        _data["cacheAge"] = _age
        return _data
    try:
        is_us = region.upper() == "US"
        csym = "$" if is_us else "₹"
        
        all_india = [
            "NIFTY","BANKNIFTY","SENSEX",
            "RELIANCE","TCS","HDFCBANK","INFY","ICICIBANK","BHARTIARTL","ITC","LT","SBIN","AXISBANK",
            "KOTAKBANK","BAJFINANCE","MARUTI","TATAMOTORS","SUNPHARMA","HCLTECH","WIPRO","NTPC","POWERGRID","ONGC",
            "ADANIENT","TITAN","NESTLEIND","ULTRACEMCO","JSWSTEEL","M&M","TATASTEEL","BAJAJ-AUTO","HDFCLIFE","DIVISLAB",
            "DRREDDY","CIPLA","COALINDIA","VEDL","GAIL","TRENT","ZOMATO","POLYCAB","PERSISTENT","HAL",
            "BEL","DLF","SIEMENS","ABB","DIXON","IREDA","IRFC","SUZLON","NHPC","TATAPOWER",
            "ADANIPORTS","HINDALCO","BPCL","TECHM","HINDUNILVR","ASIANPAINT","GRASIM","BAJAJFINSV","INDUSINDBK",
        ]
        all_us = [
            "SPY","QQQ","IWM",
            "AAPL","MSFT","NVDA","TSLA","AMZN","GOOGL","META","AMD","JPM","AVGO","NFLX","CRM",
            "ORCL","INTC","BA","DIS","V","MA","WMT","COST","HD","PG","KO","PEP","MRK","LLY",
            "UNH","JNJ","ABBV","PLTR","CRWD","DDOG","SNOW","NET","UBER","SQ","PYPL","COIN",
            "SOFI","RIVN","NIO","BABA","TSM","ASML","ARM","XOM","CVX","NKE","SBUX","ABNB",
            "NOW","PANW","GS","BAC","WFC","MS","BRK-B","MCD",
        ]
        targets = all_us if is_us else all_india
        t0 = time.time()
        print(f"\n🔥 CONCURRENT trader scan: {len(targets)} {region} instruments")
        
        # ═══ CONCURRENT EXECUTION — 8 parallel workers ═══
        sem = asyncio.Semaphore(8)
        
        async def _scan_one(sym):
            async with sem:
                try:
                    d = await asyncio.wait_for(decision_engine(sym, region), timeout=20)
                    if not d.get("success"): return None
                    ms = d.get("marketState", {}); tp = d.get("tradePath", {})
                    vol = d.get("volatility", {}); conf = d.get("confidence", {})
                    strat = d.get("strategy", {}); lt = d.get("liveTag", {})
                    pos = d.get("positioning", {})
                    entry = tp.get("entry", [0, 0])
                    entry_v = entry[0] if isinstance(entry, list) else entry
                    return {
                        "symbol": sym, "price": d.get("price", 0),
                        "signal": d.get("signal", "HOLD"), "direction": ms.get("direction", ""),
                        "state": ms.get("state", ""), "strength": ms.get("strength", ""),
                        "adx": ms.get("adx", 0),
                        "strategy": strat.get("name", "WAIT"), "strategyReason": strat.get("reason", ""),
                        "entry": entry_v, "sl": tp.get("sl", 0),
                        "t1": tp.get("t1", 0), "t2": tp.get("t2", 0), "rr": tp.get("rr", 0),
                        "ivRank": vol.get("ivRank", 0), "ivPremium": vol.get("ivPremium", ""),
                        "iv": vol.get("iv", 0), "hv": vol.get("hv", 0),
                        "confidence": conf.get("score", 0), "grade": conf.get("grade", ""),
                        "liveTag": lt.get("tag", ""), "tagColor": lt.get("color", ""),
                        "pcr": pos.get("pcr", 0), "vix": d.get("vix", 0),
                        "expMovePct": d.get("zones", {}).get("expMovePct", 0),
                        # Elite engine data
                        "tradeVerdict": d.get("tradeVerdict", {}).get("verdict", ""),
                        "tradeType": d.get("tradeVerdict", {}).get("tradeType", ""),
                        "tvScore": d.get("tradeVerdict", {}).get("score", 0),
                        "tvGrade": d.get("tradeVerdict", {}).get("grade", ""),
                        "tvAction": d.get("tradeVerdict", {}).get("action", ""),
                        "tvColor": d.get("tradeVerdict", {}).get("color", ""),
                        "probability": d.get("tradeVerdict", {}).get("probability", 50),
                        "supertrend": (d.get("engines", {}) or {}).get("supertrend", {}).get("signal", ""),
                        "mtfAlignment": (d.get("engines", {}) or {}).get("mtf", {}).get("alignment", ""),
                    }
                except asyncio.TimeoutError:
                    print(f"  ⏰ {sym} timeout — skipped")
                    return None
                except Exception as e:
                    print(f"  ❌ {sym}: {e}")
                    return None
        
        # Fire ALL concurrently
        raw = await asyncio.gather(*[_scan_one(sym) for sym in targets])
        results = [r for r in raw if r is not None]
        errors = len(targets) - len(results)
        elapsed = time.time() - t0
        print(f"🔥 Trader scan done: {len(results)}/{len(targets)} in {elapsed:.1f}s ({elapsed/max(len(results),1):.1f}s/stock)")
        
        results.sort(key=lambda x: x["confidence"], reverse=True)
        gut_picks = sorted(
            [r for r in results if r["confidence"] >= 60 and r["adx"] > 20 and r["rr"] >= 1.8],
            key=lambda x: x["confidence"] * x.get("rr", 1), reverse=True)[:7]
        bullish = sorted([r for r in results if r["direction"] == "BULLISH" and r["confidence"] >= 50], key=lambda x: x["confidence"], reverse=True)[:10]
        bearish = sorted([r for r in results if r["direction"] == "BEARISH" and r["confidence"] >= 50], key=lambda x: x["confidence"], reverse=True)[:10]
        best_rr = sorted([r for r in results if r["rr"] >= 2.0 and r["confidence"] >= 45], key=lambda x: x["rr"], reverse=True)[:10]
        iv_cheap = sorted([r for r in results if 0 < r["ivRank"] < 30 and r["confidence"] >= 40], key=lambda x: x["ivRank"])[:7]
        iv_rich = sorted([r for r in results if r["ivRank"] > 65], key=lambda x: x["ivRank"], reverse=True)[:7]
        
        _result = {
            "success": True, "region": region, "csym": csym,
            "totalScanned": len(targets), "totalAnalyzed": len(results), "errors": errors,
            "elapsed": round(elapsed, 1),
            "topTrades": results[:15], "gutPicks": gut_picks,
            "bullish": bullish, "bearish": bearish, "bestRR": best_rr,
            "ivCheap": iv_cheap, "ivRich": iv_rich,
            "timestamp": datetime.utcnow().strftime("%H:%M UTC"),
            "fromCache": False, "cacheAge": 0,
            "count": len(results),
        }
        _decide_cache[ck] = {"ts": time.time(), "data": _result}
        return _result
    except Exception as e:
        import traceback; traceback.print_exc()
        return {"success": False, "error": str(e)[:200]}

