            "UPL","COROMANDEL","GNFC",
            "MAZAGON","COCHINSHIP","GRSE","BDL","BEML","TITAGARH","RVNL","RAILTEL","RITES","IRCON","NCC","KEC",
            "KALPATPOWR","JKCEMENT","RAMCOCEM","BIKAJI","VARUN","HONASA",
            "REDINGTON","ELECON","TIMKEN","CGPOWER","APAR","INOXWIND","VGUARD",
            "BLUESTARCO","AMBER","GRINDWELL","SCHAEFFLER","SKF",
            "ESCORTS","RAYMOND","PRAJ",
            "PFIZER","GLAND","NATCOPHARM","AJANTPHARM","ALKEM","TORNTPOWER","JSWENERGY","SJVN",
            "HUDCO","HDFCAMC","UTIAMC","NIPPONLIFE","MAZDOCK",
