@app.get("/api/cds-batch")
async def cds_batch(symbols: str = "", region: str = "US", segment: str = "LARGE"):
    """Batch CDS scan — downloads all stocks in ONE yfinance call, computes CDS scores server-side.
    symbols: comma-separated list e.g. AAPL,MSFT,NVDA
    """
    import pandas as pd
    import numpy as np
    import time as _t
    t0 = _t.time()
    
    try:
        sym_list = [s.strip() for s in symbols.split(",") if s.strip()]
        if not sym_list:
            return {"success": False, "error": "No symbols provided"}
        
        is_us = region.upper() == "US"
        csym = "$" if is_us else "₹"
        
        # Add .NS for India
        yf_syms = sym_list if is_us else [s+".NS" if not s.endswith(".NS") else s for s in sym_list]
        
        print(f"⚡ CDS Batch: {len(yf_syms)} stocks | {region} | {segment}")
        
        # ═══ SINGLE BATCH DOWNLOAD ═══
        loop = asyncio.get_event_loop()
        def _dl():
            try:
                return yf.download(yf_syms, period="1y", group_by="ticker", progress=False, threads=True)
            except:
                return pd.DataFrame()
        hist = await loop.run_in_executor(None, _dl)
        
        if hist.empty:
            return {"success": False, "error": "Failed to download market data"}
        
        # ═══ BATCH FUNDAMENTALS — one Ticker call per stock but parallelized ═══
        def _get_info(sym):
            try:
                t = yf.Ticker(sym)
                info = t.info or {}
                return sym, info
            except:
                return sym, {}
        
        import concurrent.futures
        fund_data = {}
        with concurrent.futures.ThreadPoolExecutor(max_workers=10) as executor:
            futures = {executor.submit(_get_info, s): s for s in yf_syms}
            for f in concurrent.futures.as_completed(futures):
                sym, info = f.result()
                fund_data[sym] = info
        
        # ═══ SCORE EACH STOCK ═══
        results = []
        for sym in yf_syms:
            try:
                if len(yf_syms) == 1:
                    closes = hist["Close"].dropna()
                    volumes = hist["Volume"].dropna()
                elif sym in hist.columns.get_level_values(0):
                    closes = hist[sym]["Close"].dropna()
                    volumes = hist[sym]["Volume"].dropna()
                else:
                    continue
                
                if len(closes) < 30: continue
                price = float(closes.iloc[-1])
                if price <= 0: continue
                
                info = fund_data.get(sym, {})
                
                # ── PRICE ACTION METRICS ──
                sma50 = float(closes.iloc[-50:].mean()) if len(closes) >= 50 else float(closes.mean())
                sma200 = float(closes.iloc[-200:].mean()) if len(closes) >= 200 else float(closes.mean())
                
                delta = closes.diff()
                gain = delta.where(delta > 0, 0).rolling(14).mean()
                loss = (-delta.where(delta < 0, 0)).rolling(14).mean()
                rs = gain.iloc[-1] / loss.iloc[-1] if loss.iloc[-1] > 0 else 100
                rsi = float(100 - (100 / (1 + rs)))
                
                daily_ret = closes.pct_change().dropna()
                volatility = float(daily_ret.std() * np.sqrt(252) * 100)
                beta_proxy = volatility / 16  # Rough beta estimate from vol
                
                avg_vol = float(volumes.iloc[-20:].mean()) if len(volumes) >= 20 else 0
                vol_trend = float(volumes.iloc[-5:].mean() / max(volumes.iloc[-20:].mean(), 1)) if len(volumes) >= 20 else 1
                
                hi52 = float(closes.max())
                lo52 = float(closes.min())
                
                ret_1m = float((closes.iloc[-1] / closes.iloc[-22] - 1) * 100) if len(closes) >= 22 else 0
                ret_3m = float((closes.iloc[-1] / closes.iloc[-66] - 1) * 100) if len(closes) >= 66 else 0
                ret_1y = float((closes.iloc[-1] / closes.iloc[0] - 1) * 100)
                
                # ── FUNDAMENTAL METRICS ──
                pe = float(info.get("trailingPE", 0) or info.get("forwardPE", 0) or 0)
                pb = float(info.get("priceToBook", 0) or 0)
                roe = float(info.get("returnOnEquity", 0) or 0) * 100 if info.get("returnOnEquity") and abs(info.get("returnOnEquity", 0)) < 5 else float(info.get("returnOnEquity", 0) or 0)
                de = float(info.get("debtToEquity", 0) or 0)
                gm = float(info.get("grossMargins", 0) or 0) * 100 if info.get("grossMargins") and abs(info.get("grossMargins", 0)) < 5 else 0
                npm = float(info.get("profitMargins", 0) or 0) * 100 if info.get("profitMargins") and abs(info.get("profitMargins", 0)) < 5 else 0
                rev_g = float(info.get("revenueGrowth", 0) or 0) * 100 if info.get("revenueGrowth") and abs(info.get("revenueGrowth", 0)) < 5 else 0
                earn_g = float(info.get("earningsGrowth", 0) or 0) * 100 if info.get("earningsGrowth") and abs(info.get("earningsGrowth", 0)) < 5 else 0
                div_y = float(info.get("dividendYield", 0) or 0) * 100 if info.get("dividendYield") else 0
                beta = float(info.get("beta", beta_proxy) or beta_proxy)
                mc = float(info.get("marketCap", 0) or 0)
                name = info.get("shortName", "") or info.get("longName", sym)
                sector = info.get("sector", "")
                
                # ── PIOTROSKI F-SCORE (simplified) ──
                f_score = 0
                if npm > 0: f_score += 1  # Positive net income
                if roe > 0: f_score += 1  # Positive ROA proxy
                if rev_g > 0: f_score += 1  # Revenue growing
                if earn_g > 0: f_score += 1  # Earnings growing
                if gm > 30: f_score += 1  # Good margins
                if de < 100: f_score += 1  # Manageable debt
                if npm > 5: f_score += 1  # Quality earnings
                if ret_1y > 0: f_score += 1  # Positive returns
                if price > sma200: f_score += 1  # Above long-term trend
                
                # ── FAIR VALUE ESTIMATE ──
                eps = float(info.get("trailingEps", 0) or 0)
                fv_graham = (eps * (8.5 + 2 * max(0, min(rev_g, 20)))) if eps > 0 else 0
                fv_pe = eps * 15 if eps > 0 else 0
                fair_value = max(fv_graham, fv_pe) if eps > 0 else price
                upside = round((fair_value - price) / price * 100, 1) if price > 0 else 0
                
                # ── MOAT SCORE ──
                moat = 0
                if gm > 40: moat += 25
                elif gm > 25: moat += 15
                if roe > 20: moat += 25
                elif roe > 12: moat += 15
                if rev_g > 15: moat += 25
                elif rev_g > 5: moat += 15
                if de < 50: moat += 25
                elif de < 100: moat += 15
                
                # ── CDS 6-LAYER SCORING ──
                # L1: Liquidity
                l1 = min(100, int(min(avg_vol, 5000000) / 50000))
                if vol_trend > 1.3: l1 = min(100, l1 + 15)
                
                # L2: Flow (Smart Money proxy)
                l2 = 50  # Base
                if vol_trend > 1.5: l2 += 20
                elif vol_trend > 1.2: l2 += 10
                if price > sma50 and rsi > 50: l2 += 15
                elif price < sma50 and rsi < 40: l2 -= 15
                l2 = max(0, min(100, l2))
                
                # L3: Volatility/Risk
                l3 = max(0, min(100, int(100 - volatility * 1.5)))
                if beta > 1.8: l3 = max(0, l3 - 15)
                
                # L4: Fundamentals
                l4 = min(100, f_score * 11)
                if upside > 20: l4 = min(100, l4 + 15)
                elif upside < -20: l4 = max(0, l4 - 15)
                
                # L5: Quant/Factor
                l5 = 0
                if price > sma200: l5 += 25
                if price > sma50: l5 += 20
                if 40 < rsi < 70: l5 += 25
                if f_score >= 7: l5 += 15
                if beta < 1.5: l5 += 15
                l5 = min(100, l5)
                
                # L6: Probability
                mc_prob = 50
                if upside > 30 and f_score >= 6: mc_prob = 80
                elif upside > 10 and f_score >= 5: mc_prob = 65
                elif upside < -10: mc_prob = 30
                l6 = mc_prob
                
                # ── REGIME ──
                regime = "BULL" if price > sma200 and rsi > 50 else ("BEAR" if price < sma200 and rsi < 45 else "SIDEWAYS")
                
                # ── WEIGHTED CDS SCORE ──
                if regime == "BULL":
                    w = {"L1": 15, "L2": 20, "L3": 15, "L4": 22, "L5": 18, "L6": 10}
                elif regime == "BEAR":
                    w = {"L1": 25, "L2": 15, "L3": 25, "L4": 15, "L5": 10, "L6": 10}
                else:
                    w = {"L1": 20, "L2": 18, "L3": 20, "L4": 18, "L5": 14, "L6": 10}
                
                cds_score = round((l1 * w["L1"] + l2 * w["L2"] + l3 * w["L3"] + l4 * w["L4"] + l5 * w["L5"] + l6 * w["L6"]) / 100)
                
                # ── VERDICT ──
                if cds_score >= 75: verdict, vC = "STRONG BUY", "#059669"
                elif cds_score >= 60: verdict, vC = "BUY", "#1A3A78"
                elif cds_score >= 45: verdict, vC = "HOLD", "#d97706"
                elif cds_score >= 30: verdict, vC = "EXIT", "#dc2626"
                else: verdict, vC = "STRONG SELL", "#dc2626"
                
                # ── BUCKET ──
                if cds_score >= 70 and l1 >= 40 and l2 >= 30:
                    bucket, bIcon = "DEPLOY", "🟢"
                elif cds_score >= 55:
                    bucket, bIcon = "WATCH", "🟡"
                else:
                    bucket, bIcon = "AVOID", "🔴"
                
                # ── POSITION SIZE ──
                kelly = max(1, min(20, round(cds_score * 0.25)))
                
                clean = sym.replace(".NS", "")
                
                results.append({
                    "symbol": clean,
                    "name": name[:30] if name else clean,
                    "sector": sector,
                    "price": round(price, 2),
                    "cdsScore": cds_score,
                    "verdict": verdict,
                    "verdictColor": vC,
                    "bucket": bucket,
                    "bucketIcon": bIcon,
                    "fScore": f_score,
                    "moat": moat,
                    "pe": round(pe, 1),
                    "roe": round(roe, 1),
                    "beta": round(beta, 2),
                    "rsi": round(rsi, 1),
                    "upside": upside,
                    "fairValue": round(fair_value, 2),
                    "ret1m": round(ret_1m, 1),
                    "ret3m": round(ret_3m, 1),
                    "ret1y": round(ret_1y, 1),
                    "volatility": round(volatility, 1),
                    "avgVolume": round(avg_vol),
                    "regime": regime,
                    "segment": segment,
                    "layers": {"L1": l1, "L2": l2, "L3": l3, "L4": l4, "L5": l5, "L6": l6},
                    "weights": w,
                    "kelly": kelly,
                    "aboveSMA200": price > sma200,
                    "aboveSMA50": price > sma50,
                    "from52Hi": round(((price - hi52) / hi52) * 100, 1),
                    "marketCap": mc,
                    "divYield": round(div_y, 2),
                })
            except Exception as ex:
                continue
        
        results.sort(key=lambda x: x["cdsScore"], reverse=True)
        elapsed = round(_t.time() - t0, 1)
        
        deploy = [r for r in results if r["bucket"] == "DEPLOY"]
        watch = [r for r in results if r["bucket"] == "WATCH"]
        avoid = [r for r in results if r["bucket"] == "AVOID"]
        
        print(f"✅ CDS Batch: {len(results)} scored in {elapsed}s | Deploy:{len(deploy)} Watch:{len(watch)} Avoid:{len(avoid)}")
        
        return {
            "success": True,
            "region": region,
            "csym": csym,
            "segment": segment,
            "totalScanned": len(yf_syms),
            "totalScored": len(results),
            "elapsed": elapsed,
            "deployCount": len(deploy),
            "watchCount": len(watch),
            "avoidCount": len(avoid),
            "results": results,
        }
    except Exception as e:
        import traceback; traceback.print_exc()
        return {"success": False, "error": str(e)}


@app.get("/api/asset-intelligence")
async def asset_intelligence():
    """Global Asset Correlation & Impact Engine — how assets affect each other"""
    try:
        # yfinance imported globally with 401 wrapper
        import pandas as pd
        import numpy as np
        
        # ═══ GLOBAL ASSETS ═══
        assets = {
            "CL=F": {"name": "Crude Oil (WTI)", "emoji": "🛢️", "category": "Commodity", "unit": "$"},
            "BZ=F": {"name": "Brent Crude", "emoji": "🛢️", "category": "Commodity", "unit": "$"},
            "GC=F": {"name": "Gold", "emoji": "🥇", "category": "Commodity", "unit": "$"},
            "SI=F": {"name": "Silver", "emoji": "🥈", "category": "Commodity", "unit": "$"},
            "DX-Y.NYB": {"name": "US Dollar Index", "emoji": "💵", "category": "Currency", "unit": ""},
            "^TNX": {"name": "US 10Y Yield", "emoji": "📊", "category": "Bond", "unit": "%"},
            "^NSEI": {"name": "NIFTY 50", "emoji": "🇮🇳", "category": "Index", "unit": ""},
            "^NSEBANK": {"name": "Bank NIFTY", "emoji": "🏦", "category": "Index", "unit": ""},
            "^GSPC": {"name": "S&P 500", "emoji": "🇺🇸", "category": "Index", "unit": ""},
            "^IXIC": {"name": "NASDAQ", "emoji": "💻", "category": "Index", "unit": ""},
            "^VIX": {"name": "VIX (Fear)", "emoji": "😱", "category": "Volatility", "unit": ""},
            "USDINR=X": {"name": "USD/INR", "emoji": "💱", "category": "Currency", "unit": "₹"},
            "BTC-USD": {"name": "Bitcoin", "emoji": "₿", "category": "Crypto", "unit": "$"},
        }
        
        tickers = list(assets.keys())
        
        # Batch download
        hist = yf.download(tickers, period="1y", group_by="ticker", progress=False, threads=True)
        
        if hist.empty:
            return {"success": False, "error": "Could not download asset data"}
        
        # Extract closes for each asset
        asset_data = {}
        for ticker in tickers:
            try:
                if len(tickers) > 1 and ticker in hist.columns.get_level_values(0):
                    closes = hist[ticker]["Close"].dropna()
                else:
                    continue
                if len(closes) < 20: continue
                
                vals = closes.values.astype(float)
                price = round(float(vals[-1]), 2)
                
                # Returns across timeframes
                def _ret(n):
                    if len(vals) >= n+1:
                        return round(((vals[-1] / vals[-min(n, len(vals)-1)]) - 1) * 100, 2)
                    return 0
                
                asset_data[ticker] = {
                    **assets[ticker],
                    "ticker": ticker, "price": price, "closes": vals,
                    "ret1d": _ret(1), "ret1w": _ret(5), "ret15d": _ret(11),
                    "ret1m": _ret(22), "ret3m": _ret(63), "ret6m": _ret(126), "ret1y": _ret(252),
                }
            except:
                continue
        
        # ═══ CORRELATION MATRIX ═══
        # Build DataFrame of returns
        returns_df = pd.DataFrame()
        asset_names = {}
        for ticker, ad in asset_data.items():
            if len(ad["closes"]) >= 60:
                returns_df[ticker] = pd.Series(ad["closes"]).pct_change().dropna().values[-60:]
                asset_names[ticker] = ad["name"]
        
        corr_matrix = {}
        if len(returns_df.columns) >= 2:
            corr = returns_df.corr()
            for t1 in corr.columns:
                corr_matrix[t1] = {}
                for t2 in corr.columns:
                    corr_matrix[t1][t2] = round(float(corr.loc[t1, t2]), 2)
        
        # ═══ IMPACT ANALYSIS — What's driving what TODAY ═══
        impacts = []
        
        # Crude Oil impact chain
        oil = asset_data.get("CL=F", {})
        brent = asset_data.get("BZ=F", {})
        gold = asset_data.get("GC=F", {})
        dxy = asset_data.get("DX-Y.NYB", {})
        nifty = asset_data.get("^NSEI", {})
        bnifty = asset_data.get("^NSEBANK", {})
        sp500 = asset_data.get("^GSPC", {})
        vix = asset_data.get("^VIX", {})
        usdinr = asset_data.get("USDINR=X", {})
        yields_10y = asset_data.get("^TNX", {})
        btc = asset_data.get("BTC-USD", {})
        
        if oil.get("ret1w", 0) > 3:
            impacts.append({"from": "🛢️ Crude Oil", "to": "🇮🇳 NIFTY / 🏦 Banks", "type": "NEGATIVE",
                "reason": f"Crude up {oil['ret1w']:.1f}% this week → import bill rises → INR weakens → inflation fear → RBI may stay hawkish → banks & market under pressure",
                "severity": "HIGH" if oil["ret1w"] > 5 else "MEDIUM"})
            impacts.append({"from": "🛢️ Crude Oil", "to": "⛽ Oil Marketing (BPCL, IOC)", "type": "NEGATIVE",
                "reason": "Higher crude = squeezed margins for OMCs unless they raise fuel prices", "severity": "MEDIUM"})
            impacts.append({"from": "🛢️ Crude Oil", "to": "💱 USD/INR", "type": "NEGATIVE",
                "reason": "India imports 85% of its oil → higher crude = more dollar outflow → INR depreciates", "severity": "HIGH"})
        elif oil.get("ret1w", 0) < -3:
            impacts.append({"from": "🛢️ Crude Oil", "to": "🇮🇳 NIFTY / Economy", "type": "POSITIVE",
                "reason": f"Crude down {oil['ret1w']:.1f}% → lower import bill → INR stabilizes → inflation eases → bullish for India",
                "severity": "HIGH" if oil["ret1w"] < -5 else "MEDIUM"})
        
        if dxy.get("ret1w", 0) > 1:
            impacts.append({"from": "💵 Dollar Index", "to": "🥇 Gold / 🇮🇳 NIFTY", "type": "NEGATIVE",
                "reason": f"Dollar strengthening ({dxy['ret1w']:.1f}% this week) → gold falls (inverse) → FII sell emerging markets → pressure on NIFTY",
                "severity": "HIGH" if dxy["ret1w"] > 2 else "MEDIUM"})
            impacts.append({"from": "💵 Dollar Index", "to": "💱 USD/INR", "type": "NEGATIVE",
                "reason": "Strong dollar → INR weakens → imported inflation rises", "severity": "MEDIUM"})
        elif dxy.get("ret1w", 0) < -1:
            impacts.append({"from": "💵 Dollar Index", "to": "🇮🇳 Emerging Markets", "type": "POSITIVE",
                "reason": f"Dollar weakening ({dxy['ret1w']:.1f}%) → FII money flows into India → bullish for NIFTY & midcaps",
                "severity": "HIGH"})
        
        if gold.get("ret1w", 0) > 2:
            impacts.append({"from": "🥇 Gold", "to": "📊 Risk Sentiment", "type": "WARNING",
                "reason": f"Gold surging {gold['ret1w']:.1f}% → investors seeking safety → risk-off mode → equity may face selling",
                "severity": "MEDIUM"})
        
        if vix.get("price", 0) > 25:
            impacts.append({"from": "😱 VIX (Fear Index)", "to": "📉 All Equities", "type": "NEGATIVE",
                "reason": f"VIX at {vix['price']:.1f} (elevated fear) → options expensive → big moves expected → hedge your positions",
                "severity": "HIGH" if vix["price"] > 30 else "MEDIUM"})
        elif vix.get("price", 0) < 15:
            impacts.append({"from": "😱 VIX (Fear Index)", "to": "📈 Equities", "type": "POSITIVE",
                "reason": f"VIX at {vix['price']:.1f} (very low fear) → calm markets → good for option sellers → steady uptrend likely",
                "severity": "LOW"})
        
        if yields_10y.get("ret1w", 0) > 3:
            impacts.append({"from": "📊 US 10Y Yield", "to": "💻 Tech / Growth Stocks", "type": "NEGATIVE",
                "reason": f"Bond yields jumping {yields_10y['ret1w']:.1f}% → higher discount rate → growth/tech stocks fall → NASDAQ pressure",
                "severity": "HIGH"})
        
        if btc.get("ret1w", 0) > 8:
            impacts.append({"from": "₿ Bitcoin", "to": "🎰 Risk Appetite", "type": "POSITIVE",
                "reason": f"Bitcoin rallying {btc['ret1w']:.1f}% → risk-on sentiment → generally positive for equities",
                "severity": "LOW"})
        elif btc.get("ret1w", 0) < -8:
            impacts.append({"from": "₿ Bitcoin", "to": "🎰 Risk Appetite", "type": "NEGATIVE",
                "reason": f"Bitcoin crashing {btc['ret1w']:.1f}% → risk-off → could spill into equity markets",
                "severity": "MEDIUM"})
        
        # NIFTY-specific
        if nifty.get("ret1w", 0) and sp500.get("ret1w", 0):
            if sp500["ret1w"] < -2 and nifty["ret1w"] > 0:
                impacts.append({"from": "🇺🇸 S&P 500", "to": "🇮🇳 NIFTY", "type": "WARNING",
                    "reason": f"US down {sp500['ret1w']:.1f}% but India up {nifty['ret1w']:.1f}% — decoupling may not last. Watch for catch-up selling.",
                    "severity": "MEDIUM"})
            elif sp500["ret1w"] > 2:
                impacts.append({"from": "🇺🇸 S&P 500", "to": "🇮🇳 NIFTY", "type": "POSITIVE",
                    "reason": f"US rallying {sp500['ret1w']:.1f}% → global risk-on → FII inflows → NIFTY support",
                    "severity": "MEDIUM"})
        
        # If no impacts found, add default
        if not impacts:
            impacts.append({"from": "🌍 Global Markets", "to": "All Assets", "type": "NEUTRAL",
                "reason": "No major cross-asset moves this week. Markets in equilibrium — good for range-bound strategies.",
                "severity": "LOW"})
        
        # ═══ HISTORICAL REGIME — classify each timeframe ═══
        def _regime(oil_r, gold_r, dxy_r, vix_p, nifty_r):
            if vix_p > 25 and nifty_r < -3: return {"regime": "RISK-OFF", "color": "#dc2626", "emoji": "🔴", "advice": "Reduce exposure. Hedge with puts. Cash is king."}
            if oil_r > 5 and dxy_r > 1: return {"regime": "INFLATION FEAR", "color": "#d97706", "emoji": "🟠", "advice": "Avoid rate-sensitive stocks. Favor commodities, energy, value."}
            if gold_r > 3 and dxy_r < -1: return {"regime": "SAFE HAVEN", "color": "#d97706", "emoji": "🟡", "advice": "Defensive mode — gold, FMCG, pharma outperform."}
            if nifty_r > 3 and vix_p < 18: return {"regime": "BULL RUN", "color": "#059669", "emoji": "🟢", "advice": "Buy dips. Stay long. Momentum strategies work."}
            return {"regime": "NEUTRAL", "color": "#6b7280", "emoji": "⚪", "advice": "Range-bound. Iron condors and strangles work best."}
        
        timeframes = {}
        for tf_key, tf_days in [("1W", 5), ("15D", 11), ("1M", 22), ("3M", 63), ("1Y", 252)]:
            tf_ret = lambda ad, n=tf_days: ad.get(f"ret{tf_key.lower().replace('d','d').replace('w','w').replace('m','m').replace('y','y')}", 0)
            oil_r = oil.get({5:"ret1w",11:"ret15d",22:"ret1m",63:"ret3m",252:"ret1y"}[tf_days], 0)
            gold_r = gold.get({5:"ret1w",11:"ret15d",22:"ret1m",63:"ret3m",252:"ret1y"}[tf_days], 0)
            dxy_r = dxy.get({5:"ret1w",11:"ret15d",22:"ret1m",63:"ret3m",252:"ret1y"}[tf_days], 0)
            nifty_r = nifty.get({5:"ret1w",11:"ret15d",22:"ret1m",63:"ret3m",252:"ret1y"}[tf_days], 0)
            vix_p = vix.get("price", 15)
            timeframes[tf_key] = _regime(oil_r, gold_r, dxy_r, vix_p, nifty_r)
        
        # Build asset table (without closes array)
        asset_table = []
        for ticker, ad in asset_data.items():
            asset_table.append({
                "ticker": ticker, "name": ad["name"], "emoji": ad["emoji"],
                "category": ad["category"], "unit": ad["unit"], "price": ad["price"],
                "ret1d": ad["ret1d"], "ret1w": ad["ret1w"], "ret15d": ad["ret15d"],
                "ret1m": ad["ret1m"], "ret3m": ad["ret3m"], "ret6m": ad["ret6m"], "ret1y": ad["ret1y"],
            })
        asset_table.sort(key=lambda x: x["ret1w"], reverse=True)
        
        # Top correlations
        top_corrs = []
        seen = set()
        for t1 in corr_matrix:
            for t2 in corr_matrix[t1]:
                if t1 == t2: continue
                pair = tuple(sorted([t1, t2]))
                if pair in seen: continue
                seen.add(pair)
                c = corr_matrix[t1][t2]
                if abs(c) > 0.4:
                    n1 = asset_names.get(t1, t1); n2 = asset_names.get(t2, t2)
                    top_corrs.append({"asset1": n1, "asset2": n2, "corr": c,
                        "type": "MOVES TOGETHER" if c > 0 else "MOVES OPPOSITE"})
        top_corrs.sort(key=lambda x: abs(x["corr"]), reverse=True)
        
        return {
            "success": True,
            "assets": asset_table,
            "impacts": impacts,
            "correlations": top_corrs[:15],
            "timeframes": timeframes,
            "timestamp": datetime.utcnow().isoformat(),
        }
    except Exception as e:
        import traceback; traceback.print_exc()
        return {"success": False, "error": str(e)}


@app.get("/api/payoff-curve")
async def payoff_curve(symbol: str, region: str = "IN"):
    """Generate P&L payoff curves for all strategies on a given stock"""
    try:
        algo = await algo_signal_safe(symbol, region)
        strats = algo.get("strategies", [])
        spot = algo.get("spot", 0)
        inst = algo.get("instrument", {"gap": 50, "lot": 50})
        gap = inst.get("gap", 50)
        lot = inst.get("lot", 50)
        csym = "$" if region.upper() == "US" else "₹"
        
        if not strats and spot == 0:
            return {"success": False, "error": "No strategies available"}
        
        if spot == 0:
            return {"success": False, "error": "Could not get spot price"}
        
        # Generate price range (±10% from spot)
        low = round(spot * 0.9, 0)
        high = round(spot * 1.1, 0)
        step = max(1, round((high - low) / 50))
        prices = [low + i * step for i in range(51)]
        
        # Helper to compute one curve
        def compute_curve(legs_data, name, strat_type, pop_val=50):
            data_points = []
            for p in prices:
                pnl = 0
                for leg in legs_data:
                    strike = leg.get("strike", 0)
                    prem = leg.get("premium", 0)
                    is_buy = leg.get("action") == "BUY"
                    is_ce = leg.get("type") in ["CE", "CALL"]
                    if is_ce:
                        intrinsic = max(0, p - strike)
                    else:
                        intrinsic = max(0, strike - p)
                    if is_buy:
                        pnl += (intrinsic - prem) * lot
                    else:
                        pnl += (prem - intrinsic) * lot
                data_points.append({"price": round(p, 0), "pnl": round(pnl, 0)})
            max_profit = max(dp["pnl"] for dp in data_points)
            max_loss = min(dp["pnl"] for dp in data_points)
            breakevens = []
            for i in range(1, len(data_points)):
                if (data_points[i-1]["pnl"] < 0 and data_points[i]["pnl"] >= 0) or \
                   (data_points[i-1]["pnl"] >= 0 and data_points[i]["pnl"] < 0):
                    breakevens.append(data_points[i]["price"])
            return {
                "name": name, "type": strat_type, "legs": legs_data,
                "dataPoints": data_points, "maxProfit": max_profit,
                "maxLoss": max_loss, "breakevens": breakevens, "pop": pop_val,
            }
        
        curves = []
        
        # Get ATM info for naked strategies
        _atm = algo.get("atm", round(spot / gap) * gap if gap > 0 else spot)
        is_us = region.upper() == "US"
        ce_type = "CALL" if is_us else "CE"
        pe_type = "PUT" if is_us else "PE"
        
        # Find ATM premiums from existing strategies or estimate
        ce_prem = 0; pe_prem = 0
        for s in strats:
            for leg in s.get("legs", []):
                if leg.get("strike") == _atm and leg.get("action") == "BUY":
                    if leg.get("type") in ["CE", "CALL"]: ce_prem = leg.get("premium", 0)
                    if leg.get("type") in ["PE", "PUT"]: pe_prem = leg.get("premium", 0)
        # Fallback: estimate from expected move
        if ce_prem == 0:
            em = algo.get("expectedMove", {})
            em_pts = em.get("em_pts", spot * 0.02)
            ce_prem = round(em_pts * 0.5, 2)
            pe_prem = round(em_pts * 0.5, 2)
        
        # 1. Naked Call Buy (ATM)
        if ce_prem > 0:
            curves.append(compute_curve(
                [{"action": "BUY", "strike": _atm, "type": ce_type, "premium": ce_prem}],
                "Buy Call (ATM)", "DIRECTIONAL — BULLISH", 45
            ))
        
        # 2. Naked Put Buy (ATM)
        if pe_prem > 0:
            curves.append(compute_curve(
                [{"action": "BUY", "strike": _atm, "type": pe_type, "premium": pe_prem}],
                "Buy Put (ATM)", "DIRECTIONAL — BEARISH", 45
            ))
        
        # 3-7. Existing multi-leg strategies
        for strat in strats:
            legs = strat.get("legs", [])
            if not legs: continue
            curves.append(compute_curve(
                legs, strat.get("name", ""), strat.get("type", ""), strat.get("pop", 50)
            ))
        
        return {"success": True, "symbol": symbol, "spot": spot, "csym": csym, "curves": curves}
    except Exception as e:
        return {"success": False, "error": str(e)}


@app.get("/api/journal-review")
async def journal_review():
    """Today's trade review with behavioral insights"""
    trades = _load_journal()
    today = datetime.utcnow().strftime("%Y-%m-%d")
    
    today_trades = [t for t in trades if t.get("timestamp", "").startswith(today)]
    all_closed = [t for t in trades if t.get("status") == "CLOSED"]
    
    # Behavioral analysis
    behaviors = []
    if len(all_closed) >= 3:
        # Early exits
        early_exits = 0
        for t in all_closed[-10:]:
            entry = t.get("entryPrem", 0)
            exit_p = t.get("exitPrem", 0)
            if exit_p > 0 and exit_p > entry:
                gain_pct = (exit_p - entry) / entry * 100 if entry > 0 else 0
                if gain_pct < 10 and gain_pct > 0:
                    early_exits += 1
        if early_exits >= 2:
            behaviors.append({"type": "WARNING", "habit": "Early Profit Booking", 
                "msg": f"You booked profits too early on {early_exits} of last 10 trades (<10% gain). Let winners run — set trailing SL instead.",
                "fix": "Try booking 50% at T1, trail rest with 15-min candle SL"})
        
        # Revenge trading
        consecutive_losses = 0
        for t in reversed(all_closed[-10:]):
            if t.get("pnl", 0) < 0:
                consecutive_losses += 1
            else:
                break
        if consecutive_losses >= 3:
            behaviors.append({"type": "CRITICAL", "habit": "Revenge Trading Risk",
                "msg": f"{consecutive_losses} consecutive losses. STOP trading today. Your judgment is clouded.",
                "fix": "Take a 24-hour break. Review what went wrong before next trade."})
        
        # Overtrading
        recent_dates = set()
        for t in all_closed[-20:]:
            d = t.get("timestamp", "")[:10]
            recent_dates.add(d)
        avg_per_day = len(all_closed[-20:]) / max(len(recent_dates), 1)
        if avg_per_day > 5:
            behaviors.append({"type": "WARNING", "habit": "Overtrading",
                "msg": f"Averaging {avg_per_day:.0f} trades/day. Quality > quantity.",
                "fix": "Limit to 3 high-conviction trades per day. Wait for A+ setups."})
        
        # Win/loss asymmetry
        wins = [t for t in all_closed if t.get("pnl", 0) > 0]
        losses = [t for t in all_closed if t.get("pnl", 0) < 0]
        if wins and losses:
            avg_win = sum(t["pnl"] for t in wins) / len(wins)
            avg_loss = abs(sum(t["pnl"] for t in losses) / len(losses))
            if avg_loss > avg_win * 1.5:
                behaviors.append({"type": "CRITICAL", "habit": "Letting Losses Run",
                    "msg": f"Average loss (₹{avg_loss:,.0f}) is {avg_loss/max(avg_win,1):.1f}x your average win (₹{avg_win:,.0f}). You hold losers too long.",
                    "fix": "Strict SL — exit the MOMENT SL hits. No hoping, no averaging down."})
    
    # Today's summary
    today_pnl = sum(t.get("pnl", 0) for t in today_trades if t.get("status") == "CLOSED")
    today_wins = len([t for t in today_trades if t.get("pnl", 0) > 0 and t.get("status") == "CLOSED"])
    today_losses = len([t for t in today_trades if t.get("pnl", 0) < 0 and t.get("status") == "CLOSED"])
    today_open = len([t for t in today_trades if t.get("status") == "OPEN"])
    
    # Streak
    streak = 0; streak_type = "NONE"
    for t in reversed(all_closed):
        if t.get("pnl", 0) > 0:
            if streak_type == "WIN" or streak_type == "NONE": streak += 1; streak_type = "WIN"
            else: break
        elif t.get("pnl", 0) < 0:
            if streak_type == "LOSS" or streak_type == "NONE": streak += 1; streak_type = "LOSS"
            else: break
    
    return {
        "success": True,
        "today": {
            "trades": len(today_trades), "wins": today_wins, "losses": today_losses,
            "open": today_open, "pnl": round(today_pnl, 0),
        },
        "streak": {"count": streak, "type": streak_type},
        "behaviors": behaviors,
        "totalClosed": len(all_closed),
    }


@app.post("/api/ai-assist")
async def ai_assist(request: Request):
    """AI assistant that answers trading questions using live data."""
    data = await request.json()
    question = (data.get("question", "")).strip().lower()
    symbol = data.get("symbol", "NIFTY")
    
    if not question:
        return {"success": False, "error": "No question provided"}
    
    # Get fresh algo data
    try:
        algo = await algo_signal_safe(symbol, data.get("region", "IN"))
    except:
        algo = {}
    
    tr = algo.get("trade", {})
    tc = algo.get("tradeConfidence", {})
    oi = algo.get("options_intel", {})
    vi = algo.get("volIntelligence", {})
    strats = algo.get("strategies", [])
    sc = algo.get("scalp", {})
    sig = algo.get("signal", "HOLD / WAIT")
    direction = algo.get("direction", "NEUTRAL")
    is_us = algo.get("region") == "US"
    csym = "$" if is_us else "₹"
    price = algo.get("spot", 0)
    inst = algo.get("instrument", {"gap": 50, "lot": 50})
    nse = algo.get("options", {})
    bs_data = algo.get("black_scholes", {})
    
    answer = ""
    
    # Pattern matching for common questions
    # CALL/CE BUY — Full trade details
    if any(w in question for w in ["call buy", "ce buy", "call trade", "ce trade", "bullish trade"]):
        win = tc.get("estimatedWin", 50)
        grade = tc.get("grade", "B")
        # Build CE/CALL trade regardless of algo direction
        ce_type = "CALL" if is_us else "CE"
        atm = round(price / inst.get("gap", 50)) * inst.get("gap", 50)
        ce_prem = 0
        try:
            from math import log, sqrt, exp, erf
            _iv = (nse.get("atm_iv", 20) or 20) / 100
            _T = max(bs_data.get("dte", 7), 1) / 365 if bs_data else 7/365
            _r = 0.0525 if is_us else 0.065
            d1 = (log(price/atm) + (_r + _iv**2/2)*_T) / (_iv*sqrt(_T)) if _iv > 0 and _T > 0 else 0
            d2 = d1 - _iv*sqrt(_T) if _iv > 0 and _T > 0 else 0
            nd1 = 0.5*(1+erf(d1/sqrt(2))); nd2 = 0.5*(1+erf(d2/sqrt(2)))
            ce_prem = round(max(price*nd1 - atm*exp(-_r*_T)*nd2, 0), 1)
        except: ce_prem = round(price * 0.015, 1)
        
        atr_val = algo.get("technicals", {}).get("atr14", price * 0.015)
        ce_sl_spot = round(price - atr_val * 1.5, 2)
        ce_t1_spot = round(price + atr_val * 1.0, 2)
        ce_t2_spot = round(price + atr_val * 2.0, 2)
        
        oi_data = algo.get("options_intel", {})
        answer = f"""📈 {ce_type} BUY TRADE — {symbol}

🎯 TRADE SETUP:
• Action: BUY {atm} {ce_type}
• Entry Premium: ~{csym}{ce_prem}
• Spot Price: {csym}{price:,.2f}

📊 LEVELS (on underlying):
• Entry Zone: {csym}{price:,.0f}
• Stop Loss: {csym}{ce_sl_spot:,.0f} (if breaks below this, exit)
• Target 1: {csym}{ce_t1_spot:,.0f} (book 50% here)
• Target 2: {csym}{ce_t2_spot:,.0f} (book remaining)

📋 TRADE RULES:
• When T1 is hit → move SL to entry (free trade!)
• Max risk: {csym}{ce_prem} per unit (you can never lose more)
• Exit by 3:00 PM if no target hit

📊 CONFIDENCE:
• Win Rate: {win}% (Grade {grade})
• Signal: {sig} | Direction: {direction}
• IV Rank: {oi_data.get('iv_rank', 50)}%

💡 IN SIMPLE WORDS:
We're betting {symbol} will go UP. Buy {ce_type} at {csym}{ce_prem}. 
If stock rises → your option becomes more valuable → profit!
If stock falls → exit at SL → lose only the premium paid.
Think of it as buying a lottery ticket where you know the odds."""
    
    # PUT/PE BUY — Full trade details
    elif any(w in question for w in ["put buy", "pe buy", "put trade", "pe trade", "bearish trade"]):
        win = tc.get("estimatedWin", 50)
        grade = tc.get("grade", "B")
        pe_type = "PUT" if is_us else "PE"
        atm = round(price / inst.get("gap", 50)) * inst.get("gap", 50)
        pe_prem = 0
        try:
            from math import log, sqrt, exp, erf
            _iv = (nse.get("atm_iv", 20) or 20) / 100
            _T = max(bs_data.get("dte", 7), 1) / 365 if bs_data else 7/365
            _r = 0.0525 if is_us else 0.065
            d1 = (log(price/atm) + (_r + _iv**2/2)*_T) / (_iv*sqrt(_T)) if _iv > 0 and _T > 0 else 0
            d2 = d1 - _iv*sqrt(_T) if _iv > 0 and _T > 0 else 0
            nd1 = 0.5*(1+erf(d1/sqrt(2))); nd2 = 0.5*(1+erf(d2/sqrt(2)))
            pe_prem = round(max(atm*exp(-_r*_T)*(1-nd2) - price*(1-nd1), 0), 1)
        except: pe_prem = round(price * 0.015, 1)
        
