                        if not info.get("operatingMargins") and _yval(_fd, "operatingMargins"): info["operatingMargins"] = _yval(_fd, "operatingMargins")
                        if not info.get("revenueGrowth") and _yval(_fd, "revenueGrowth"): info["revenueGrowth"] = _yval(_fd, "revenueGrowth")
                        if not info.get("earningsGrowth") and _yval(_fd, "earningsGrowth"): info["earningsGrowth"] = _yval(_fd, "earningsGrowth")
