# ═══ FAST NEWS TICKER (no AI, just RSS headlines) ═══
_stock_news_cache = {}

@app.get("/api/stock-news")
async def stock_news(symbol: str = "RELIANCE", region: str = "IN"):
    """Fetch recent news headlines for a stock with sentiment classification"""
    import asyncio, re
    
    cache_key = f"{symbol}_{region}"
    now = time.time()
    if cache_key in _stock_news_cache and now - _stock_news_cache[cache_key]["ts"] < 900:
        return _stock_news_cache[cache_key]["data"]
    
    is_us = region.upper() == "US"
    yf_sym = symbol if is_us else f"{symbol}.NS"
    loop = asyncio.get_event_loop()
    
    def _fetch():
        try:
            _yahoo_rate_wait()
            tk = yf.Ticker(yf_sym)
            news = tk.news or []
            items = []
            for n in news[:10]:
                title = n.get("title", "") or n.get("content", {}).get("title", "") or ""
                publisher = n.get("publisher", "") or n.get("content", {}).get("provider", {}).get("displayName", "") or ""
                link = n.get("link", "") or n.get("content", {}).get("canonicalUrl", {}).get("url", "") or ""
                pub_ts = n.get("providerPublishTime", 0)
                if title:
                    items.append({"title": title, "publisher": publisher, "link": link, "ts": pub_ts})
            return items
        except:
            return []
    
    raw = await loop.run_in_executor(None, _fetch)
    
    # Classify sentiment
    bullish_kw = ["surge","rally","beat","upgrade","record","growth","profit","gain","buy","bullish","outperform","raise","boost","strong","soar","jump","positive","optimistic","exceed","upside"]
    bearish_kw = ["fall","drop","decline","cut","downgrade","miss","loss","sell","bearish","underperform","weak","crash","fear","risk","warning","slash","layoff","concern","threat","negative","panic","plunge","tumble"]
    
    catalysts = []
    for n in raw:
        t = n["title"].lower()
        bull = sum(1 for k in bullish_kw if k in t)
        bear = sum(1 for k in bearish_kw if k in t)
        sentiment = "bullish" if bull > bear else ("bearish" if bear > bull else "neutral")
        sc = "#10b981" if sentiment == "bullish" else ("#ef4444" if sentiment == "bearish" else "#f59e0b")
        catalysts.append({
            "title": n["title"], "publisher": n["publisher"], 
            "link": n["link"], "sentiment": sentiment, "color": sc
        })
    
    # Generate narrative
    bull_count = sum(1 for c in catalysts if c["sentiment"] == "bullish")
    bear_count = sum(1 for c in catalysts if c["sentiment"] == "bearish")
    total = len(catalysts)
    
    if total == 0:
        narrative = f"No recent news found for {symbol}. The stock may be moving on broader market sentiment or technical factors."
    elif bear_count > bull_count + 1:
        top_bear = [c["title"] for c in catalysts if c["sentiment"] == "bearish"][:2]
        narrative = f"News sentiment is predominantly NEGATIVE ({bear_count}/{total} bearish headlines). Key concerns: {top_bear[0] if top_bear else 'market headwinds'}. This selling pressure is news-driven — wait for sentiment to stabilize before buying."
    elif bull_count > bear_count + 1:
        top_bull = [c["title"] for c in catalysts if c["sentiment"] == "bullish"][:2]
        narrative = f"News sentiment is POSITIVE ({bull_count}/{total} bullish headlines). Catalyst: {top_bull[0] if top_bull else 'positive developments'}. The upward move has fundamental news support."
    else:
        narrative = f"News sentiment is MIXED ({bull_count} bullish, {bear_count} bearish out of {total} headlines). The market is processing conflicting signals — expect volatility."
    
    result = {
        "success": True, "symbol": symbol, "catalysts": catalysts[:8],
        "narrative": narrative, "bullCount": bull_count, "bearCount": bear_count,
        "total": total
    }
    
    _stock_news_cache[cache_key] = {"ts": now, "data": result}
    return result

_news_cache = None
_news_cache_ts = 0

@app.get("/api/news-ticker")
async def news_ticker():
    """Fast news headlines for scrolling ticker — no AI, just RSS"""
    global _news_cache, _news_cache_ts
    now = time.time()
    if _news_cache and now - _news_cache_ts < 1800:  # 30 min cache
        return _news_cache
    
    headlines = []
    feeds = [
        ("🇮🇳", "https://feeds.finance.yahoo.com/rss/2.0/headline?s=%5ENSEI&region=IN&lang=en-US"),
        ("🇮🇳", "https://feeds.finance.yahoo.com/rss/2.0/headline?s=%5EBSESN&region=IN&lang=en-US"),
        ("🇺🇸", "https://feeds.finance.yahoo.com/rss/2.0/headline?s=%5EGSPC&region=US&lang=en-US"),
        ("🇺🇸", "https://feeds.finance.yahoo.com/rss/2.0/headline?s=%5EIXIC&region=US&lang=en-US"),
        ("🌍", "https://feeds.finance.yahoo.com/rss/2.0/headline?s=%5EDJI&region=US&lang=en-US"),
    ]
    
    loop = asyncio.get_event_loop()
    def _fetch():
        results = []
        for flag, url in feeds:
            try:
                r = _http_pool.get(url, timeout=5)
                if r.status_code == 200:
                    import xml.etree.ElementTree as ET
                    root = ET.fromstring(r.text)
                    for item in root.findall('.//item')[:3]:
                        title = item.find('title')
                        if title is not None and title.text:
                            # Simple sentiment from keywords
                            t = title.text.lower()
                            sent = "positive" if any(w in t for w in ["surge","rally","gain","rise","jump","bull","record","high","beat"]) else \
                                   "negative" if any(w in t for w in ["fall","drop","crash","plunge","bear","loss","cut","warn","fear","sell"]) else "neutral"
                            results.append({"title": title.text[:100], "source": flag, "sentiment": sent})
            except:
                pass
        return results
    
    try:
        headlines = await loop.run_in_executor(None, _fetch)
    except:
        headlines = []
    
    if not headlines:
        headlines = [
            {"title": "Markets trading — check live data for latest updates", "source": "🌍", "sentiment": "neutral"},
        ]
    
    result = {"success": True, "headlines": headlines[:15]}
    _news_cache = result
    _news_cache_ts = now
    return result


