# ━━━ CDS SCORING ENGINE (Python version mirrors JS engine) ━━━
def _cds_score_stock(data, segment, currency="₹"):
    """Python implementation of CDS v2.0 scoring — mirrors JS _calcInstitutionalMDO"""
    import math
    p = float(data.get("price", 0))
    if p <= 0:
        return None
    
    fS = int(data.get("fScore", data.get("business", {}).get("fScore", 0)) or 0)
    beta = float(data.get("beta", data.get("fundamental", {}).get("beta", 1)) or 1)
    rsi = float(data.get("technicals", {}).get("rsi", data.get("rsi", 50)) or 50)
    roe = float(data.get("roe", data.get("fundamental", {}).get("roe", 0)) or 0)
    sma50 = float(data.get("technicals", {}).get("sma50", p) or p)
    sma200 = float(data.get("technicals", {}).get("sma200", p) or p)
    fv = float(data.get("intrinsicValue", {}).get("average", 0) or data.get("levels", {}).get("fairValue", p) or p)
    moS = round((fv - p) / p * 100) if p > 0 else 0
    volRatio = float(data.get("technicals", {}).get("volRatio", 1) or 1)
    adx = float(data.get("technicals", {}).get("adx", 0) or 0)
    macd_h = float(data.get("technicals", {}).get("macdHist", 0) or 0)
    de = float(data.get("fundamental", {}).get("debtToEquity", 0) or 0)
    gm = float(data.get("fundamental", {}).get("grossMargin", 0) or 0)
    pe = float(data.get("fundamental", {}).get("pe", data.get("pe", 0)) or 0)
    fwdPE = float(data.get("fwdPE", 0) or 0)
    revG = float(data.get("fundamental", {}).get("revenueGrowth", 0) or 0)
    earnG = float(data.get("fundamental", {}).get("earningsGrowth", 0) or 0)
    histVol = float(data.get("volatility", 0) or 0)
    
    # ROIC/WACC
    rf = 0.072 if currency == "₹" else 0.045
    erp = 0.075 if currency == "₹" else 0.052
    wacc = round((rf + beta * erp) * 100, 1)
    roic = roe * 0.85 if roe > 0 else 0
    spread = roic - wacc
    
    # EPS revision proxy
    epsRev = 1 if (fwdPE > 0 and pe > 0 and fwdPE < pe * 0.85) else (-1 if fwdPE > pe * 1.15 else 0)
    growthStab = 1 if (revG > 0 and earnG > 0) else (-1 if revG < 0 and earnG < 0 else 0)
    
    # L1-L6
    L1 = min(100, max(0, (25 if volRatio >= 2 else 20 if volRatio >= 1.5 else 12 if volRatio >= 1 else 6) + 15 + (10 if adx > 25 else 5) + (5 if beta < 1.5 else 0) + (10 if moS > 10 else 5 if moS > 0 else 0)))
    L2 = min(100, max(0, (20 if rsi > 50 and rsi < 70 else 10) + (15 if adx > 25 else 8) + (12 if volRatio > 1.3 else 6) + (10 if macd_h > 0 else 3) + (8 if epsRev > 0 else 3)))
    L3 = min(100, max(0, (25 if beta < 0.8 else 18 if beta < 1.2 else 10 if beta < 1.5 else 0) + (18 if 30 < rsi < 70 else 8) + (12 if adx < 40 else 6) + (8 if volRatio < 2.5 else 0) + (10 if beta < 1 else 5 if beta < 1.5 else 0)))
    L4 = min(100, max(0, (20 if fS >= 8 else 15 if fS >= 6 else 8 if fS >= 4 else 0) + (15 if roe > 20 else 10 if roe > 10 else 4) + (15 if moS > 20 else 12 if moS > 10 else 8 if moS > 0 else 3) + (15 if spread > 12 else 10 if spread > 5 else 5 if spread > 0 else 0) + (8 if growthStab > 0 else 0)))
    L5 = min(100, max(0, round((70 if 30 <= rsi <= 70 else 40) * 0.25 + ((35 if rsi > 48 else 0) + (25 if volRatio > 0.9 else 0)) * 0.3 + ((15 if 0 < pe < 20 else 8 if 0 < pe < 30 else 0) + (15 if fS >= 7 else 8 if fS >= 5 else 0)) * 0.45)))
    varPct = beta * 15
    L6 = min(100, max(0, (22 if moS > 20 else 15 if moS > 10 else 10 if moS > 0 else 3) + (20 if varPct < 12 else 12 if varPct < 20 else 5) + (15 if fS >= 6 else 8 if fS >= 4 else 0) + (12 if beta < 1.5 else 5) + (12 if roe > 15 else 5 if roe > 5 else 0)))
    
    # Segment weights (SIDEWAYS baseline)
    W = {"LARGE": {"L1":15,"L2":18,"L3":20,"L4":22,"L5":15,"L6":10},
         "MID": {"L1":18,"L2":25,"L3":15,"L4":20,"L5":12,"L6":10},
         "SMALL": {"L1":28,"L2":22,"L3":22,"L4":12,"L5":8,"L6":8},
         "MICRO": {"L1":35,"L2":18,"L3":25,"L4":10,"L5":5,"L6":7}}[segment]
    
    raw = (L1*W["L1"]+L2*W["L2"]+L3*W["L3"]+L4*W["L4"]+L5*W["L5"]+L6*W["L6"]) / 100
    liqConf = 1.0 if L1 >= 60 else 0.95 if L1 >= 40 else 0.85
    score = round(min(100, max(0, raw * liqConf)))
    
    # Verdict
    verdicts = {"LARGE":{75:"CORE HOLD",60:"DEFENSIVE ADD",40:"NEUTRAL",0:"TRIM"},
                "MID":{75:"ACCUMULATION",60:"BREAKOUT READY",40:"EARLY ALPHA",0:"AVOID"},
                "SMALL":{75:"SPECULATIVE ENTRY",60:"WATCHLIST",40:"LIQUIDITY TRAP",0:"AVOID"},
                "MICRO":{75:"EVENT-DRIVEN TRADE",60:"CATALYST WATCH",40:"RESTRICTED",0:"RESTRICTED"}}
    verdict = "AVOID"
    for t in sorted(verdicts[segment].keys(), reverse=True):
        if score >= t:
            verdict = verdicts[segment][t]
            break
    
    bucket = "DEPLOY" if score > 70 and L1 >= 40 and L2 >= 30 else "WATCH" if score >= 55 else "AVOID"
    posSize = min(10, max(1, round(score/100 * L1/100 / max(0.5, beta) * 50)))
    if segment == "MICRO": posSize = min(posSize, 2)
    if segment == "SMALL": posSize = min(posSize, 5)
    
    return {
        "sym": data.get("symbol", "?"), "score": score, "verdict": verdict, "bucket": bucket,
        "posSize": posSize, "moS": moS, "fS": fS, "beta": round(beta, 2), "roe": round(roe, 1),
        "pe": round(pe, 1), "L1": L1, "L2": L2, "L3": L3, "L4": L4, "L5": L5, "L6": L6,
        "segment": segment, "price": round(p, 2)
    }


# ━━━ SEND CDS EMAIL ━━━
def _send_cds_email(to_email, subject, html_body, smtp_user=None, smtp_pass=None):
    """Send CDS scan results via email. Configure SMTP via env vars."""
    import os
    smtp_host = os.environ.get("SMTP_HOST", "smtp.gmail.com")
    smtp_port = int(os.environ.get("SMTP_PORT", "587"))
    smtp_user = smtp_user or os.environ.get("SMTP_USER", "")
    smtp_pass = smtp_pass or os.environ.get("SMTP_PASS", "")
    
    if not smtp_user or not smtp_pass:
        print(f"⚠️ CDS Email: SMTP not configured. Set SMTP_USER and SMTP_PASS environment variables.")
        print(f"   Would have sent to: {to_email}")
        print(f"   Subject: {subject}")
        return False
    
    msg = MIMEMultipart("alternative")
    msg["Subject"] = subject
    msg["From"] = smtp_user
    msg["To"] = to_email
    msg.attach(MIMEText(html_body, "html"))
    
    try:
        with smtplib.SMTP(smtp_host, smtp_port) as server:
            server.starttls()
            server.login(smtp_user, smtp_pass)
            server.send_message(msg)
        print(f"✅ CDS Email sent to {to_email}: {subject}")
        return True
    except Exception as e:
        print(f"❌ CDS Email failed: {e}")
        return False


# ━━━ CDS DAILY SCAN ENDPOINT ━━━
_cds_scan_cache = {}
_cds_scan_cache_ts = 0

@app.get("/api/cds-scan")
async def cds_daily_scan(region: str = "IN", email: str = "", threshold: int = 70):
    """
    CDS v2.0 Daily Scanner — Scans all stocks, returns Deploy signals.
    Optionally emails results to specified address.
    
    Usage:
      /api/cds-scan?region=IN               → Scan India, return JSON
      /api/cds-scan?region=US               → Scan US, return JSON
      /api/cds-scan?region=IN&email=you@mail.com  → Scan + email results
      /api/cds-scan?region=IN&threshold=60  → Lower threshold to 60
    """
    global _cds_scan_cache, _cds_scan_cache_ts
    
    cache_key = f"cds_{region}_{threshold}"
    now = time.time()
    
    # Cache for 4 hours (scan is expensive)
    if cache_key in _cds_scan_cache and now - _cds_scan_cache_ts < 14400:
        cached = _cds_scan_cache[cache_key]
        if email:
            _send_cds_email(email, cached["subject"], cached["html"])
        return cached["data"]
    
    is_us = region.upper() == "US"
    csym = "$" if is_us else "₹"
    universe = CDS_UNIVERSE.get(region.upper(), CDS_UNIVERSE["IN"])
    
    all_results = {}
    scan_start = datetime.now()
    
    for segment, stocks in universe.items():
        segment_results = []
        for sym in stocks:
            try:
                # Call the existing investor-decide API internally
                data = await investor_decide(sym, region.upper())
                if data.get("success"):
                    result = _cds_score_stock(data, segment, csym)
                    if result:
                        result["companyName"] = data.get("companyName", sym)
                        segment_results.append(result)
            except Exception as e:
                print(f"  ⚠️ CDS scan skip {sym}: {e}")
                continue
        
        segment_results.sort(key=lambda x: -x["score"])
        all_results[segment] = segment_results
    
    scan_end = datetime.now()
    scan_duration = (scan_end - scan_start).seconds
    
    # Collect Deploy + Watch signals
    deploy_stocks = []
    watch_stocks = []
    for seg, results in all_results.items():
        for r in results:
            if r["score"] >= threshold:
                deploy_stocks.append(r)
            elif r["score"] >= threshold - 15:
                watch_stocks.append(r)
    
    deploy_stocks.sort(key=lambda x: -x["score"])
    watch_stocks.sort(key=lambda x: -x["score"])
    
    # Build response
    response = {
        "success": True,
        "engine": "CDS v2.0",
        "region": region.upper(),
        "scanDate": scan_start.strftime("%Y-%m-%d %H:%M"),
        "duration": f"{scan_duration}s",
        "threshold": threshold,
        "totalScanned": sum(len(v) for v in all_results.values()),
        "deployCount": len(deploy_stocks),
        "watchCount": len(watch_stocks),
        "deploy": deploy_stocks[:20],
        "watch": watch_stocks[:20],
        "segments": {seg: results[:10] for seg, results in all_results.items()},
    }
    
    # Build email HTML
    seg_icons = {"LARGE":"🏛️","MID":"🚀","SMALL":"🔍","MICRO":"💎"}
    date_str = scan_start.strftime("%d %b %Y")
    
    html = f"""
    <div style="font-family:system-ui,sans-serif;max-width:700px;margin:0 auto;background:#fff">
      <div style="padding:20px 24px;background:linear-gradient(135deg,#0A1628,#1A3A78);color:#fff;border-radius:12px 12px 0 0">
        <div style="font-size:20px;font-weight:900">🤖 CDS v2.0 — Daily Scan Report</div>
        <div style="font-size:12px;color:rgba(255,255,255,.6);margin-top:4px">{'🇮🇳 India' if not is_us else '🇺🇸 USA'} · {date_str} · {response['totalScanned']} stocks scanned · Threshold: {threshold}/100</div>
      </div>
      
      <div style="padding:16px 24px;background:{'#05966910' if deploy_stocks else '#fef3c710'};border-bottom:1px solid #e5e7eb">
        <div style="font-size:16px;font-weight:800;color:{'#059669' if deploy_stocks else '#d97706'}">
          {'🟢 '+str(len(deploy_stocks))+' DEPLOY SIGNAL'+('' if len(deploy_stocks)==1 else 'S')+' DETECTED' if deploy_stocks else '🟡 No Deploy signals today — '+str(len(watch_stocks))+' on watchlist'}
        </div>
      </div>
    """
    
    if deploy_stocks:
        html += '<div style="padding:16px 24px"><div style="font-size:13px;font-weight:800;color:#059669;margin-bottom:8px">🟢 DEPLOY — Invest Now</div>'
        html += '<table style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr style="border-bottom:2px solid #e5e7eb">'
        for h in ['Stock','Score','Segment','Upside','F-Score','Verdict','Alloc']:
            html += f'<th style="padding:6px;text-align:left;font-size:10px;color:#6b7280">{h}</th>'
        html += '</tr></thead><tbody>'
        for r in deploy_stocks[:15]:
            sc_c = '#059669' if r['score']>=75 else '#1A3A78'
            html += f'<tr style="border-bottom:1px solid #f3f4f6"><td style="padding:6px;font-weight:700">{r["sym"]}<div style="font-size:9px;color:#9ca3af">{r.get("companyName","")[:25]}</div></td>'
            html += f'<td style="padding:6px;font-weight:900;color:{sc_c}">{r["score"]}/100</td>'
            html += f'<td style="padding:6px;font-size:10px">{seg_icons.get(r["segment"],"📊")} {r["segment"]}</td>'
            html += f'<td style="padding:6px;color:{"#059669" if r["moS"]>0 else "#dc2626"}">{"+" if r["moS"]>0 else ""}{r["moS"]}%</td>'
            html += f'<td style="padding:6px">{r["fS"]}/9</td>'
            html += f'<td style="padding:6px;font-weight:700;color:{sc_c}">{r["verdict"]}</td>'
            html += f'<td style="padding:6px;font-weight:700">{r["posSize"]}%</td></tr>'
        html += '</tbody></table></div>'
    
    if watch_stocks:
        html += '<div style="padding:16px 24px;border-top:1px solid #e5e7eb"><div style="font-size:13px;font-weight:800;color:#d97706;margin-bottom:8px">🟡 WATCHLIST — Approaching Deploy Threshold</div>'
        html += '<table style="width:100%;border-collapse:collapse;font-size:11px"><tbody>'
        for r in watch_stocks[:10]:
            html += f'<tr style="border-bottom:1px solid #f3f4f6"><td style="padding:4px 6px;font-weight:600">{r["sym"]}</td><td style="padding:4px;font-weight:700;color:#d97706">{r["score"]}/100</td><td style="padding:4px;font-size:10px">{seg_icons.get(r["segment"],"")} {r["segment"]}</td><td style="padding:4px">{r["verdict"]}</td></tr>'
        html += '</tbody></table></div>'
    
    # Segment summaries
    html += '<div style="padding:16px 24px;border-top:2px solid #e5e7eb"><div style="font-size:11px;font-weight:800;color:#6b7280;margin-bottom:8px">SEGMENT BREAKDOWN</div>'
    for seg in ["LARGE","MID","SMALL","MICRO"]:
        results = all_results.get(seg, [])
        if not results:
            continue
        top3 = results[:3]
        html += f'<div style="margin-bottom:6px;font-size:11px"><span style="font-weight:800">{seg_icons[seg]} {seg}:</span> '
        html += ', '.join(f'{r["sym"]}({r["score"]})' for r in top3)
        html += f' <span style="color:#9ca3af">({len(results)} scanned)</span></div>'
    html += '</div>'
    
    html += f"""
      <div style="padding:12px 24px;background:#f9fafb;border-radius:0 0 12px 12px;font-size:10px;color:#9ca3af">
        Celesys Decision System v2.0 · Scan completed in {scan_duration}s · {response['totalScanned']} stocks · This is not financial advice
      </div>
    </div>
    """
    
    subject = f"{'🟢' if deploy_stocks else '🟡'} CDS v2.0 {'🇮🇳' if not is_us else '🇺🇸'} — {len(deploy_stocks)} Deploy · {len(watch_stocks)} Watch · {date_str}"
    
    # Cache
    _cds_scan_cache[cache_key] = {"data": response, "html": html, "subject": subject}
    _cds_scan_cache_ts = now
    
    # Send email if requested
    if email:
        _send_cds_email(email, subject, html)
    
    return response


# ━━━ AUTOMATED DAILY SCAN (runs at market open) ━━━
async def _cds_daily_auto_scan():
    """Background task: runs CDS scan daily at 9:30 AM IST / 9:30 AM EST"""
    import os
    await asyncio.sleep(30)  # Wait for server warmup
    
    auto_email = os.environ.get("CDS_ALERT_EMAIL", "")
    if not auto_email:
        print("ℹ️ CDS Auto-scan: Set CDS_ALERT_EMAIL env var to enable daily emails")
        return
    
    print(f"🤖 CDS Auto-scan: Will email {auto_email} daily")
    
    while True:
        now = datetime.now()
        # Run at 9:30 AM local time
        target_hour = 9
        target_minute = 30
        
        if now.hour == target_hour and now.minute == target_minute:
            print(f"🤖 CDS Auto-scan: Running daily scan at {now.strftime('%H:%M')}")
            try:
                # Scan India
                await cds_daily_scan(region="IN", email=auto_email, threshold=70)
                await asyncio.sleep(60)  # Brief pause between scans
                # Scan US
                await cds_daily_scan(region="US", email=auto_email, threshold=70)
                print(f"✅ CDS Auto-scan: Complete. Emails sent to {auto_email}")
            except Exception as e:
                print(f"❌ CDS Auto-scan error: {e}")
            
            # Sleep until next day (23.5 hours)
            await asyncio.sleep(84600)
        else:
            # Check every minute
            await asyncio.sleep(60)

# Register the auto-scan task at startup
@app.on_event("startup")
async def _start_cds_auto_scan():
    asyncio.create_task(_cds_daily_auto_scan())
    print("🤖 CDS v2.0 Auto-scan task registered")


# ═══════════════════════════════════════════════════════════════════════════════
# UNIVERSAL OPTIONS QUICK TRADE — Works for ANY ticker (India/US/ETF)
# Returns: spot, chain, bias, breakout levels in unified format
# ═══════════════════════════════════════════════════════════════════════════════
# CATALYST SCANNER — News + Earnings + Gap + Volume for morning watchlist
# ═══════════════════════════════════════════════════════════════════════════════

_catalyst_cache = {"ts": 0, "data": None, "region": ""}

@app.get("/api/catalyst-scan")
async def catalyst_scan(region: str = "IN"):
    """Catalyst scanner — India: NSE for options + yfinance for news. US: yfinance for both."""
    import asyncio
    from concurrent.futures import ThreadPoolExecutor, as_completed
    global _catalyst_cache
    
    now = time.time()
    if _catalyst_cache["data"] and now - _catalyst_cache["ts"] < 300 and _catalyst_cache["region"] == region:
        return _catalyst_cache["data"]
    
    is_us = region.upper() == "US"
    tickers = (
        ["SPY","QQQ","AAPL","MSFT","NVDA","TSLA","META","GOOGL","AMZN","MU","AMD","NFLX","COIN","PLTR","SOFI","BA","JPM","UBER","CRM","SMCI"]
        if is_us else
        ["NIFTY","BANKNIFTY","RELIANCE","TCS","HDFCBANK","INFY","ICICIBANK","SBIN","BAJFINANCE","TATAMOTORS","LT","MARUTI","AXISBANK","ITC","BHARTIARTL","WIPRO","HCLTECH","ADANIENT","TITAN","SUNPHARMA"]
    )
    
    loop = asyncio.get_event_loop()
    
    bullish_kw = ["surge","rally","beat","upgrade","record","growth","profit","gain","buy","bullish","outperform","raise","boost","strong","soar","jump","positive","exceed","upside","dividend","bonus","split","buyback","order","deal","contract","approve"]
    bearish_kw = ["fall","drop","decline","cut","downgrade","miss","loss","sell","bearish","underperform","weak","crash","fear","risk","warning","slash","layoff","concern","threat","negative","panic","plunge","tumble","fraud","probe","ban","fine","penalty","resign"]
    
    def _classify_news(title):
        t = title.lower()
        bull = sum(1 for k in bullish_kw if k in t)
        bear = sum(1 for k in bearish_kw if k in t)
        return "bullish" if bull > bear else ("bearish" if bear > bull else "neutral")
    
    def _fetch_news_yf(sym):
        """Fetch news from Yahoo Finance — works for both IN and US"""
        try:
            yf_map = {"NIFTY":"^NSEI","BANKNIFTY":"^NSEBANK","SENSEX":"^BSESN","FINNIFTY":"NIFTY_FIN_SERVICE.NS"}
            yf_sym = sym if is_us else yf_map.get(sym, f"{sym}.NS")
            _yahoo_rate_wait()
            tk = yf.Ticker(yf_sym)
            news = tk.news or []
            items = []
            for n in news[:5]:
                title = n.get("title", "") or n.get("content", {}).get("title", "") or ""
                publisher = n.get("publisher", "") or n.get("content", {}).get("provider", {}).get("displayName", "") or ""
                link = n.get("link", "") or n.get("content", {}).get("canonicalUrl", {}).get("url", "") or ""
                if title:
                    items.append({"title": title, "publisher": publisher, "link": link, "sentiment": _classify_news(title)})
            return items
        except:
            return []
    
    def _fetch_price_yf(sym):
        """Fetch price/gap/volume from Yahoo Finance — used for US stocks"""
        try:
            _yahoo_rate_wait()
            tk = yf.Ticker(sym)
            hist = tk.history(period="5d")
            if len(hist) < 2:
                return {}
            spot = float(hist["Close"].iloc[-1])
            prev_close = float(hist["Close"].iloc[-2])
            today_open = float(hist["Open"].iloc[-1])
            gap_pct = round((today_open - prev_close) / prev_close * 100, 2) if prev_close > 0 else 0
            today_vol = float(hist["Volume"].iloc[-1])
            avg_vol = float(hist["Volume"].iloc[-5:-1].mean()) if len(hist) >= 5 else today_vol
            vol_ratio = round(today_vol / avg_vol, 1) if avg_vol > 0 else 1
            today_high = float(hist["High"].iloc[-1])
            today_low = float(hist["Low"].iloc[-1])
            return {"spot": round(spot, 2), "prevClose": round(prev_close, 2), "gapPct": gap_pct,
                    "volRatio": vol_ratio, "todayHigh": round(today_high, 2), "todayLow": round(today_low, 2)}
        except:
            return {}
    
    def _fetch_india_data(sym):
        """Fetch India data from NSE via _options_quick_impl (sync wrapper)"""
        try:
            import asyncio as _aio
            _loop = _aio.new_event_loop()
            try:
                data = _loop.run_until_complete(_options_quick_impl(sym, "IN"))
                if data and data.get("success"):
                    spot = data.get("spot", 0)
                    vwap = data.get("vwap", 0)
                    prev_close = data.get("prev_close", 0) or data.get("previous_close", 0) or 0
                    pcr = data.get("pcr", 0)
                    bars = data.get("ohlc_bars", [])
                    chain = data.get("chain_near_atm", [])
                    ce_build = data.get("ce_buildup", [])
                    pe_build = data.get("pe_buildup", [])
                    gex = data.get("gex", {})
                    lot_size = data.get("lot_size", 1)
                    
                    gap_pct = round((spot - prev_close) / prev_close * 100, 2) if prev_close > 0 and spot > 0 else 0
                    
                    vol_ratio = 1.0
                    if bars and len(bars) >= 3:
                        recent_vol = sum(b.get("v", 0) for b in bars[-2:]) / 2
                        avg_vol = sum(b.get("v", 0) for b in bars) / len(bars)
                        vol_ratio = round(recent_vol / avg_vol, 1) if avg_vol > 0 else 1
                    
                    today_high = max(b.get("h", 0) for b in bars) if bars else 0
                    today_low = min(b.get("l", 99999999) for b in bars) if bars else 0
                    
                    return {
                        "spot": round(spot, 2), "prevClose": round(prev_close, 2), "gapPct": gap_pct,
                        "volRatio": vol_ratio, "todayHigh": round(today_high, 2), "todayLow": round(today_low, 2),
                        "pcr": pcr, "vwap": round(vwap, 2), "lot_size": lot_size,
                        "ce_buildup": ce_build, "pe_buildup": pe_build,
                        "gex": gex, "chain": chain
                    }
                return {}
            finally:
                _loop.close()
        except:
            return {}
    
    def _scan_one(sym):
        try:
            result = {"sym": sym, "catalysts": [], "score": 0, "direction": "NEUTRAL", "news": [], "spot": 0, "prevClose": 0, "gapPct": 0}
            
            # ─── STEP 1: Get price data (NSE for India, yfinance for US) ───
            if is_us:
                pdata = _fetch_price_yf(sym)
            else:
                pdata = _fetch_india_data(sym)
            
            if not pdata or not pdata.get("spot"):
                return result
            
            spot = pdata["spot"]
            result["spot"] = spot
            result["prevClose"] = pdata.get("prevClose", 0)
            result["gapPct"] = pdata.get("gapPct", 0)
            
            # ─── STEP 2: News (yfinance for both — best free source) ───
            news_items = _fetch_news_yf(sym)
            for n in news_items:
                result["news"].append(n)
                if n["sentiment"] != "neutral":
                    result["catalysts"].append({
                        "type": "NEWS", "icon": "📰",
                        "text": n["title"][:100],
                        "sentiment": n["sentiment"],
                        "link": n.get("link", ""),
                        "impact": 20
                    })
                    result["score"] += 20
                    if n["sentiment"] == "bullish" and result["direction"] == "NEUTRAL":
                        result["direction"] = "BULLISH"
                    if n["sentiment"] == "bearish" and result["direction"] == "NEUTRAL":
                        result["direction"] = "BEARISH"
            
            # ─── STEP 3: Gap detection ───
            gap = pdata.get("gapPct", 0)
            if abs(gap) >= 0.5:
                result["catalysts"].append({
                    "type": "GAP",
                    "icon": "\U0001f7e2" if gap > 0 else "\U0001f534",
                    "text": f"{'Gap Up' if gap > 0 else 'Gap Down'} {abs(gap):.1f}%",
                    "sentiment": "bullish" if gap > 0 else "bearish",
                    "impact": min(35, int(abs(gap) * 8))
                })
                result["score"] += min(35, int(abs(gap) * 8))
                if result["direction"] == "NEUTRAL":
                    result["direction"] = "BULLISH" if gap > 0 else "BEARISH"
            
            # ─── STEP 4: Volume surge ───
            vr = pdata.get("volRatio", 1)
            if vr >= 1.5:
                result["catalysts"].append({
                    "type": "VOLUME", "icon": "\U0001f4ca",
                    "text": f"Volume {vr}x average — institutional activity",
                    "sentiment": "neutral",
                    "impact": min(25, int(vr * 8))
                })
                result["score"] += min(25, int(vr * 8))
            
            # ─── STEP 5: India-specific — OI Build-up + PCR ───
            if not is_us:
                ce_build = pdata.get("ce_buildup", [])
                pe_build = pdata.get("pe_buildup", [])
                pcr = pdata.get("pcr", 0)
                
                if pe_build and len(pe_build) > 0 and pe_build[0].get("chg", 0) > 5000:
                    result["catalysts"].append({
                        "type": "OI_BUILDUP", "icon": "\U0001f3db\ufe0f",
                        "text": f"Put writers built {pe_build[0]['chg']:,} contracts at {pe_build[0]['strike']:,} — bullish",
                        "sentiment": "bullish", "impact": 25
                    })
                    result["score"] += 25
                    if result["direction"] == "NEUTRAL": result["direction"] = "BULLISH"
                
                if ce_build and len(ce_build) > 0 and ce_build[0].get("chg", 0) > 5000:
                    result["catalysts"].append({
                        "type": "OI_BUILDUP", "icon": "\U0001f3db\ufe0f",
                        "text": f"Call writers built {ce_build[0]['chg']:,} contracts at {ce_build[0]['strike']:,} — bearish",
                        "sentiment": "bearish", "impact": 25
                    })
                    result["score"] += 25
                    if result["direction"] == "NEUTRAL": result["direction"] = "BEARISH"
                
                if pcr > 1.5:
                    result["catalysts"].append({"type": "PCR", "icon": "\U0001f4c8", "text": f"PCR {pcr:.1f} — extreme put writing, very bullish", "sentiment": "bullish", "impact": 15})
                    result["score"] += 15
                elif 0 < pcr < 0.5:
                    result["catalysts"].append({"type": "PCR", "icon": "\U0001f4c9", "text": f"PCR {pcr:.1f} — extreme call writing, very bearish", "sentiment": "bearish", "impact": 15})
                    result["score"] += 15
            
            # ─── STEP 6: Trade details (computed) ───
            if spot > 0 and result["direction"] != "NEUTRAL":
                _inst = ALGO_INSTRUMENTS.get(sym, {})
                lot = pdata.get("lot_size", 0) or _inst.get("lot", 100 if is_us else 1)
                step = _inst.get("gap", 1 if is_us else (50 if spot > 5000 else 20 if spot > 1000 else 5))
                is_bull = result["direction"] == "BULLISH"
                atm = round(spot / step) * step
                
                day_range = abs(gap) * spot / 100 + spot * 0.005
                est_prem = round(day_range * (1.5 if is_us else 1.0), 2)
                if est_prem <= 0: est_prem = round(spot * 0.01, 2)
                
                target = round(est_prem * 1.4, 2)
                sl = round(est_prem * 0.70, 2)
                rr = round((target - est_prem) / max(est_prem - sl, 0.01), 1)
                
                result["trade"] = {
                    "action": "BUY CALL" if is_bull else "BUY PUT",
                    "strike": atm, "type": "CE" if is_bull else "PE",
                    "premium": est_prem, "target": target, "sl": sl,
                    "rr": rr, "lot": lot, "spot": round(spot, 2)
                }
            
            # Urgency
            result["urgency"] = "HIGH" if result["score"] >= 50 else ("MEDIUM" if result["score"] >= 25 else "LOW")
            return result
        except Exception as e:
            return {"sym": sym, "catalysts": [], "score": 0, "direction": "NEUTRAL", "news": [], "urgency": "LOW", "error": str(e)}
    
    # Run in parallel
    results = []
    try:
        with ThreadPoolExecutor(max_workers=5) as executor:
            futures = {executor.submit(_scan_one, t): t for t in tickers}
            for future in as_completed(futures, timeout=60):
                try:
                    r = future.result(timeout=15)
                    if r: results.append(r)
                except: pass
    except: pass
    
    # Sort by score, filter empty
    results = [r for r in results if r.get("score", 0) > 0]
    results.sort(key=lambda x: x["score"], reverse=True)
    
    response = {
        "success": True,
        "region": region,
        "catalysts": results[:15],
        "total_scanned": len(tickers),
        "high_urgency": len([r for r in results if r.get("urgency") == "HIGH"]),
        "ts": now
    }
    
    _catalyst_cache = {"ts": now, "data": response, "region": region}
    return response

# ═══════════════════════════════════════════════════════════════════════════════

@app.get("/api/options-quick")
async def options_quick(symbol: str = "NIFTY", region: str = "IN"):
    """Universal options quick trade data — works for India indices, US stocks, ETFs."""
    try:
        return await _options_quick_impl(symbol, region)
    except Exception as e:
        print(f"[OPTIONS-QUICK] ❌ Top-level error for {symbol}: {e}")
        return {"success": False, "error": str(e)[:200], "spot": 0, "ohlc_bars": [], "chain_near_atm": [], "ce_resistance": [], "pe_support": [], "gex": {"total": 0, "regime": "NEUTRAL", "topStrikes": [], "flipPoint": 0, "callWall": 0, "putWall": 0}}


async def _options_quick_impl(symbol: str = "NIFTY", region: str = "IN"):
    """Actual implementation — separated so top-level catches ALL errors cleanly."""
    try:
        sym = symbol.upper().replace('.NS', '').replace('.BO', '')
        
        # Detect market type
        india_indices = ['NIFTY', 'BANKNIFTY', 'SENSEX', 'FINNIFTY', 'MIDCPNIFTY']
        is_india_index = sym in india_indices
        is_india = (region == 'IN') or is_india_index
        result = None  # Initialize
        
        # ══════════════════════════════════════════════════════════════════
        # NSE FIRST FOR ALL INDIA SYMBOLS (not just indices).
        #
        # Previously only 5 indices routed here. Everything else — HDFCBANK,
        # RELIANCE, TCS, ETFs like BANKBEES — fell through to Yahoo, which
        # does NOT have real option chains for Indian stocks. Result: every
        # Indian single-stock scan produced `_chain_unavailable` and got
        # dropped. nse_options() already handles stock equities via the
        # option-chain-equities endpoint (see line ~3765); we just weren't
        # calling it.
        # ══════════════════════════════════════════════════════════════════
        if is_india:
            # r37: Upstox FIRST (if connected) — personal broker API, no
            # IP-ban issues, real-time NSE data entitlement. This is the
            # permanent fix for India option chains. Falls through to NSE
            # scraping if Upstox is disconnected, token expired, or fails.
            if _upstox_is_connected():
                try:
                    upstox_result = _upstox_get_option_chain(sym)
                    if upstox_result and upstox_result.get("success") and upstox_result.get("spot", 0) > 0:
                        try:
                            diag_log("FALLBACK", "upstox_ok", {
                                "sym": sym, "step": "upstox", "result": "success",
                                "spot": upstox_result.get("spot"),
                                "strikes": len(upstox_result.get("chain_near_atm", [])),
                            })
                        except Exception: pass
                        # Need to fill in remaining fields expected downstream
                        # (ohlc_bars, gex, etc.) — use empty/default values so
                        # frontend doesn't crash on missing fields.
                        upstox_result.setdefault("ohlc_bars", [])
                        upstox_result.setdefault("ce_resistance", [])
                        upstox_result.setdefault("pe_support", [])
                        upstox_result.setdefault("gex", {"total": 0, "regime": "NEUTRAL", "topStrikes": [], "flipPoint": 0, "callWall": 0, "putWall": 0})
                        return upstox_result
                    else:
                        try: diag_log("FALLBACK", "upstox_returned_empty", {"sym": sym})
                        except Exception: pass
                except Exception as _uxe:
                    print(f"[OPTIONS-QUICK] Upstox failed for {sym}: {type(_uxe).__name__}: {_uxe}")
                    try: diag_log("FALLBACK", "upstox_exception_outer", {
                        "sym": sym, "err": f"{type(_uxe).__name__}: {str(_uxe)[:120]}",
                    })
                    except Exception: pass
            
            print(f"[OPTIONS-QUICK] Trying NSE for {sym} (india)...")
            try:
                result = await nse_options(sym)
                if result and result.get("success") and result.get("spot", 0) > 0:
                    return result
                print(f"[OPTIONS-QUICK] NSE returned no data for {sym}, trying yfinance fallback...")
            except Exception as nse_err:
                print(f"[OPTIONS-QUICK] NSE failed for {sym}: {nse_err}, trying yfinance fallback...")
        
        if is_india_index:
            # Fallback: use yfinance for basic spot + VIX data (indices only)
            import yfinance as yf
            yf_map = {"NIFTY": "^NSEI", "BANKNIFTY": "^NSEBANK", "SENSEX": "^BSESN", "FINNIFTY": "NIFTY_FIN_SERVICE.NS", "MIDCPNIFTY": "NIFTY_MID_SELECT.NS"}
            yf_sym = yf_map.get(sym, f"^NSEI")
            print(f"[OPTIONS-QUICK] yfinance fallback: {yf_sym}")
            _yahoo_rate_wait()
            
            try:
                tk = yf.Ticker(yf_sym)
                hist = tk.history(period="2d", interval="5m")
                
                if len(hist) > 0:
                    spot = float(hist['Close'].iloc[-1])
                    day_high = float(hist['High'].max()) if len(hist) > 5 else spot
                    day_low = float(hist['Low'].min()) if len(hist) > 5 else spot
                    day_open = float(hist['Open'].iloc[0]) if len(hist) > 0 else spot
                    vwap = round((day_high + day_low + spot) / 3, 2)
                    
                    # Get VIX
                    vix = 18.0
                    try:
                        vix_tk = yf.Ticker("^INDIAVIX")
                        vix_h = vix_tk.history(period="1d")
                        if len(vix_h) > 0:
                            vix = float(vix_h['Close'].iloc[-1])
                    except:
                        pass
                    
                    # Build basic chain from intraday data
                    # ══════════════════════════════════════════════════════════════
                    # STRICT: NSE failed and we only have yfinance spot data.
                    # We do NOT have real option chain (LTP/bid/ask/OI) — so we
                    # REFUSE to fabricate ce_ltp/pe_ltp from an intrinsic-value
                    # approximation. A made-up premium corrupts every downstream
                    # number (SL, Target, Trigger, R:R, Kelly sizing, attribution).
                    #
                    # Return success:False so the bottom-nav scanner drops this
                    # ticker rather than showing a tradable card at a fake price.
                    # See celesys core principle: no fake assumptions.
                    # ══════════════════════════════════════════════════════════════
                    print(f"[SYNTH-PREMIUM-BLOCKED] {sym}: NSE chain down + yfinance has no chain → dropping ticker (spot={spot}). This is intentional — we refuse to fabricate option premiums.")
                    return {
                        "success": False,
                        "error": "NSE option chain unavailable and no real chain from yfinance — refusing to fabricate premiums",
                        "symbol": sym,
                        "spot": round(spot, 2),  # spot is real, but we won't trade without chain
                        "_chain_unavailable": True,
                        "ohlc_bars": [], "chain_near_atm": [], "ce_resistance": [], "pe_support": [],
                        "gex": {"total": 0, "regime": "NEUTRAL", "topStrikes": [], "flipPoint": 0, "callWall": 0, "putWall": 0}
                    }
                else:
                    print(f"[OPTIONS-QUICK] ❌ yfinance returned no history for {yf_sym}")
            except Exception as yf_err:
                print(f"[OPTIONS-QUICK] ❌ yfinance fallback failed: {yf_err}")
            
            return {"success": False, "error": "NSE API and yfinance both failed", "spot": 0, "ohlc_bars": [], "chain_near_atm": [], "ce_resistance": [], "pe_support": [], "gex": {"total": 0, "regime": "NEUTRAL", "topStrikes": [], "flipPoint": 0, "callWall": 0, "putWall": 0}}
        
        # ═══ LAST RESORT: If India index and both NSE and yfinance fail ═══
        # We only try one more thing: fetch spot from Yahoo's chart endpoint
        # directly (bypassing yfinance library). Even if we get spot, we do NOT
        # have an option chain — so we refuse to fabricate premiums and return
        # success:False. See celesys core principle: no fake assumptions.
        if is_india_index and (result is None or not result.get("success")):
            print(f"[OPTIONS-QUICK] ⚠️ Last resort: trying direct Yahoo for spot-only {sym} (no chain will be fabricated)")
            try:
                import requests as _rq
                yf_map2 = {"NIFTY": "^NSEI", "BANKNIFTY": "^NSEBANK", "SENSEX": "^BSESN"}
                yf_s2 = yf_map2.get(sym, f"^NSEI")
                r2 = _rq.get(f"https://query1.finance.yahoo.com/v8/finance/chart/{yf_s2}?interval=5m&range=1d",
                    headers={"User-Agent": "Mozilla/5.0"}, timeout=10)
                if r2.status_code == 200:
                    j2 = r2.json()
                    meta = j2.get("chart", {}).get("result", [{}])[0].get("meta", {})
                    spot2 = meta.get("regularMarketPrice", 0)
                    if spot2 > 0:
                        # We got spot — but WITHOUT a real option chain, we cannot
                        # produce a tradable card. Drop the ticker.
                        print(f"[SYNTH-PREMIUM-BLOCKED] {sym}: last-resort got spot={spot2} but no chain → dropping. Refusing to fabricate premiums.")
                        return {
                            "success": False,
                            "error": "NSE+yfinance chain unavailable; spot-only data won't produce a tradable card",
                            "symbol": sym,
                            "spot": round(spot2, 2),
                            "_chain_unavailable": True,
                            "ohlc_bars": [], "chain_near_atm": [], "ce_resistance": [], "pe_support": [],
                            "gex": {"total": 0, "regime": "NEUTRAL", "topStrikes": [], "flipPoint": 0, "callWall": 0, "putWall": 0}
                        }
            except Exception as lr_err:
                print(f"[OPTIONS-QUICK] ❌ Last resort also failed: {lr_err}")
        
        # If India index, return whatever we have (don't fall into US path)
        if is_india_index:
            if result and result.get("success"):
                return result
            # r34 bug fix: yfinance fallback was only wired for India STOCKS,
            # not indices. When NSE blocks NIFTY/BANKNIFTY/SENSEX, the scanner
            # hits this branch and returns failure without trying yfinance.
            # Now: try yfinance here too. Same .NS/^ mapping as stocks path.
            try:
                import yfinance as yf
                if sym in ("NIFTY", "NIFTY 50"):
                    yf_idx_sym = "^NSEI"
                elif sym in ("BANKNIFTY", "NIFTY BANK"):
                    yf_idx_sym = "^NSEBANK"
                elif sym == "SENSEX":
                    yf_idx_sym = "^BSESN"
                elif sym == "FINNIFTY":
                    yf_idx_sym = "NIFTY_FIN_SERVICE.NS"
                elif sym == "MIDCPNIFTY":
                    yf_idx_sym = "NIFTY_MID_SELECT.NS"
                else:
                    yf_idx_sym = None
                
                if yf_idx_sym:
                    _yahoo_rate_wait()
                    yf_idx_tk = yf.Ticker(yf_idx_sym)
                    yf_idx_spot = 0
                    yf_idx_bars = []
                    try:
                        yf_info_idx = yf_idx_tk.info or {}
                        yf_idx_spot = (yf_info_idx.get('regularMarketPrice', 0)
                                       or yf_info_idx.get('currentPrice', 0) or 0)
                    except Exception:
                        yf_idx_spot = 0
                    
                    # fallback via history if .info didn't work (common for indices)
                    if yf_idx_spot <= 0:
                        try:
                            _yahoo_rate_wait()
                            _quick = yf_idx_tk.history(period="1d", interval="1m")
                            if _quick is not None and len(_quick) > 0:
                                yf_idx_spot = float(_quick['Close'].iloc[-1])
                        except Exception:
                            pass
                    
                    if yf_idx_spot > 0:
                        try:
                            _yahoo_rate_wait()
                            yf_hist_idx = yf_idx_tk.history(period="1d", interval="5m")
                            if yf_hist_idx is not None and len(yf_hist_idx) > 0:
                                for _, _b in yf_hist_idx.tail(30).iterrows():
                                    yf_idx_bars.append({
                                        "t": str(_b.name.time())[:5] if hasattr(_b.name, 'time') else "",
                                        "o": round(float(_b['Open']), 2),
                                        "h": round(float(_b['High']), 2),
                                        "l": round(float(_b['Low']), 2),
                                        "c": round(float(_b['Close']), 2),
                                        "v": int(_b['Volume']) if _b['Volume'] else 0,
                                    })
                        except Exception as _ybe:
                            print(f"[OPTIONS-QUICK] {sym} (index): yfinance bars failed: {type(_ybe).__name__}")
                        
                        print(f"[OPTIONS-QUICK] {sym} (INDEX): NSE failed, yfinance gave spot={yf_idx_spot}, {len(yf_idx_bars)} bars.")
                        diag_log("FALLBACK", "yfinance_india_index_ok", {
                            "sym": sym, "step": "yfinance_india_index", "result": "success",
                            "spot": round(yf_idx_spot, 2), "bars": len(yf_idx_bars)
                        })
                        return {
                            "success": False,
                            "error": f"NSE chain unavailable for index {sym}; yfinance spot={yf_idx_spot}",
                            "symbol": sym,
                            "spot": round(yf_idx_spot, 2),
                            "_chain_unavailable": True,
                            "_spot_source": "yfinance_india_index",
                            "ohlc_bars": yf_idx_bars,
                            "chain_near_atm": [], "ce_resistance": [], "pe_support": [],
                            "gex": {"total": 0, "regime": "NEUTRAL", "topStrikes": [], "flipPoint": 0, "callWall": 0, "putWall": 0}
                        }
            except Exception as _yie:
                print(f"[OPTIONS-QUICK] {sym} (index): yfinance fallback failed: {type(_yie).__name__}: {_yie}")
                diag_log("FALLBACK", "yfinance_india_index_failed", {
                    "sym": sym, "step": "yfinance_india_index", "result": "exception",
                    "err": f"{type(_yie).__name__}: {str(_yie)[:120]}"
                })
            
            # All paths exhausted for an India index
            diag_log("FALLBACK", "all_sources_exhausted_index", {
                "sym": sym, "step": "all_sources", "result": "failure",
                "note": "both NSE and yfinance failed for an India index — likely shared-IP ban"
            })
            return {"success": False, "error": "All data sources failed for " + sym, "spot": 0, "ohlc_bars": [], "chain_near_atm": [], "ce_resistance": [], "pe_support": [], "gex": {"total": 0, "regime": "NEUTRAL", "topStrikes": [], "flipPoint": 0, "callWall": 0, "putWall": 0}}
        
        # ══════════════════════════════════════════════════════════════════
        # India STOCKS (non-index) when NSE failed:
        # Yahoo does not carry real Indian stock option chains — falling
        # through to the Yahoo path would either 404 or return US ticker
        # data for name collisions (e.g. "SAIL" in India vs "SAIL" in US).
        # Return honest failure instead of pretending there's a chain.
        # ══════════════════════════════════════════════════════════════════
        if is_india and not is_india_index:
            # ══════════════════════════════════════════════════════════════
            # Known-no-options symbols: NSE doesn't list options on most
            # ETFs (NIFTYBEES, GOLDBEES, SILVERBEES, etc.). Trying them
            # over and over wastes scan time and pollutes logs. Drop them
            # silently — they're in the scan universe for *price* tracking
            # on other parts of the app, not options trading.
            # ══════════════════════════════════════════════════════════════
            _NO_OPTIONS_SYMBOLS = {
                "NIFTYBEES", "BANKBEES", "GOLDBEES", "SILVERBEES", "ITBEES",
                "JUNIORBEES", "MOM50", "CPSE", "ICICIB22", "MAFANG",
            }
            if sym in _NO_OPTIONS_SYMBOLS:
                # Silent drop — no error log for expected-empty tickers
                return {
                    "success": False,
                    "error": f"No listed options on NSE for ETF {sym}",
                    "symbol": sym, "spot": 0,
                    "_chain_unavailable": True,
                    "ohlc_bars": [], "chain_near_atm": [], "ce_resistance": [], "pe_support": [],
                    "gex": {"total": 0, "regime": "NEUTRAL", "topStrikes": [], "flipPoint": 0, "callWall": 0, "putWall": 0}
                }
            
            # ══════════════════════════════════════════════════════════════
            # r18 FIX: NSE's /api/quote-equity endpoint IS working even when
            # /api/option-chain-equities is blocked. Confirmed in live logs:
            # "✅ NSE Quote: RELIANCE ₹1354.9" works while chain endpoint
            # returns empty. Try quote-equity FIRST — it's the fastest and
            # most reliable spot source. Chain stays unavailable, card is
            # non-tradable, but at least we show a real live price.
            # ══════════════════════════════════════════════════════════════
            nse_quote_spot = 0
            try:
                q_url = f"https://www.nseindia.com/api/quote-equity?symbol={sym}"
                q_data = _nse_get(q_url)
                if q_data:
                    pi = q_data.get("priceInfo") or {}
                    try:
                        nse_quote_spot = float(pi.get("lastPrice", 0) or 0)
                    except (TypeError, ValueError):
                        nse_quote_spot = 0
            except Exception as qe:
                print(f"[OPTIONS-QUICK] {sym}: NSE quote-equity fallback failed: {type(qe).__name__}: {qe}")
                diag_log("FALLBACK", "nse_quote_equity_failed", {
                    "sym": sym, "step": "nse_quote_equity", "result": "exception",
                    "err": f"{type(qe).__name__}: {str(qe)[:120]}"
                })
            
            if nse_quote_spot > 0:
                print(f"[OPTIONS-QUICK] {sym}: NSE chain unavailable, NSE quote-equity gave spot={nse_quote_spot}. Card shown non-tradable.")
                diag_log("FALLBACK", "nse_quote_equity_ok", {
                    "sym": sym, "step": "nse_quote_equity", "result": "success",
                    "spot": round(nse_quote_spot, 2)
                })
                return {
                    "success": False,
                    "error": f"NSE chain unavailable; NSE quote spot={nse_quote_spot}",
                    "symbol": sym,
                    "spot": round(nse_quote_spot, 2),
                    "_chain_unavailable": True,
                    "_spot_source": "nse_quote_equity",
                    "ohlc_bars": [], "chain_near_atm": [], "ce_resistance": [], "pe_support": [],
                    "gex": {"total": 0, "regime": "NEUTRAL", "topStrikes": [], "flipPoint": 0, "callWall": 0, "putWall": 0}
                }
            
            # ══════════════════════════════════════════════════════════════
            # MoneyControl spot fallback (r14). When NSE fails for a real
            # optionable Indian stock (HDFCBANK, RELIANCE, etc.), MC's
            # priceapi still returns spot. We get a real price to show,
            # but we STILL don't fabricate a chain — card non-tradable.
            #
            # DEFENSIVE (r16 fix): MC returns {"data": null} for unknown
            # symbols. Must not assume dict-shape; every access guarded.
            # ══════════════════════════════════════════════════════════════
            mc_spot = 0
            try:
                mc_url = f"https://priceapi.moneycontrol.com/pricefeed/nse/equitycash/{sym}"
                mc_r = requests.get(mc_url, headers={
                    'User-Agent': 'Mozilla/5.0', 'Accept': 'application/json',
                    'Referer': 'https://www.moneycontrol.com/'
                }, timeout=5)
                if mc_r.status_code == 200:
                    mc_json = mc_r.json() or {}
                    mc_data = mc_json.get("data") or {}
                    if isinstance(mc_data, dict):
                        try:
                            mc_spot = float(mc_data.get("pricecurrent", 0) or 0)
                        except (TypeError, ValueError):
                            mc_spot = 0
            except Exception as mce:
                print(f"[OPTIONS-QUICK] {sym}: MC fallback also failed: {type(mce).__name__}: {mce}")
            
            if mc_spot > 0:
                print(f"[OPTIONS-QUICK] {sym}: NSE failed, MoneyControl gave spot={mc_spot}. No chain — card will be non-tradable.")
                diag_log("FALLBACK", "moneycontrol_ok", {
                    "sym": sym, "step": "moneycontrol", "result": "success",
                    "spot": round(mc_spot, 2)
                })
                return {
                    "success": False,
                    "error": f"NSE chain unavailable; MC spot={mc_spot}",
                    "symbol": sym,
                    "spot": round(mc_spot, 2),
                    "_chain_unavailable": True,
                    "_spot_source": "moneycontrol",
                    "ohlc_bars": [], "chain_near_atm": [], "ce_resistance": [], "pe_support": [],
                    "gex": {"total": 0, "regime": "NEUTRAL", "topStrikes": [], "flipPoint": 0, "callWall": 0, "putWall": 0}
                }
            
            # ══════════════════════════════════════════════════════════════
            # r32: yfinance fallback for India (third-tier after NSE + MC).
            #
            # yfinance provides spot + OHLC bars for Indian equities via the
            # .NS suffix (e.g. RELIANCE.NS, HDFCBANK.NS) and indices via
            # ^NSEI / ^BSESN / etc. It does NOT provide option chains for
            # Indian tickers — that's NSE-exclusive. So this fallback gives:
            #   ✓ Real live spot
            #   ✓ Intraday OHLC bars (enables sparklines, timeframes view)
            #   ✗ No option chain → card remains non-tradable
            #
            # Rate-limit shared with US yfinance path via _yahoo_rate_wait().
            # Circuit breaker (r23) protects both regions using same
            # provider key "yahoo_chain" — but we DON'T fetch options here,
            # just spot + bars, so no chain-level rate limit.
            # ══════════════════════════════════════════════════════════════
            yf_spot = 0
            yf_bars = []
            try:
                import yfinance as yf
                # Map symbol to yfinance convention
                if sym in ("NIFTY", "NIFTY 50"):
                    yf_india_sym = "^NSEI"
                elif sym in ("BANKNIFTY", "NIFTY BANK"):
                    yf_india_sym = "^NSEBANK"
                elif sym == "SENSEX":
                    yf_india_sym = "^BSESN"
                elif sym == "FINNIFTY":
                    yf_india_sym = "NIFTY_FIN_SERVICE.NS"
                elif sym == "MIDCPNIFTY":
                    yf_india_sym = "NIFTY_MID_SELECT.NS"
                else:
                    # Regular equity — append .NS for NSE listing
                    yf_india_sym = sym + ".NS"
                
                _yahoo_rate_wait()  # respect global Yahoo rate limit
                yf_tk = yf.Ticker(yf_india_sym)
                try:
                    yf_info = yf_tk.info or {}
                    yf_spot = (yf_info.get('currentPrice', 0)
                               or yf_info.get('regularMarketPrice', 0)
                               or 0)
                except Exception:
                    yf_spot = 0
                
                # Intraday bars — last day, 5m interval (matches US path)
                if yf_spot > 0:
                    try:
                        _yahoo_rate_wait()
                        yf_hist = yf_tk.history(period="1d", interval="5m")
                        if yf_hist is not None and len(yf_hist) > 0:
                            for _, _b in yf_hist.tail(30).iterrows():
                                yf_bars.append({
                                    "t": str(_b.name.time())[:5] if hasattr(_b.name, 'time') else "",
                                    "o": round(float(_b['Open']), 2),
                                    "h": round(float(_b['High']), 2),
                                    "l": round(float(_b['Low']), 2),
                                    "c": round(float(_b['Close']), 2),
                                    "v": int(_b['Volume']) if _b['Volume'] else 0,
                                })
                    except Exception as yhe:
                        print(f"[OPTIONS-QUICK] {sym}: yfinance bars fetch failed: {type(yhe).__name__}: {yhe}")
            except Exception as yfe:
                print(f"[OPTIONS-QUICK] {sym}: yfinance India fallback failed: {type(yfe).__name__}: {yfe}")
                diag_log("FALLBACK", "yfinance_india_failed", {
                    "sym": sym, "step": "yfinance_india", "result": "exception",
                    "err": f"{type(yfe).__name__}: {str(yfe)[:120]}"
                })
            
            if yf_spot > 0:
                print(f"[OPTIONS-QUICK] {sym}: NSE+MC failed, yfinance gave spot={yf_spot}, {len(yf_bars)} bars.")
                diag_log("FALLBACK", "yfinance_india_ok", {
                    "sym": sym, "step": "yfinance_india", "result": "success",
                    "spot": round(yf_spot, 2), "bars": len(yf_bars)
                })
                return {
                    "success": False,
                    "error": f"NSE chain unavailable; yfinance spot={yf_spot}",
                    "symbol": sym,
                    "spot": round(yf_spot, 2),
                    "_chain_unavailable": True,
                    "_spot_source": "yfinance_india",
                    "ohlc_bars": yf_bars,  # real bars → enables sparklines
                    "chain_near_atm": [], "ce_resistance": [], "pe_support": [],
                    "gex": {"total": 0, "regime": "NEUTRAL", "topStrikes": [], "flipPoint": 0, "callWall": 0, "putWall": 0}
                }
            
            print(f"[OPTIONS-QUICK] {sym}: NSE + MC + yfinance all failed — dropping.")
            diag_log("FALLBACK", "all_sources_exhausted_stock", {
                "sym": sym, "step": "all_sources", "result": "failure",
                "note": "NSE + MC + yfinance all failed for an India stock"
            })
            return {
                "success": False,
                "error": "NSE option chain unavailable for Indian stock " + sym,
                "symbol": sym,
                "spot": 0,
                "_chain_unavailable": True,
                "ohlc_bars": [], "chain_near_atm": [], "ce_resistance": [], "pe_support": [],
                "gex": {"total": 0, "regime": "NEUTRAL", "topStrikes": [], "flipPoint": 0, "callWall": 0, "putWall": 0}
            }
        
        # ═══ US STOCK / ETF OPTIONS (via Yahoo Finance) ═══
        # India is handled above (short-circuits if NSE failed). Only US
        # tickers reach this path; yf_sym matches sym directly.
        yf_sym = sym
        
        print(f"[OPTIONS-QUICK] Fetching {yf_sym} via Yahoo Finance")
        _yahoo_rate_wait()
        
        import yfinance as yf
        tk = yf.Ticker(yf_sym)
        
        # Get stock info
        info = {}
        try:
            info = tk.info or {}
        except:
            pass
        
        spot = info.get('currentPrice', 0) or info.get('regularMarketPrice', 0) or 0
        prev_close = info.get('previousClose', spot) or spot
        day_high = info.get('dayHigh', spot) or spot
        day_low = info.get('dayLow', spot) or spot
        day_open = info.get('open', spot) or spot
        volume = info.get('volume', 0) or 0
        
        # Fallback: if info didn't give spot, try history
        if spot <= 0:
            try:
                hist = tk.history(period='2d', interval='5m')
                if len(hist) > 0:
                    spot = float(hist['Close'].iloc[-1])
                    day_high = float(hist['High'].max())
                    day_low = float(hist['Low'].min())
                    day_open = float(hist['Open'].iloc[0])
                    print(f"[OPTIONS-QUICK] Got spot from history: {yf_sym}={spot}")
            except Exception as hist_err:
                print(f"[OPTIONS-QUICK] History fallback failed: {hist_err}")
        
        # Get VIX (CBOE for US, India VIX for IN)
        vix = 0
        try:
            vix_sym = '^VIX' if region == 'US' else '^INDIAVIX'
            vix_tk = yf.Ticker(vix_sym)
            vix_hist = vix_tk.history(period='1d')
            if len(vix_hist) > 0:
                vix = float(vix_hist['Close'].iloc[-1])
        except Exception as e:
            print(f"[OPTIONS-QUICK] VIX fetch error: {e}")
            vix = 18.0  # fallback
        
        # NaN guard — Yahoo returns NaN for missing OI/IV fields
        import math as _math
        def _is_nan(v):
            try:
                return v is None or _math.isnan(float(v))
            except (TypeError, ValueError):
                return True
        
        # Get options chain
        chain_data = []
        ce_resistance = []
        pe_support = []
        atm_iv = 0
        pcr = 0
        max_pain = 0
        expiry_dates = []
        
        try:
            # r23: Circuit breaker guard for Yahoo. If repeated 429s have tripped
            # the breaker, short-circuit immediately — don't fuel the fire.
            if not _cb_allow("yahoo_chain"):
                print(f"[OPTIONS-QUICK] ⏸ {yf_sym}: circuit breaker OPEN for yahoo_chain — skipping chain fetch")
                raise Exception("circuit_breaker_open")
            
            opts = tk.options
            if opts and len(opts) > 0:
                expiry_dates = list(opts[:4])  # First 4 expiries
                # ══════════════════════════════════════════════════════════════
                # Yahoo rate-limit discipline for US option chain fetch.
                #
                # Without this, 8 parallel scanner threads would hit
                # tk.option_chain() concurrently → "Too Many Requests" → every
                # ticker dropped by our strict-honest no-fabrication policy →
                # empty scanner. _yahoo_rate_wait() uses a module-global lock
                # that serializes calls across threads with 1.5s spacing.
                #
                # We also retry once on failure with a 3s backoff — Yahoo's
                # rate limit is a hard cap per burst, not per hour, so a single
                # patient retry usually succeeds.
                # ══════════════════════════════════════════════════════════════
                _yahoo_rate_wait()
                try:
                    chain = tk.option_chain(opts[0])
                except Exception as _chain_e1:
                    _err1 = str(_chain_e1)
                    if "Too Many" in _err1 or "429" in _err1 or "rate" in _err1.lower():
                        # r23: report rate-limit to breaker BEFORE retrying
                        _cb_record_failure("yahoo_chain", reason="429")
                        import time as _t2
                        print(f"[OPTIONS-QUICK] {yf_sym} rate-limited, retrying once after 3s...")
                        _t2.sleep(3.0)
                        _yahoo_rate_wait()
                        try:
                            chain = tk.option_chain(opts[0])
                        except Exception as _chain_e2:
                            # Second failure also counts toward breaker
                            _err2 = str(_chain_e2)
                            if "Too Many" in _err2 or "429" in _err2 or "rate" in _err2.lower():
                                _cb_record_failure("yahoo_chain", reason="429_retry")
                            raise
                    else:
                        raise
                calls = chain.calls
                puts = chain.puts
                
                # r23: chain fetch succeeded — record breaker success
                if len(calls) > 0 or len(puts) > 0:
                    _cb_record_success("yahoo_chain")
                
                if spot <= 0 and len(calls) > 0:
                    # Estimate spot from chain midpoint
                    spot = float(calls['strike'].median())
                
                # Determine step size
                strikes_sorted = sorted(calls['strike'].unique())
                step = 1
                if len(strikes_sorted) >= 2:
                    diffs = [strikes_sorted[i+1] - strikes_sorted[i] for i in range(min(5, len(strikes_sorted)-1))]
                    step = round(min(diffs)) if diffs else 1
                if step <= 0:
                    step = 1
                
                atm_strike = round(spot / step) * step if step > 0 else spot
                
                # Build chain_near_atm (±5 strikes)
                for _, c in calls.iterrows():
                    if abs(c['strike'] - atm_strike) <= step * 5:
                        put_match = puts[puts['strike'] == c['strike']]
                        pe_oi = int(put_match['openInterest'].iloc[0]) if len(put_match) > 0 and 'openInterest' in put_match.columns and not _is_nan(put_match['openInterest'].iloc[0]) else 0
                        pe_iv = float(put_match['impliedVolatility'].iloc[0] * 100) if len(put_match) > 0 and 'impliedVolatility' in put_match.columns and not _is_nan(put_match['impliedVolatility'].iloc[0]) else 0
                        pe_ltp = float(put_match['lastPrice'].iloc[0]) if len(put_match) > 0 and not _is_nan(put_match['lastPrice'].iloc[0]) else 0
                        pe_bid = float(put_match['bid'].iloc[0]) if len(put_match) > 0 and 'bid' in put_match.columns and not _is_nan(put_match['bid'].iloc[0]) else 0
                        pe_ask = float(put_match['ask'].iloc[0]) if len(put_match) > 0 and 'ask' in put_match.columns and not _is_nan(put_match['ask'].iloc[0]) else 0
                        
                        ce_oi = int(c.get('openInterest', 0)) if not _is_nan(c.get('openInterest', 0)) else 0
                        ce_iv = float(c.get('impliedVolatility', 0) or 0) * 100
                        ce_ltp = float(c.get('lastPrice', 0) or 0)
                        ce_bid = float(c.get('bid', 0) or 0)
                        ce_ask = float(c.get('ask', 0) or 0)
                        
                        chain_data.append({
                            "strike": float(c['strike']),
                            "ce_oi": ce_oi, "pe_oi": pe_oi,
                            "ce_iv": round(ce_iv, 1), "pe_iv": round(pe_iv, 1),
                            "ce_ltp": round(ce_ltp, 2), "pe_ltp": round(pe_ltp, 2),
                            "ce_bid": round(ce_bid, 2), "pe_bid": round(pe_bid, 2),
                            "ce_ask": round(ce_ask, 2), "pe_ask": round(pe_ask, 2),
                            "ce_chg": 0, "pe_chg": 0
                        })
                        
                        if abs(c['strike'] - atm_strike) < step:
                            atm_iv = round(ce_iv, 1)
                
                # OI-based resistance/support
                call_oi_sorted = sorted(chain_data, key=lambda x: x['ce_oi'], reverse=True)
                put_oi_sorted = sorted(chain_data, key=lambda x: x['pe_oi'], reverse=True)
                ce_resistance = [{"strike": c['strike'], "oi": c['ce_oi'], "chg": 0} for c in call_oi_sorted[:3] if c['ce_oi'] > 0]
                pe_support = [{"strike": p['strike'], "oi": p['pe_oi'], "chg": 0} for p in put_oi_sorted[:3] if p['pe_oi'] > 0]
                
                # PCR
                total_ce_oi = sum(c['ce_oi'] for c in chain_data)
                total_pe_oi = sum(c['pe_oi'] for c in chain_data)
                pcr = round(total_pe_oi / max(total_ce_oi, 1), 2)
                
                # Max Pain (simplified)
                max_pain = atm_strike
                
        except Exception as e:
            print(f"[OPTIONS-QUICK] Chain fetch error for {yf_sym}: {e}")
        
        # VWAP estimate
        vwap = round((day_high + day_low + spot) / 3, 2) if spot > 0 else 0
        
        # ══════════════════════════════════════════════════════════════════
        # STRICT: if Yahoo returned spot but no option chain, we do NOT
        # fabricate ce_ltp/pe_ltp. A made-up premium corrupts SL, Target,
        # Trigger, R:R, Kelly sizing, and attribution — every number on the
        # trade card becomes a lie.
        #
        # r15: Before giving up, if we also lack spot (Yahoo fully failed),
        # try Google Finance as a spot-only fallback. The card will still
        # be non-tradable (_chain_unavailable: True), but at least users
        # see the current price instead of a card disappearing entirely.
        # ══════════════════════════════════════════════════════════════════
        _spot_source = "yahoo"  # default; will flip to "google_finance" if GF fallback used
        if region == 'US' and spot <= 0 and len(chain_data) == 0:
            try:
                gf_exchange = _gf_resolve_exchange(sym)
                gf_data = _gf_fetch_spot(sym, gf_exchange)
                if gf_data and gf_data.get("spot"):
                    spot = float(gf_data["spot"])
                    day_high = gf_data.get("day_high") or day_high or spot
                    day_low = gf_data.get("day_low") or day_low or spot
                    prev_close = gf_data.get("prev_close") or prev_close or spot
                    _spot_source = "google_finance"
                    print(f"[OPTIONS-QUICK] {sym}: Yahoo failed, Google Finance gave spot={spot}. No chain — card will be non-tradable.")
            except Exception as gfe:
                print(f"[OPTIONS-QUICK] {sym}: Google Finance fallback also failed: {gfe}")
        
        if spot > 0 and len(chain_data) == 0:
            print(f"[SYNTH-PREMIUM-BLOCKED] {sym}: spot={spot} from {_spot_source} but no option chain → non-tradable SPOT-ONLY card. Refusing to fabricate premiums.")
            return {
                "success": False,
                "error": "Option chain unavailable for " + sym + " — SPOT-ONLY mode",
                "symbol": sym,
                "spot": round(spot, 2),
                "region": region,
                "_chain_unavailable": True,
                "_spot_source": _spot_source,
                "ohlc_bars": [], "chain_near_atm": [], "ce_resistance": [], "pe_support": [],
                "gex": {"total": 0, "regime": "NEUTRAL", "topStrikes": [], "flipPoint": 0, "callWall": 0, "putWall": 0}
            }
        
        # Currency
        currency = '$' if region == 'US' else '₹'
        # Lot size: look up from ALGO_INSTRUMENTS, default 100 for US, 1 for unknown India stocks
        _algo_inst = ALGO_INSTRUMENTS.get(sym, {})
        lot_size = _algo_inst.get("lot", 100 if region == 'US' else 1)
        
        result = {
            "success": True if spot > 0 else False,
            "_fallback": True if spot > 0 and len(expiry_dates) == 0 else False,
            "symbol": sym,
            "region": region,
            "currency": currency,
            "lot_size": lot_size,
            "spot": round(spot, 2),
            "vix": round(vix, 1),
            "pcr": pcr,
            "max_pain": max_pain,
            "atm_iv": atm_iv,
            "vwap": vwap,
            "today_high": round(day_high, 2),
            "today_low": round(day_low, 2),
            "today_open": round(day_open, 2),
            "expiry": expiry_dates[0] if expiry_dates else "",
            "expiry_dates": expiry_dates,
            "chain_near_atm": chain_data,
            "ce_resistance": ce_resistance,
            "pe_support": pe_support,
            "total_ce_oi": sum(c['ce_oi'] for c in chain_data),
            "total_pe_oi": sum(c['pe_oi'] for c in chain_data),
            "ohlc_bars": [],  # Will be populated below if available
            "gex": {"total": 0, "regime": "NEUTRAL", "topStrikes": [], "flipPoint": max_pain, "callWall": ce_resistance[0]['strike'] if ce_resistance else 0, "putWall": pe_support[0]['strike'] if pe_support else 0},
            "pivot": vwap,
            "cpr_top": round(day_high * 0.998, 2),
            "cpr_bottom": round(day_low * 1.002, 2),
            "prev_close": round(prev_close, 2) if prev_close else round(spot * 0.998, 2),
        }
        
        # r25: Enrich Yahoo chain with Black-Scholes greeks + record ATM IV
        # to rolling buffer + compute long-gamma+cheap-IV signal. Same logic
        # as NSE path — signal is region-agnostic.
        try:
            from datetime import datetime as _dt2
            dte_days_us = 7
            if expiry_dates:
                try:
                    # Yahoo returns "2026-04-25" style
                    exp_dt = _dt2.strptime(expiry_dates[0], "%Y-%m-%d")
                    dte_days_us = max(0.1, (exp_dt - _dt2.utcnow()).total_seconds() / 86400.0)
                except Exception:
                    pass
            _enrich_chain_with_greeks(result.get("chain_near_atm") or [], spot, dte_days_us, region="US")
            _iv_history_record(sym, atm_iv)
            # Compute long-gamma signal (cheap IV + high gamma + delta 0.3-0.7)
            _lg = _long_gamma_signal(result.get("chain_near_atm") or [], atm_iv, sym, region="US")
            result["_long_gamma"] = _lg
        except Exception as _ge2:
            print(f"[GREEKS] ⚠️ Yahoo greeks enrich failed for {sym}: {type(_ge2).__name__}")
        
        # ═══ FETCH INTRADAY BARS (5-min) — OPTIONAL, non-critical ═══
        # Skip if we already used too many Yahoo calls (rate limit protection)
        try:
            _yahoo_rate_wait()
            hist_5m = tk.history(period='1d', interval='5m')
            if hist_5m is not None and len(hist_5m) > 0:
                ohlc_bars = []
                # Limit to last 30 bars to keep response size small
                for _, row in hist_5m.tail(30).iterrows():
                    ohlc_bars.append({
                        "t": str(row.name.time())[:5] if hasattr(row.name, 'time') else "",
                        "o": round(float(row['Open']), 2),
                        "h": round(float(row['High']), 2),
                        "l": round(float(row['Low']), 2),
                        "c": round(float(row['Close']), 2),
                        "v": int(row.get('Volume', 0))
                    })
                result["ohlc_bars"] = ohlc_bars
                # Recalculate VWAP from bars
                vwap_num = sum((b["h"]+b["l"]+b["c"])/3 * b["v"] for b in ohlc_bars if b["v"] > 0)
                vwap_den = sum(b["v"] for b in ohlc_bars if b["v"] > 0)
                if vwap_den > 0:
                    result["vwap"] = round(vwap_num / vwap_den, 2)
                print(f"[OPTIONS-QUICK] ✅ {sym} bars: {len(ohlc_bars)}")
        except Exception as bar_err:
            print(f"[OPTIONS-QUICK] ⚠️ Bars skipped for {yf_sym}: {bar_err}")
        
        # ═══ DAILY TREND DATA — SMA 200/400 + EMA 9/21 for Trend Compass ═══
        try:
            _yahoo_rate_wait()
            hist_daily = tk.history(period='2y', interval='1d')
            if hist_daily is not None and len(hist_daily) >= 5:
                closes = [float(r['Close']) for _, r in hist_daily.iterrows()]
                
                # SMA calculation
                def _sma(data, period):
                    if len(data) < period: return 0
                    return round(sum(data[-period:]) / period, 2)
                
                # EMA calculation
                def _ema(data, period):
                    if len(data) < period: return 0
                    k = 2 / (period + 1)
                    ema = sum(data[:period]) / period
                    for p in data[period:]:
                        ema = p * k + ema * (1 - k)
                    return round(ema, 2)
                
                sma200 = _sma(closes, 200)
                sma400 = _sma(closes, 400)
                ema9 = _ema(closes, 9)
                ema21 = _ema(closes, 21)
                ema5 = _ema(closes, 5)
                ema13 = _ema(closes, 13)
                ema26 = _ema(closes, 26) if len(closes) >= 26 else 0
                
                # Daily trend: bullish if price above SMA200 and EMA5 > EMA13
                daily_trend = 'NEUTRAL'
                if closes[-1] > sma200 and ema5 > ema13:
                    daily_trend = 'BULLISH'
                elif closes[-1] < sma200 and ema5 < ema13:
                    daily_trend = 'BEARISH'
                elif closes[-1] > sma200:
                    daily_trend = 'BULLISH'
                elif closes[-1] < sma200:
                    daily_trend = 'BEARISH'
                
                # Recent momentum: last 5 days
                _d5_change = round((closes[-1] - closes[-6]) / closes[-6] * 100, 2) if len(closes) >= 6 else 0
                
                result["daily_trend"] = {
                    "trend": daily_trend,
                    "sma200": sma200,
                    "sma400": sma400,
                    "ema9": ema9,
                    "ema21": ema21,
                    "ema5": ema5,
                    "ema13": ema13,
                    "ema26": ema26,
                    "d5_change": _d5_change,
                    "days": len(closes)
                }
                print(f"[OPTIONS-QUICK] ✅ {sym} trend: {daily_trend} SMA200={sma200} SMA400={sma400} EMA9={ema9} EMA21={ema21}")
        except Exception as dt_err:
            print(f"[OPTIONS-QUICK] ⚠️ Daily trend skipped for {sym}: {dt_err}")
        
        # ═══ US MARKET IMPACT — For India tickers, show how US markets are doing ═══
        if region == 'IN':
            try:
                _yahoo_rate_wait()
                import yfinance as yf
                _sp500 = yf.Ticker("^GSPC")
                _sp_hist = _sp500.history(period='5d')
                if _sp_hist is not None and len(_sp_hist) >= 2:
                    _sp_last = float(_sp_hist['Close'].iloc[-1])
                    _sp_prev = float(_sp_hist['Close'].iloc[-2])
                    _sp_chg = round((_sp_last - _sp_prev) / _sp_prev * 100, 2)
                    _sp_5d = round((_sp_last - float(_sp_hist['Close'].iloc[0])) / float(_sp_hist['Close'].iloc[0]) * 100, 2) if len(_sp_hist) >= 5 else _sp_chg
                    
                    result["us_market"] = {
                        "sp500": round(_sp_last, 2),
                        "sp500_chg": _sp_chg,
                        "sp500_5d": _sp_5d,
                        "impact": "POSITIVE" if _sp_chg > 0.3 else "NEGATIVE" if _sp_chg < -0.3 else "NEUTRAL",
                        "detail": f"S&P 500 at {_sp_last:.0f} ({'+'if _sp_chg>0 else ''}{_sp_chg}% last session, {'+'if _sp_5d>0 else ''}{_sp_5d}% 5-day)"
                    }
                    print(f"[OPTIONS-QUICK] ✅ US market impact: S&P {_sp_last:.0f} ({_sp_chg:+.2f}%)")
            except Exception as us_err:
                print(f"[OPTIONS-QUICK] ⚠️ US market data skipped: {us_err}")
        
        print(f"[OPTIONS-QUICK] ✅ {sym} ({region}): spot={spot}, chain={len(chain_data)}, bars={len(result.get('ohlc_bars', []))}")
        return result
        
    except Exception as e:
        print(f"[OPTIONS-QUICK] ❌ Error for {symbol}: {e}")
        import traceback; traceback.print_exc()
        return {"success": False, "error": str(e), "spot": 0, "ohlc_bars": [], "chain_near_atm": [], "ce_resistance": [], "pe_support": [], "gex": {"total": 0, "regime": "NEUTRAL", "topStrikes": [], "flipPoint": 0, "callWall": 0, "putWall": 0}}


# ═══════════════════════════════════════════════════════════════
# SWING TRADING ENGINE — Positional Analysis (Days-Weeks)
# Institutional: Daily/Weekly Structure, Trend, Accumulation
# ═══════════════════════════════════════════════════════════════

@app.get("/api/swing-analysis")
async def swing_analysis(symbol: str = "RELIANCE", region: str = "IN"):
    """Swing Trading Engine — uses daily/weekly data for positional decisions"""
    try:
        sym = symbol.upper().strip()
        reg = region.upper().strip()
        
        import yfinance as yf
        _yahoo_rate_wait()
        
        # Determine yfinance ticker
        india_index_map = {"NIFTY": "^NSEI", "BANKNIFTY": "^NSEBANK", "SENSEX": "^BSESN", "FINNIFTY": "^CNXFIN", "MIDCPNIFTY": "^NSEI"}
        yf_sym = india_index_map.get(sym, sym)
        if yf_sym == sym and reg == 'IN' and not sym.endswith('.NS') and not sym.startswith('^'):
            yf_sym = sym + '.NS'
        
        tk = yf.Ticker(yf_sym)
        
        # ─── DAILY DATA (3 months) ───
        daily = tk.history(period='3mo', interval='1d')
        if len(daily) < 10:
            return {"success": False, "error": f"Insufficient daily data for {sym}"}
        
        spot = float(daily['Close'].iloc[-1])
        if hasattr(spot, 'item'): spot = spot.item()  # numpy → python
        prev = float(daily['Close'].iloc[-2]) if len(daily) > 1 else spot
        
        # ─── WEEKLY DATA (1 year) ───
        weekly = tk.history(period='1y', interval='1wk')
        
        # ─── TREND ANALYSIS (HH/HL pattern) ───
        closes = daily['Close'].values
        highs = daily['High'].values
        lows = daily['Low'].values
        volumes = daily['Volume'].values
        
        # Find swing highs and lows (last 20 days)
        swing_highs = []
        swing_lows = []
        for i in range(2, min(len(highs)-1, 20)):
            if highs[-(i+1)] > highs[-(i)] and highs[-(i+1)] > highs[-(i+2)]:
                swing_highs.append(float(highs[-(i+1)]))
            if lows[-(i+1)] < lows[-(i)] and lows[-(i+1)] < lows[-(i+2)]:
                swing_lows.append(float(lows[-(i+1)]))
        
        # Trend: HH+HL = uptrend, LH+LL = downtrend
        trend = 'SIDEWAYS'
        trend_strength = 0
        if len(swing_highs) >= 2 and len(swing_lows) >= 2:
            hh = bool(swing_highs[0] > swing_highs[1])  # Higher high
            hl = bool(swing_lows[0] > swing_lows[1])     # Higher low
            lh = bool(swing_highs[0] < swing_highs[1])   # Lower high
            ll = bool(swing_lows[0] < swing_lows[1])      # Lower low
            if hh and hl:
                trend = 'UPTREND'
                trend_strength = 2
            elif lh and ll:
                trend = 'DOWNTREND'
                trend_strength = 2
            elif hh or hl:
                trend = 'UPTREND'
                trend_strength = 1
            elif lh or ll:
                trend = 'DOWNTREND'
                trend_strength = 1
        
        # ─── MOVING AVERAGES ───
        ema20 = float(daily['Close'].ewm(span=20).mean().iloc[-1])
        ema50 = float(daily['Close'].ewm(span=50).mean().iloc[-1]) if len(daily) >= 50 else ema20
        sma200 = float(daily['Close'].rolling(200).mean().iloc[-1]) if len(daily) >= 200 else ema50
        
        ma_bullish = bool(spot > ema20) and bool(ema20 > ema50)
        ma_bearish = bool(spot < ema20) and bool(ema20 < ema50)
        
        # ─── SUPPORT / RESISTANCE ZONES ───
        recent_high = float(highs[-20:].max())
        recent_low = float(lows[-20:].min())
        
        # Weekly S/R
        weekly_high = float(weekly['High'].iloc[-4:].max()) if len(weekly) >= 4 else recent_high
        weekly_low = float(weekly['Low'].iloc[-4:].min()) if len(weekly) >= 4 else recent_low
        
        # Key levels
        support = round(recent_low, 2)
        resistance = round(recent_high, 2)
        
        # ─── VOLUME ANALYSIS ───
        avg_vol_20 = float(volumes[-20:].mean()) if len(volumes) >= 20 else float(volumes.mean())
        recent_vol = float(volumes[-3:].mean())
        vol_expansion = bool(recent_vol > avg_vol_20 * 1.3)
        vol_ratio = round(recent_vol / max(avg_vol_20, 1), 2)
        
        # ─── ACCUMULATION / DISTRIBUTION ───
        # Rising price + rising volume = accumulation
        price_change_5d = (closes[-1] - closes[-6]) / closes[-6] * 100 if len(closes) > 5 else 0
        vol_change_5d = (float(volumes[-3:].mean()) - float(volumes[-8:-3].mean())) / max(float(volumes[-8:-3].mean()), 1) * 100 if len(volumes) > 8 else 0
        
        accumulating = bool(price_change_5d > 0) and bool(vol_change_5d > 10)
        distributing = bool(price_change_5d < 0) and bool(vol_change_5d > 10)
        
        # ─── RSI (14-day) ───
        deltas = [closes[i] - closes[i-1] for i in range(1, len(closes))]
        gains = [d if d > 0 else 0 for d in deltas[-14:]]
        losses = [-d if d < 0 else 0 for d in deltas[-14:]]
        avg_gain = sum(gains) / 14
        avg_loss = sum(losses) / 14
        rsi = 100 - (100 / (1 + avg_gain / max(avg_loss, 0.001)))
        rsi = round(rsi, 1)
        
        # ─── CONSOLIDATION DETECTION ───
        range_20 = (recent_high - recent_low) / spot * 100
        is_consolidating = bool(range_20 < 8)  # Less than 8% range = tight
        
        # ─── BREAKOUT DETECTION ───
        broke_resistance = bool(spot > resistance * 0.99) and vol_expansion
        broke_support = bool(spot < support * 1.01) and vol_expansion
        
        # ─── PULLBACK DETECTION ───
        pullback_to_ema = trend == 'UPTREND' and bool(abs(spot - ema20) / max(spot, 1) < 0.02)
        
        # ═══ SWING DECISION ENGINE (3 Rules) ═══
        
        # RULE 1: Trend Structure (HH/HL or LH/LL)
        rule1_trend = trend != 'SIDEWAYS'
        
        # RULE 2: Volume Confirms (accumulation or distribution)
        rule2_volume = vol_expansion or accumulating or distributing
        
        # RULE 3: Entry Trigger (breakout, pullback, or accumulation zone)
        rule3_trigger = broke_resistance or broke_support or pullback_to_ema
        
        # Direction
        direction = 'NONE'
        if trend == 'UPTREND' and (broke_resistance or pullback_to_ema or (ma_bullish and accumulating)):
            direction = 'BULLISH'
        elif trend == 'DOWNTREND' and (broke_support or (ma_bearish and distributing)):
            direction = 'BEARISH'
        elif ma_bullish and accumulating:
            direction = 'BULLISH'
        elif ma_bearish and distributing:
            direction = 'BEARISH'
        
        # Final verdict
        rules_pass = (1 if rule1_trend else 0) + (1 if rule2_volume else 0) + (1 if rule3_trigger else 0)
        
        verdict = 'NO TRADE'
        if rules_pass >= 3:
            verdict = 'BUY' if direction == 'BULLISH' else ('SELL' if direction == 'BEARISH' else 'NO TRADE')
        elif rules_pass == 2 and direction != 'NONE':
            verdict = 'WATCH — Almost ready'
        
        # WHY reasons
        why = []
        if rule1_trend:
            why.append({"pass": True, "label": f"{trend} — {'Higher highs + higher lows' if trend=='UPTREND' else 'Lower highs + lower lows'}"})
        else:
            why.append({"pass": False, "label": "No clear trend — sideways"})
        
        if rule2_volume:
            if accumulating:
                why.append({"pass": True, "label": f"Accumulation — volume up {vol_ratio}x"})
            elif distributing:
                why.append({"pass": True, "label": f"Distribution — volume up {vol_ratio}x"})
            else:
                why.append({"pass": True, "label": f"Volume expanding — {vol_ratio}x average"})
        else:
            why.append({"pass": False, "label": f"Low volume — {vol_ratio}x average"})
        
        if broke_resistance:
            why.append({"pass": True, "label": f"Breakout above {resistance}"})
        elif broke_support:
            why.append({"pass": True, "label": f"Breakdown below {support}"})
        elif pullback_to_ema:
            why.append({"pass": True, "label": "Pullback to 20 EMA in uptrend"})
        elif is_consolidating:
            why.append({"pass": False, "label": f"Consolidating — range only {range_20:.1f}%"})
        else:
            why.append({"pass": False, "label": "No clear entry trigger"})
        
        # Entry/Target/SL
        entry_level = round(resistance, 2) if direction == 'BULLISH' else round(support, 2)
        target = round(spot * 1.08, 2) if direction == 'BULLISH' else round(spot * 0.92, 2)
        stop_loss = round(spot * 0.95, 2) if direction == 'BULLISH' else round(spot * 1.05, 2)
        
        # Direction label
        dir_label = 'SIDEWAYS — No momentum'
        if direction == 'BULLISH':
            dir_label = 'BULLISH ↑' if trend == 'UPTREND' else 'LEANING BULLISH ↑'
        elif direction == 'BEARISH':
            dir_label = 'BEARISH ↓' if trend == 'DOWNTREND' else 'LEANING BEARISH ↓'
        
        print(f"[SWING] ✅ {sym}: spot={spot}, trend={trend}, verdict={verdict}, dir={direction}")
        
        # Sanitize numpy types for JSON serialization
        def _native(v):
            """Convert numpy types to Python native"""
            if hasattr(v, 'item'):
                return v.item()
            return v
        
        ma_bullish = bool(ma_bullish)
        ma_bearish = bool(ma_bearish)
        vol_expansion = bool(vol_expansion)
        accumulating = bool(accumulating)
        distributing = bool(distributing)
        is_consolidating = bool(is_consolidating)
        broke_resistance = bool(broke_resistance)
        broke_support = bool(broke_support)
        pullback_to_ema = bool(pullback_to_ema)
        spot = float(spot)
        prev = float(prev)
        ema20 = float(ema20)
        ema50 = float(ema50)
        sma200 = float(sma200)
        rsi = float(rsi)
        support = float(support)
        resistance = float(resistance)
        weekly_high = float(weekly_high)
        weekly_low = float(weekly_low)
        avg_vol_20 = float(avg_vol_20)
        recent_vol = float(recent_vol)
        vol_ratio = float(vol_ratio)
        price_change_5d = float(price_change_5d)
        range_20 = float(range_20)
        
        return {
            "success": True,
            "symbol": sym,
            "region": reg,
            "spot": round(spot, 2),
            "prev_close": round(prev, 2),
            "change_pct": round((spot - prev) / prev * 100, 2),
            "trend": trend,
            "trend_strength": trend_strength,
            "direction": direction,
            "direction_label": dir_label,
            "verdict": verdict,
            "rules_pass": rules_pass,
            "why": why,
            "ema20": round(ema20, 2),
            "ema50": round(ema50, 2),
            "sma200": round(sma200, 2),
            "ma_bullish": ma_bullish,
            "rsi": rsi,
            "support": support,
            "resistance": resistance,
            "weekly_high": round(weekly_high, 2),
            "weekly_low": round(weekly_low, 2),
            "vol_ratio": vol_ratio,
            "vol_expansion": vol_expansion,
            "accumulating": accumulating,
            "distributing": distributing,
            "is_consolidating": is_consolidating,
            "range_pct": round(range_20, 1),
            "broke_resistance": broke_resistance,
            "broke_support": broke_support,
            "pullback_to_ema": pullback_to_ema,
            "entry_level": entry_level,
            "target": target,
            "stop_loss": stop_loss,
            "price_change_5d": round(price_change_5d, 2),
            "currency": '$' if reg == 'US' else '₹'
        }
        
    except Exception as e:
        print(f"[SWING] ❌ Error for {symbol}: {e}")
        import traceback; traceback.print_exc()
        return {"success": False, "error": str(e)}
